// ─── RECENT ADDRESSES ────────────────────────────────────────────────────────
const RECENT_ADDRS_KEY = 'hliq_recent_addrs'
const MAX_RECENT       = 5

function pushRecentAddr(addr) {
  let recent = []
  try { recent = JSON.parse(localStorage.getItem(RECENT_ADDRS_KEY)) || [] } catch {}
  recent = [addr, ...recent.filter(a => a.toLowerCase() !== addr.toLowerCase())].slice(0, MAX_RECENT)
  localStorage.setItem(RECENT_ADDRS_KEY, JSON.stringify(recent))
  renderRecentAddrs()
}

function renderRecentAddrs() {
  const el = document.getElementById('recentAddrsRow')
  if (!el) return
  let recent = []
  try { recent = JSON.parse(localStorage.getItem(RECENT_ADDRS_KEY)) || [] } catch {}
  if (!recent.length) { el.innerHTML = ''; return }
  el.innerHTML = `
    <div class="recent-addrs-row">
      <span class="recent-addrs-label">Recent</span>
      ${recent.map(a => {
        const label = WM.getLabel(a)
        const short = a.slice(0, 6) + '…' + a.slice(-4)
        return `<button class="btn-recent-addr" title="${esc(a)}"
          onclick="window.__quickLoad('${esc(a)}')">${esc(label || short)}</button>`
      }).join('')}
    </div>`
}

// ─── i18n ─────────────────────────────────────────────────────────────────────
// Only two languages: English (source) and Spanish. Translation is a hand-curated
// dictionary (src/i18n-es.js) — no network, no Google, no per-language cache fetch.
const _LANG_NAMES = { en:'English', es:'Español' }
const _xlLang = l => l   // cache is keyed by the bare code ('es')
// Source-level bilingual picker for prose blocks too formatted (inline <b>) for the DOM
// dictionary — mirrors onboard.js's T(). Reads the live language.
const _T = (en, es) => _currentLang === 'es' ? es : en
let _i18nCache  = {}
let _currentLang = 'en'
const _origNodes = new Map()   // textNode → original full textContent

// Every language switch bumps this. Any async work (a fetch mid-switch, a queued observer
// flush) captures the token and aborts if it's since changed — so a slow translation for an
// OLD language can never land after you've already switched to a new one. That stale-apply
// race is what left the UI in one language while the chip showed another.
let _i18nSwitchToken = 0

// Incremental auto-translate observer: keeps translation "sticky" without re-walking the
// whole page. When new DOM is added (a background repaint, the watchlist rotator, or an
// overlay like Help & Learn / Security & Keys), we translate ONLY those new subtrees.
//
// The apply is SYNCHRONOUS and dictionary-only, done inside the observer callback.
// MutationObserver callbacks run as microtasks — AFTER the render that added the English
// nodes, but BEFORE the browser paints. So dictionary strings are swapped to Spanish before
// any English frame is shown: no flicker. Strings not in the dictionary simply stay English
// (no network, nothing queued) — there's no async pass anymore.
let _i18nObserver = null
function _i18nStartObserver() {
  if (_i18nObserver || typeof MutationObserver === 'undefined') return
  _i18nObserver = new MutationObserver(muts => {
    if (_currentLang === 'en') return
    const roots = []
    for (const m of muts) {
      for (const n of m.addedNodes) {
        if (n.nodeType === 1 || n.nodeType === 3) roots.push(n)
      }
    }
    if (!roots.length) return
    _i18nApplyCachedSync(roots.filter(n => n.isConnected), _currentLang)
  })
  _i18nObserver.observe(document.body, { childList: true, subtree: true })
}
function _i18nStopObserver() {
  _i18nObserver?.disconnect(); _i18nObserver = null
}
// One-shot re-apply for callers that inject overlays synchronously (dictionary-only).
window.__i18nApply = () => {
  if (_currentLang === 'en') return
  _i18nApplyCachedSync([document.body], _currentLang)
}

function _i18nLoadCache() {
  // The cache IS the bundled dictionary now — no localStorage, no fetch. Missing strings
  // simply stay English. (Old 'hliq_i18n_g' / 'hliq_i18n_seen' keys are abandoned.)
  _i18nCache = { es: ES_DICT }
}

// Record the English originals under a root into the seen-set (runs even in English, so normal
// browsing builds the set that a later switch pre-warms from).
function _i18nHarvest(_root) { /* no-op: dictionary is bundled, nothing to harvest */ }
// No-op: every translation is already bundled, so there's nothing to pre-warm.
function _i18nPrewarm(_lang) {}

function _i18nShouldSkip(text) {
  if (!text || text.length < 2) return true
  // pure numbers / symbols / prices / tickers
  if (/^[\d\s$%+\-.,/:°()\[\]{}~*@#^&|<>]+$/.test(text)) return true
  if (/^0x[0-9a-fA-F]{6,}/.test(text)) return true       // wallet addresses
  if (/^[A-Z][A-Z0-9]{1,5}(-[A-Z0-9]+)?$/.test(text)) return true  // BTC, ETH-PERP
  if (/^\$?[\d,]+\.?\d*[kKmMbB%]?$/.test(text)) return true         // $1,234 / 5.6k
  if (/^\d+[dhms]\s/.test(text)) return true                         // 5d 3h countdown
  return false
}

// No-op: translations come from the bundled dictionary, never the network. Kept as an
// async stub so existing `await _i18nBatchFetch(...)` call sites need no change.
async function _i18nBatchFetch(_texts, _lang) {}

// Gather translatable text nodes under a set of roots (elements or text nodes).
function _i18nGatherNodes(roots) {
  const out = []
  const accept = node => {
    const tag = node.parentElement?.tagName
    if (!tag || ['SCRIPT','STYLE','INPUT','TEXTAREA','CANVAS'].includes(tag)) return false
    // skip elements that update every second (prices, countdowns) and any opted-out subtree —
    // .notranslate / translate="no" mark user data (account/wallet names) that must stay verbatim.
    if (node.parentElement?.closest('.oc-countdown, .topbar-price, .pos-liq, [id^="oc-cd-"], [id^="oc-chance-"], .notranslate, [translate="no"]')) return false
    const text = (_origNodes.get(node) ?? node.textContent).trim()
    return !_i18nShouldSkip(text)
  }
  for (const root of roots) {
    if (root.nodeType === 3) { if (accept(root)) out.push(root); continue }
    if (root.nodeType !== 1) continue
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: n => accept(n) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT
    })
    let n; while (n = walker.nextNode()) out.push(n)
  }
  return out
}

// Synchronous, cache-only apply. Swaps every already-cached string under `roots` to `lang`
// right now (no fetch, no await) so it can run inside the observer microtask before paint.
// Returns true if any string was NOT cached (caller should fetch), false if fully applied.
// Look up a translation for `s` in `cache`. Exact match first; then a fallback for a leading
// decoration (emoji / arrow / star / bullet + space) followed by a translatable phrase — so a
// button like "🏆 Paper Challenge", "↓ Save Image" or "★ Favs" reuses the plain key ("Paper
// Challenge", "Save Image", "Favs") and keeps its symbol. Returns the translated string or null.
const _I18N_DECOR = /^([^\p{L}\p{N}\s]+\s+)(\p{L}[\s\S]*)$/u
function _i18nLookup(cache, s) {
  const t = cache[s]
  if (t && t !== s) return t
  const m = s.match(_I18N_DECOR)
  if (m && /[^\x00-\x7F]/.test(m[1])) {   // only strip a genuine symbol/emoji prefix, not "$"/"-"
    const rt = cache[m[2]]
    if (rt && rt !== m[2]) return m[1] + rt
  }
  return null
}
function _i18nApplyCachedSync(roots, lang) {
  if (lang === 'en') return false
  const L = _xlLang(lang)
  const cache = _i18nCache[L] || {}
  const nodes = _i18nGatherNodes(roots)
  let missed = false
  for (const node of nodes) {
    if (!node.isConnected) continue
    const origFull = _origNodes.get(node) ?? node.textContent
    const origTrim = origFull.trim()
    if (_i18nShouldSkip(origTrim)) continue
    const t = _i18nLookup(cache, origTrim)
    if (t) {
      if (!_origNodes.has(node)) _origNodes.set(node, origFull)
      const next = origFull.replace(origTrim, t)
      if (node.textContent !== next) node.textContent = next
    } else {
      missed = true
    }
  }
  return missed
}

// Translate the text nodes under the given roots to `lang` — fetch anything uncached, then
// apply. Token-guarded so a slow fetch for a superseded language never writes stale text.
async function _translateNodesUnder(roots, lang) {
  if (lang === 'en') return
  _i18nStartObserver()
  const tok = _i18nSwitchToken
  const nodes = _i18nGatherNodes(roots)
  if (!nodes.length) return
  const unique = [...new Set(nodes.map(n => (_origNodes.get(n) ?? n.textContent).trim()).filter(t => !_i18nShouldSkip(t)))]
  await _i18nBatchFetch(unique, lang)
  if (tok !== _i18nSwitchToken) return   // a newer switch happened while fetching — abandon
  const L = _xlLang(lang)
  for (const node of nodes) {
    if (!node.isConnected) continue
    const origFull = _origNodes.get(node) ?? node.textContent
    const origTrim = origFull.trim()
    const t = _i18nLookup(_i18nCache[L] || {}, origTrim)
    if (!t) continue
    if (!_origNodes.has(node)) _origNodes.set(node, origFull)
    node.textContent = origFull.replace(origTrim, t)
  }
}

async function _translateDOM(lang) {
  if (lang === 'en') {
    _i18nStopObserver()
    for (const [node, orig] of _origNodes) { if (node.isConnected) node.textContent = orig }
    _origNodes.clear()
    return
  }
  await _translateNodesUnder([document.body], lang)
}

// The single entry point for a language change — used by both desktop and mobile. Bumping the
// token first cancels any in-flight translation for the previous language, and we set state +
// chip highlight synchronously so `_currentLang` and what's on screen can never disagree.
async function _applyLang(lang) {
  if (lang !== 'es') lang = 'en'   // only en/es now; coerce any stale saved code (fr/de/…) to English
  _i18nSwitchToken++
  if (lang === 'en') _i18nStopObserver()   // stop the observer BEFORE restoring, so its flush can't re-translate
  _currentLang = lang
  localStorage.setItem('hliq_lang', lang)
  document.documentElement.lang = lang
  document.querySelectorAll('.lang-chip').forEach(b => b.classList.toggle('active', b.dataset.lang === lang))
  const nameEl = document.getElementById('langCurrentName')
  if (nameEl) nameEl.textContent = _LANG_NAMES[lang] || lang
  _i18nPrewarm(lang)          // warm the cache for every seen string, in the background
  await _translateDOM(lang)
}

window.__setLang = function(lang) { _applyLang(lang) }

// Mobile settings language switch. Re-render the settings body first (so the selected chip
// highlights immediately), then translate. Token-guarding + the incremental observer make a
// single press land reliably and stay put as the screen live-updates.
window.__setLangMob = async function(lang) {
  if (lang !== 'es') lang = 'en'   // only en/es now; coerce any stale saved code to English
  _i18nSwitchToken++
  _currentLang = lang
  localStorage.setItem('hliq_lang', lang)
  document.documentElement.lang = lang
  if (lang === 'en') _i18nStopObserver()
  _i18nPrewarm(lang)          // warm the cache for every seen string, in the background
  _mobVRenderContent()
  await _translateDOM(lang)
}

// ─── WALLET MANAGER ──────────────────────────────────────────────────────────
const WM = {
  load()              { return JSON.parse(localStorage.getItem('savedWallets') || '[]') },
  save(list)          {
    localStorage.setItem('savedWallets', JSON.stringify(list))
    // The cached All Accounts snapshot describes the OLD wallet set (and labels),
    // so drop it rather than paint stale totals on the next open.
    try { localStorage.removeItem('hliq_allacct_v1'); _allAcctLastPersist = 0 } catch {}
    // Wallet list changed — re-sync the push subscription so removed
    // accounts stop alerting and new ones start (no-op if notifs are off)
    try { _registerPushDebounced() } catch {}
  },
  getLabel(addr)      { return this.load().find(w => w.addr === addr)?.label ?? null },
  upsert(addr, label) {
    const list = this.load()
    const ex   = list.find(w => w.addr === addr)
    if (ex) ex.label = label; else list.push({ addr, label })
    this.save(list)
  },
  remove(addr) { this.save(this.load().filter(w => w.addr !== addr)) },
}

function renderSavedWallets() {
  const el = document.getElementById('savedWalletsRow')
  if (!el) return
  const list = WM.load()
  if (!list.length) { el.innerHTML = ''; return }
  el.innerHTML = `
    <div class="saved-wallets-row">
      <span class="saved-wallets-label">Saved wallets</span>
      ${list.map(w => `
        <button class="btn-wallet-chip notranslate" onclick="window.__quickLoad('${esc(w.addr)}')">
          ${esc(w.label)}
        </button>
        <button class="btn-wallet-chip-del" title="Remove" onclick="window.__removeWallet('${esc(w.addr)}')">✕</button>
      `).join('')}
    </div>`
}

function renderWalletStrip(addr) {
  const el = document.getElementById('walletStrip')
  if (!el) return
  const _chalCur = addr === PAPER_ADDR && paperSlot() === 'challenge'
  const short   = addr === '__all_accounts__'
    ? _maLoad().length + ' wallets combined'
    : addr === PAPER_ADDR ? (_chalCur ? 'Challenge · $1,000 paper' : 'Paper · simulated funds, no real orders')
    : addr.slice(0, 8) + '...' + addr.slice(-6)
  const label   = addr === '__all_accounts__' ? 'All Accounts'
    : addr === PAPER_ADDR ? (_paperName() + (_chalCur ? ' (Challenge)' : '')) : WM.getLabel(addr)
  const list    = WM.load()
  const isSaved = (addr === '__all_accounts__' || addr === PAPER_ADDR) ? true : !!label
  const subs    = state.subAccounts ?? []

  const totalAccounts = list.length + subs.length
  const badgeHtml     = totalAccounts > 0 ? `<span class="ws-count">${totalAccounts}</span>` : ''

  // ── Saved wallet rows ──
  const walletRowsHtml = list.map(w => {
    const isCurrent = w.addr.toLowerCase() === addr.toLowerCase()
    const wShort    = w.addr.slice(0, 8) + '...' + w.addr.slice(-6)
    return `
      <div class="ws-wallet-row${isCurrent ? ' ws-wallet-current' : ''}"
           data-ws-addr="${esc(w.addr)}"
           onclick="window.__switchWallet('${esc(w.addr)}')">
        <div class="ws-wallet-row-info">
          <span class="ws-wallet-row-name notranslate">${esc(w.label)}</span>
          <span class="ws-wallet-row-addr">${wShort}</span>
        </div>
        <div class="ws-wallet-row-acts" onclick="event.stopPropagation()">
          <button class="ws-row-btn"     title="Rename" onclick="window.__panelRename('${esc(w.addr)}')">✎</button>
          <button class="ws-row-btn del" title="Remove" onclick="window.__panelRemove('${esc(w.addr)}')">✕</button>
        </div>
      </div>`
  }).join('')

  // ── Sub-accounts section ──
  const subsHtml = subs.length ? `
    <div class="ws-panel-divider"></div>
    <div class="ws-panel-section">
      <div class="ws-panel-section-label">Sub-accounts</div>
      <div class="ws-sub-pills">
        ${subs.map(s => {
          const subShort = s.subAccountUser.slice(0, 6) + '…' + s.subAccountUser.slice(-4)
          const isActive = s.subAccountUser.toLowerCase() === addr.toLowerCase()
          return `<button class="ws-sub-pill${isActive ? ' active-sub' : ''}"
            onclick="window.__quickLoad('${esc(s.subAccountUser)}')">
            ${esc(s.name || subShort)}
          </button>`
        }).join('')}
      </div>
    </div>` : ''

  // ── Save unsaved wallet ──
  const saveRowHtml = !isSaved ? `
    <div class="ws-panel-divider"></div>
    <div class="ws-panel-save-row">
      <input class="ws-panel-input" id="wsPanelNameInput" placeholder="Name this wallet…"
        onkeydown="if(event.key==='Enter')window.__panelSave()" />
      <button class="ws-panel-save-btn" onclick="window.__panelSave()">Save</button>
    </div>` : ''

  el.innerHTML = `
    <div class="ws-bar">
      <div class="ws-identity">
        ${label ? `<div class="ws-name">${esc(label)}</div>` : ''}
        <div class="ws-addr"><span>${short}</span></div>
      </div>

      <div class="ws-actions">
        <div class="ws-switcher-wrap" id="wsSwitcherWrap">
          <button class="ws-switcher-btn" id="wsSwitcherBtn" onclick="window.__toggleWalletPanel()">
            Accounts ${badgeHtml} <span class="ws-chevron">▾</span>
          </button>
          <div class="ws-panel" id="wsPanel">
            ${list.length > 1 ? `
              <div class="ws-panel-section">
                <button class="ws-all-accounts-btn"
                  onclick="window.__toggleWalletPanel();window.__goAllAccounts()">
                  ⊕ All Accounts Combined
                </button>
              </div>` : ''}
            <div class="ws-panel-section">
              ${paperAccounts().map((a, i) => `<button class="ws-all-accounts-btn" style="color:#ff9f43${i ? ';margin-top:6px' : ''}"
                onclick="window.__toggleWalletPanel();window.__goPaper('${esc(a.slot)}')">
                📝 ${esc(_paperName(a.slot))} <span style="opacity:.6">· Paper</span>
              </button>`).join('')}
              <button class="ws-all-accounts-btn" style="color:var(--fg-2);margin-top:6px"
                onclick="window.__paperAcctNew()">
                ＋ New paper account <span style="opacity:.6">· separate $${PAPER_START.toLocaleString()}</span>
              </button>
              ${_chalActive() ? `<button class="ws-all-accounts-btn" style="color:#f5c518;margin-top:6px"
                onclick="window.__toggleWalletPanel();window.__goPaper('challenge')">
                🏆 ${esc(_paperName())} (Challenge) <span style="opacity:.6">· $1,000</span>
              </button>` : ''}
              ${addr === PAPER_ADDR ? `
                <div style="display:flex;gap:6px;margin-top:6px">
                  <button class="ws-btn" style="flex:1" onclick="window.__paperRename()">✎ Rename</button>
                  <button class="ws-btn" style="flex:1" onclick="window.__paperResetAcct()">↺ Reset</button>
                  ${paperSlot() !== 'main' && paperSlot() !== 'challenge'
                    ? `<button class="ws-btn" style="flex:1" onclick="window.__paperAcctDelete('${esc(paperSlot())}')">🗑 Delete</button>` : ''}
                </div>` : ''}
            </div>
            ${list.length ? `
              <div class="ws-panel-section">
                <div class="ws-panel-section-label">Saved Wallets</div>
                ${walletRowsHtml}
              </div>` : ''}
            ${saveRowHtml}
            ${subsHtml}
          </div>
        </div>
        <button class="ws-btn ws-retry-btn" id="wsRetryBtn" onclick="window.__retryRefresh()" title="Force reload all data"><span class="ws-retry-icon">↺</span> Reload</button>
        <button class="ws-btn" onclick="downloadJSON()">⬇ JSON</button>
        <button class="ws-btn" onclick="downloadCSV()">⬇ CSV</button>
        <button class="ws-btn" onclick="resetDashboard()">← New</button>
      </div>
    </div>`
}

window.__quickLoad = function(addr) {
  document.getElementById('walletInput').value = addr
  loadDashboard()
}
window.__switchWallet = function(addr) {
  if (!addr) return
  document.getElementById('walletInput').value = addr
  loadDashboard()
}
// ── Wallet panel actions ──────────────────────────────────────────────────────
function _positionWsPanel() {
  const btn   = document.getElementById('wsSwitcherBtn')
  const panel = document.getElementById('wsPanel')
  if (!btn || !panel) return
  const rect = btn.getBoundingClientRect()
  panel.style.top  = (rect.bottom + 6) + 'px'
  panel.style.left = Math.max(4, rect.right - 280) + 'px'
}

function _reopenWsPanel() {
  _positionWsPanel()
  document.getElementById('wsPanel')?.classList.add('open')
  document.getElementById('wsSwitcherBtn')?.classList.add('open')
}

window.__toggleWalletPanel = function() {
  const panel = document.getElementById('wsPanel')
  const btn   = document.getElementById('wsSwitcherBtn')
  if (!panel) return
  const isOpen = panel.classList.toggle('open')
  btn?.classList.toggle('open', isOpen)
  if (isOpen) _positionWsPanel()
}

window.__panelRename = function(addr) {
  const row = document.querySelector(`[data-ws-addr="${addr}"]`)
  if (!row) return
  const nameSpan = row.querySelector('.ws-wallet-row-name')
  if (!nameSpan) return
  const current = WM.getLabel(addr) ?? ''
  const safeId  = 'ren_' + addr.slice(2, 10)
  nameSpan.outerHTML = `<input class="ws-panel-rename-input" id="${safeId}"
    value="${esc(current)}"
    onblur="window.__panelRenameSave('${esc(addr)}', this.value)"
    onkeydown="if(event.key==='Enter')this.blur();if(event.key==='Escape')window.__panelRenameSave('${esc(addr)}', null)" />`
  document.getElementById(safeId)?.select()
}

window.__panelRenameSave = function(addr, label) {
  if (label !== null && label.trim()) WM.upsert(addr, label.trim())
  renderWalletStrip(state.addr)
  renderSavedWallets()
  _reopenWsPanel()
}

window.__panelRemove = function(addr) {
  if (!_confirmRemoveWallet(addr)) return
  WM.remove(addr)
  if (state.addr && addr.toLowerCase() === state.addr.toLowerCase()) {
    resetDashboard()
  } else {
    renderWalletStrip(state.addr)
    renderSavedWallets()
    _reopenWsPanel()
  }
}

window.__panelSave = function() {
  const input = document.getElementById('wsPanelNameInput')
  const label = input?.value?.trim()
  if (!label) return
  WM.upsert(state.addr, label)
  renderWalletStrip(state.addr)
  renderSavedWallets()
  _reopenWsPanel()
}

// Shared confirmation for every "remove this account" ✕ — the desktop chip, the
// wallet panel, and the All Accounts card. Removing a watched account is a quiet
// destructive action (and re-adding means re-pasting the address + relabelling),
// so it should never happen on a single stray tap.
function _confirmRemoveWallet(addr) {
  if (!addr) return false
  const w     = WM.load().find(e => e.addr.toLowerCase() === String(addr).toLowerCase())
  const label = w?.label ? `"${w.label}" (${addr.slice(0, 6)}…${addr.slice(-4)})` : `${addr.slice(0, 8)}…${addr.slice(-6)}`
  return confirm(`Remove ${label} from your accounts?\n\nIt stops being tracked and drops out of All Accounts. You can add it back by pasting the address again.`)
}

window.__removeWallet = function(addr) {
  if (!_confirmRemoveWallet(addr)) return
  WM.remove(addr)
  if (state.addr === addr) resetDashboard()
  else renderSavedWallets()
}

// Market metadata is identical for every account and its fan-out over ~9 perp
// dexes takes ~8s. Cache it for the whole session so account *switches* never
// re-pay that cost — only the per-account calls gate the first paint.
let _metaCache = null   // { allMetas, assetMap, perpNames, allMids }

// ─── BOOT SPLASH ──────────────────────────────────────────────────────────────
let _bootShownAt = 0
function _showBootSplash(addr) {
  const el = document.getElementById('bootSplash')
  if (!el) return
  const w = document.getElementById('bootWallet')
  if (w && addr) w.textContent = addr.slice(0, 6) + '…' + addr.slice(-6)
  const p = document.getElementById('bootPos'); if (p) p.textContent = 'positions'
  el.classList.remove('hide')
  // Replay the boot-log line reveal on every show (e.g. account switch)
  el.querySelectorAll('.boot-line').forEach(l => { l.style.animation = 'none'; void l.offsetWidth; l.style.animation = '' })
  el.classList.add('show')
  _bootShownAt = Date.now()
}
function _hideBootSplash() {
  const el = document.getElementById('bootSplash')
  if (!el || !el.classList.contains('show')) return
  const wait = Math.max(0, 1400 - (Date.now() - _bootShownAt))   // min on-screen time
  setTimeout(() => {
    el.classList.add('hide')
    setTimeout(() => el.classList.remove('show', 'hide'), 480)
  }, wait)
}
function _bootSetPos(n) {
  const p = document.getElementById('bootPos')
  if (p) p.textContent = n === 1 ? '1 position' : `${n} positions`
}

// ─── LOAD DASHBOARD ──────────────────────────────────────────────────────────
async function loadDashboard() {
  _paperExit()   // leaving the simulated account
  const addr = document.getElementById('walletInput').value.trim()

  if (!addr || !addr.startsWith('0x') || addr.length < 42) {
    showError('Please enter a valid 0x wallet address (42+ characters).')
    return
  }
  localStorage.setItem('walletAddr', addr)

  // Leaving the combined "All Accounts" view — stop its refresh loop + clear its chrome.
  if (_allAcctTimer) { clearInterval(_allAcctTimer); _allAcctTimer = null }
  if (_allAcctFastTimer) { clearInterval(_allAcctFastTimer); _allAcctFastTimer = null }
  if (_allAcctMidsTimer) { clearInterval(_allAcctMidsTimer); _allAcctMidsTimer = null }
  _stopAllAcctWs()   // drop the per-wallet WebSocket subscriptions
  setMultiAcctStrict(false)
  clearAgentKeys()
  _hideAllAcctLoader()

  _showBootSplash(addr)   // full-screen boot sequence until account data lands
  setTimeout(_hideBootSplash, 12000)   // safety: never let the splash get stuck

  document.getElementById('loadBtn').disabled = true
  document.getElementById('errorBox').classList.remove('active')
  document.getElementById('inputArea').style.display = 'none'

  const isMobile = window.innerWidth <= 768

  // Immediately switch to mobile view to avoid flash of desktop UI
  if (isMobile) {
    const _appEl = document.querySelector('.app')
    if (_appEl) _appEl.style.display = 'none'
    const _mvEl = document.getElementById('mobileView')
    if (_mvEl) { _mvEl.style.display = ''; _mvEl.classList.add('mob-view-active') }
    const _mcEl = document.getElementById('mobVContent')
    if (_mcEl) _mcEl.innerHTML = '<div class="mob-v-empty" style="padding:32px 16px">Loading…</div>'
    const _balEl = document.getElementById('mobVBalance')
    if (_balEl) _balEl.textContent = '—'
  }

  // Point the wallet layer at this account so getMainSigner()/isMainWalletConnected()
  // resolve to the wallet that controls IT, not to whichever connected last.
  setActiveWallet(addr)
  // Pass addr so the cold-start fallback seeds from this account's last known good
  // value instead of the double-counted perp+spot sum (which spiked the card on open).
  resetLiveAccountValue(addr)   // don't carry the previous account's value into this one

  // Seed state with safe empty defaults so renders don't crash before data arrives
  state = {
    ...state, addr,
    isAllAccounts: false,
    perpState:   { assetPositions: [], withdrawable: '0', marginSummary: {} },
    spotState:   { balances: [] },
    openOrders:  [], fills: [], funding: [],
    portfolio:   null, allMids: {}, assetMap: {}, allMetas: [],
    webData:     null, sessionStart: Date.now(),
  }
  _lastPerpCash = null   // reset transfer detector — a switch isn't a transfer

  // Explicitly hide loading overlay and show dashboard shell immediately
  document.getElementById('loadingOverlay').classList.remove('active')
  document.getElementById('dashboard').classList.add('active')
  document.body.classList.add('is-data-loading')

  pushRecentAddr(addr)
  _szSyncSlider()
  _disconnectAgentKeyUI()
  _resetMainWalletUI()
  restoreAgentKey(addr)
  restoreWalletForAddr(addr)
  serverStatus = {}
  checkServer()

  if (liveTimer)    clearInterval(liveTimer)
  if (sessionTimer) clearInterval(sessionTimer)
  if (midsTimer)    clearInterval(midsTimer)   // was leaking one per account switch
  liveTimer    = setInterval(refreshLive, 5000)
  // Validate stored agent keys against HL in the background, so a key HL no longer
  // recognizes is flagged in Settings BEFORE the user needs it to close a position.
  setTimeout(() => { _sweepAgentKeys().catch(() => {}) }, 12_000)
  sessionTimer = setInterval(tickSessionUptime, 1000)
  midsTimer    = setInterval(() => {
    if (_hlLimited()) return
    if (state.allMetas) fetchAllMids(state.allMetas).then(m => { state.allMids = m }).catch(e => _hl429(e))
  }, 60000)

  try {
    // ── Phase 1: account value first ──────────────────────────────────────────
    // Only the two per-account calls (~0.8s) gate the first paint. allPerpMetas
    // fans out over ~9 dexes (~8s) and is identical for every account, so it's
    // cached for the session and never blocks account value on a switch.
    const [perpState, spotState] = await Promise.all([
      infoClient.clearinghouseState({ user: addr }),
      infoClient.spotClearinghouseState({ user: addr }),
    ])

    if (_metaCache) {
      _perpNames = _metaCache.perpNames
      state = { ...state, perpState, spotState, allMids: _metaCache.allMids ?? {}, assetMap: _metaCache.assetMap, allMetas: _metaCache.allMetas }
    } else {
      state = { ...state, perpState, spotState }
    }

    renderAll()
    renderMobileView()
    _bootSetPos((perpState.assetPositions ?? []).filter(p => parseFloat(p.position?.szi ?? 0) !== 0).length)

    const _wdrawEl = document.getElementById('withdrawAvail')
    if (_wdrawEl) {
      const _perpWdraw = parseFloat(state.perpState?.withdrawable ?? 0)
      const _spotUSDC  = (state.spotState?.balances ?? []).find(b => b.coin === 'USDC')
      const _spotFree  = _spotUSDC ? Math.max(0, parseFloat(_spotUSDC.total ?? 0) - parseFloat(_spotUSDC.hold ?? 0)) : 0
      _withdrawAvailable = _perpWdraw + _spotFree
      _wdrawEl.textContent = `Available: ${_withdrawAvailable.toFixed(2)} USDC`
    }
    initRisk(totalPerpEquity(perpState))
    updateRiskUI()

    // ── Market metadata + mids: reuse the session cache, else fetch once ───────
    const metasReady = _metaCache
      ? Promise.resolve(_metaCache.allMetas)
      : Promise.all([infoClient.allPerpMetas(), infoClient.allMids()]).then(([allMetas, allMids]) => {
          const meta  = { universe: allMetas.flatMap(m => m.universe ?? []) }
          const names = new Set()
          for (const dex of allMetas) for (const u of (dex.universe ?? [])) names.add(u.name)
          const assetMap = buildAssetMap(meta)
          _perpNames = [...names]
          _metaCache = { allMetas, assetMap, perpNames: [...names], allMids }
          if (state.addr === addr) {
            state = { ...state, allMids: { ...allMids, ...state.allMids }, assetMap, allMetas }
            renderAll()
            renderMobileView()
          }
          return allMetas
        }).catch(() => null)

    // Once metas are available (cache or fresh), do the HIP-3 fan-out in background
    metasReady.then(allMetas => {
      if (state.addr !== addr || !allMetas) return
      fetchAllMids(allMetas).then(merged => {
        if (state.addr === addr) state.allMids = merged
      }).catch(() => {})
      fetchClearinghouseState(addr, allMetas).then(merged => {
        if (state.addr !== addr) return
        const extra = (merged.assetPositions ?? []).slice((perpState.assetPositions ?? []).length)
        if (!extra.length) return
        state.perpState = { ...state.perpState, assetPositions: [...(state.perpState.assetPositions ?? []), ...extra] }
        renderPositionSection()
        renderMobileView()
      }).catch(() => {})
    })

    // ── Phase 2: deferred data, split so each piece paints as soon as it lands ─
    const GENESIS = 1667260800000

    // 2a. Open orders → positions/orders tables
    fetchFrontendOpenOrders(addr, state.allMetas).catch(() => []).then(openOrders => {
      if (state.addr !== addr) return
      state.openOrders = openOrders
      renderPositionSection()
    })

    // 2b. Portfolio → account value + chart (single light call)
    infoClient.portfolio({ user: addr }).catch(() => null).then(portfolio => {
      if (state.addr !== addr || !portfolio) return
      state.portfolio = _anchorPortfolio(portfolio, state.perpState)
      renderAccountSection()
    })

    // 2c. Fills: a recent window first for a fast first paint, then the full
    //     history in the background so all-time totals/calendar fill in without
    //     blocking the initial render (this was the heaviest call on load).
    // `full` distinguishes the all-time history from the fast 14-day first paint. Net PnL
    // sums realized PnL and fees over whatever is in state.fills, so a 14-day window
    // produces a real-looking but wrong all-time figure that jumps when the full history
    // lands ~600ms later. Callers that show it consult state.fillsFull rather than
    // printing the partial number.
    state.fillsFull = false
    const applyFills = (rawFills, full = false) => {
      if (state.addr !== addr) return
      // Never let the short window overwrite a history that already landed — on a reload
      // the recent fetch can resolve after the full one.
      if (state.fillsFull && !full) return
      const fills = parseFills(rawFills).map(f => ({ ...f, coin: hip3Rename(f.coin) }))
      state.fills = fills
      state.fillsFull = full
      const FIRST_FILL_KEY = 'hliq_first_fill_' + addr
      if (fills.length > 0) localStorage.setItem(FIRST_FILL_KEY, fills[fills.length - 1].time)
      const cachedFirstFill = localStorage.getItem(FIRST_FILL_KEY)
      state.firstFillTime = cachedFirstFill ? parseInt(cachedFirstFill) : null
      computeLossStreak(fills)
      updateRiskUI()
      renderAccountSection()
      _refreshVisitedSection('trades')
      _refreshVisitedSection('calendar')
      updateMobileView(true)
      document.body.classList.remove('is-data-loading')
      _hideBootSplash()
    }
    const RECENT_MS = 14 * 24 * 60 * 60 * 1000
    infoClient.userFillsByTime({ user: addr, startTime: Date.now() - RECENT_MS, reversed: true })
      .catch(() => [])
      .then(recent => {
        applyFills(recent)
        // Full history in the background (idle) — backfills all-time totals. Time-pages
        // past the 2000-per-response cap so accounts with long histories aren't truncated.
        setTimeout(() => {
          fetchAllFills(addr, { startTime: GENESIS })
            .catch(() => infoClient.userFills({ user: addr }).catch(() => []))
            .then(full => { if (Array.isArray(full) && full.length) applyFills(full, true) })
        }, 600)
      })
      .catch(e => { console.warn('Phase 2 fills failed:', e.message); document.body.classList.remove('is-data-loading'); _hideBootSplash() })

    // 2d. outcomeMeta only labels '#N' outcome orders — fetch it idle; the
    //     Predictions tab loads its own copy when opened.
    setTimeout(() => {
      infoClient.outcomeMeta().catch(() => null).then(m => {
        if (state.addr === addr && m) { _buildOcTokenMap(m); renderPositionSection() }
      })
    }, 1500)

    // Funding + webData in background
    loadFundingData(addr, { mobile: isMobile }).then(({ funding, webData }) => {
      if (state.addr !== addr) return
      state.funding = parseFunding(funding)
      state.webData = webData ?? null
      renderAccountSection()
    }).catch(e => console.warn('Background funding load failed:', e.message))

    setTimeout(() => { fetchLedger(addr); fetchSubAccounts(addr) }, 4000)

  } catch (e) {
    console.error(e)
    document.getElementById('dashboard').classList.remove('active')
    document.getElementById('inputArea').style.display = ''
    document.getElementById('loadBtn').disabled = false
    document.body.classList.remove('is-data-loading')
    _hideBootSplash()
    showError('Failed to load account: ' + e.message)
  }
}

// ─── RENDER SECTIONS ──────────────────────────────────────────────────────────
function renderAccountSection() {
  const { perpState, spotState, fills, funding, portfolio, allMids, openOrders, ledger } = state
  renderOverview({ perpState, spotState, fills, funding, openOrders, allMids, portfolio, webData: state.webData, sessionStart: state.sessionStart, firstFillTime: state.firstFillTime ?? null, ledger: ledger ?? [], addr: state.addr })
  renderPortfolioStats({ perpState, spotState, fills, funding, portfolio, webData: state.webData })
  renderSummaryCards(fills, perpState, spotState, portfolio)
}

function renderPositionSection() {
  const { perpState, spotState, openOrders, allMids } = state
  renderSpot(spotState, state.ocTokenMap)
  renderOrders(openOrders, perpState, state.ocTokenMap)
  renderOutcomePositions()
}

function renderHistorySection() {
  renderTrades(state.fills)
  renderPnLCalendar(state.fills, state.calMonth, state.calYear, state.ledger)
  renderTransfers(state.ledger, state.transferFilter, state.addr)
}

function renderMarketSection() {
  const { fills, allMids, perpState, openOrders } = state
  renderMarkets({ fills, allMids, perpState })
  renderManageTables(perpState, openOrders, allMids)
  populateCoinDropdown()
  updateTradeBalance()
  _updateAvailDisplay()
}

// ─── LAZY TAB RENDERING ───────────────────────────────────────────────────────
// Heavy, full-history-dependent tabs (trades table, calendar, transfers) are not
// rendered at load — only when first opened. overview + positions render eagerly.
const _renderedTabs = new Set(['overview', 'positions'])

function _renderLazyTab(name) {
  switch (name) {
    case 'trades':    renderTrades(state.fills); break
    case 'calendar':  renderPnLCalendar(state.fills, state.calMonth, state.calYear, state.ledger); break
    case 'transfers': renderTransfers(state.ledger, state.transferFilter, state.addr); break
  }
}

// Render a deferred tab the first time it's opened.
function _ensureTabRendered(name) {
  if (_renderedTabs.has(name)) return
  _renderedTabs.add(name)
  try { _renderLazyTab(name) } catch (e) { console.error('lazy tab render', name, e) }
}

// Re-render a deferred tab only if it's already been shown (background data update).
function _refreshVisitedSection(name) {
  if (_renderedTabs.has(name)) { try { _renderLazyTab(name) } catch (e) { console.error(e) } }
}

// ─── RENDER ALL ───────────────────────────────────────────────────────────────
function renderAll() {
  renderWalletStrip(state.addr)
  restoreAssetLists(state.addr)
  _fxCheck()

  // The skeleton is for "we have not looked yet". An account that HAS been looked at and
  // genuinely has no trades is a known state, and holding the placeholders up for it is how
  // a new user comes to believe the screen is broken -- reported as "the desktop overview
  // is not loading", from a fresh paper account that would have sat there forever.
  //
  // Paper is complete from its first tick, so it never needs the wait. A real wallet still
  // does: perpState can arrive before the fills, and rendering then would flash zeros for
  // every figure derived from history. Portfolio history landing is the signal that the
  // fetch actually finished.
  if (state.fills.length > 0 || state.webData || isPaper() || _acctValueReady()) {
    renderAccountSection()
  } else {
    // Nothing has come back yet — show skeleton rather than a screen full of zeros.
    const el = document.getElementById('overviewStats')
    if (el) el.innerHTML =
      `<div class="overview-hero-row">${skeletonStatCards(4)}</div>` +
      `<div class="overview-perf-row">${skeletonStatCards(12)}</div>`
  }
  renderPositionSection()
  // History (trades/calendar/transfers) and market/trade tabs render lazily on
  // first visit — see _ensureTabRendered in switchTab. The trade tab's dropdown
  // and balance still need to exist for quick-trade flows, so prime them once.
  try { populateCoinDropdown(); updateTradeBalance(); _updateAvailDisplay() } catch {}
  updateWatchTicker()
  _updateSidebarAccount()

  setTimeout(() => renderChartPeriod('day'), 80)
}

function _updateMobTabCounts(posCount, ordCount) {
  const mobPos = document.getElementById('mobPosCount')
  const mobOrd = document.getElementById('mobOrdCount')
  if (mobPos) mobPos.textContent = posCount  ?? 0
  if (mobOrd) mobOrd.textContent = ordCount ?? 0
  const isOutcome = c => typeof c === 'string' && (c[0] === '+' || c[0] === '#' || /^o\d/.test(c))
  const _bals = (state.spotState?.balances ?? []).filter(b => parseFloat(b.total) > 0)
  const mobOc = document.getElementById('mobOcCount')
  if (mobOc) {
    const ocCount = _ocClampPending(_bals.filter(b => isOutcome(b.coin))).length
    mobOc.textContent = ocCount
    mobOc.style.display = ocCount > 0 ? '' : 'none'
  }
  const mobSpot = document.getElementById('mobSpotCount')
  if (mobSpot) {
    let spCount = _bals.filter(b => !isOutcome(b.coin)).length
    // Combined view keeps real spot tokens on each wallet's row, not on state.spotState.
    // Count UNIQUE assets across accounts (matches the grouped Spot tab), not row count.
    if (state.isAllAccounts) {
      const hidden = _maHiddenLoad()
      const coins  = new Set()
      _allAcctLastResults
        .filter(r => !r.error && !hidden.has(r.addr))
        .forEach(r => (r.spotBalances ?? []).forEach(b => coins.add(b.coin)))
      spCount = coins.size
    }
    mobSpot.textContent = spCount
    mobSpot.style.display = spCount > 0 ? '' : 'none'
  }
  // Strats badge in the combined view: count trading bots (not per-position guards)
  // across every visible account from the all-accounts status poll. In a single account
  // this badge is maintained by the strategy-status renderer instead.
  if (state.isAllAccounts) {
    const mobStrat = document.getElementById('mobStratCount')
    if (mobStrat) {
      const hidden   = _maHiddenLoad()
      const wallets  = _maLoad()
      const isGuard  = k => k.startsWith('liqguard:') || k.startsWith('levbrake:')
      let count = 0
      for (const [addr, bots] of Object.entries(_maBotStatus || {})) {
        if (!Array.isArray(bots) || hidden.has(addr)) continue
        if (!wallets.some(w => w.addr.toLowerCase() === addr.toLowerCase())) continue
        count += bots.filter(b => !isGuard(String(b))).length
      }
      mobStrat.textContent = count
      mobStrat.style.display = count > 0 ? '' : 'none'
    }
  }
}

function _updateSidebarAccount() {
  const { perpState, addr } = state
  if (!perpState?.marginSummary) return
  // Sidebar "Orders" item shows the open-order count (positions now live on Overview)
  const sb = document.getElementById('sidebarPosCount')
  if (sb) sb.textContent = (state.openOrders ?? []).length
  const sbAddr = document.getElementById('statusbarAddr')
  if (sbAddr && addr) sbAddr.textContent = addr.slice(0, 6) + '...' + addr.slice(-4)
}

function totalPerpEquity(perpState) {
  return computeAcctStats(perpState, state.spotState, state.fills, state.portfolio, state.funding, state.allMids).accountValue
}

// --- CELEBRATIONS ------------------------------------------------------------
// Moments worth marking. The animation was the easy half; the hard half is never firing
// on a reading that is not real. Each guard below exists for a specific way this could
// otherwise lie to someone about their own money:
//
//   - a partial load reads as a crash to zero, then as a miraculous recovery
//   - a first-ever load has nothing to compare against, so everything is a record
//   - the All Accounts total moves when you hide an account, which is not a gain
//   - paper money and real money are not the same money and never share a high

const ATH_KEY  = 'hliq_ath'
const _athLoad = () => { try { return JSON.parse(localStorage.getItem(ATH_KEY)) || {} } catch { return {} } }
const _athSave = (m) => { try { localStorage.setItem(ATH_KEY, JSON.stringify(m)) } catch {} }

// One record per account; paper is keyed by slot so each practice account keeps its own.
function _fxKey() {
  if (isPaper()) return 'paper:' + paperSlot()
  return state.addr ? 'w:' + String(state.addr).toLowerCase() : null
}

let _fxLastFire = 0
let _fxWinSeen  = null   // newest fill time already considered; null means "not seeded yet"
let _fxWinKey   = null   // the account that seed belongs to

// Never two banners at once, and never a stream of them.
function _fxGate(ms) {
  if (Date.now() - _fxLastFire < ms) return false
  _fxLastFire = Date.now()
  return true
}

// The account value the UI is showing -- or null when we do not actually know it yet.
// Returning null rather than 0 is the entire point. An empty read means "we did not look",
// and treating that as "you have nothing" is the bug that has hit Net PnL three times.
function _fxEquity() {
  // No margin summary means no reading at all, on either kind of account.
  if (!state.perpState?.marginSummary) return null
  // A real account also has to have loaded its history, since computeAcctStats folds fills
  // and portfolio into the value it returns. Paper needs no such wait: its balance is
  // whole from the first tick, and requiring a fill would mean a fresh practice account
  // could never record the high it started at.
  if (!isPaper() && !(state.fills?.length > 0 || state.webData)) return null
  const v = computeAcctStats(state.perpState, state.spotState, state.fills,
                             state.portfolio, state.funding, state.allMids)?.accountValue
  return Number.isFinite(v) && v > 0 ? v : null
}

function _fxCheckAth(key, eq) {
  const map  = _athLoad()
  const prev = map[key]

  // First sighting seeds silently, or everyone's first load is an all-time high.
  if (!prev || !Number.isFinite(prev.v)) { map[key] = { v: eq, t: Date.now() }; _athSave(map); return }
  if (eq <= prev.v) return

  // Record the new peak whether or not it is worth celebrating. Otherwise a value that
  // creeps up in sub-threshold steps eventually fires on a total that was never news.
  const gain = eq - prev.v
  map[key] = { v: eq, t: Date.now() }
  _athSave(map)

  // Beating your old peak by a cent is not a moment; a moving mark price does that every
  // few seconds. Ask for a real move before interrupting anyone.
  if (gain < 1 || gain / prev.v < 0.0025) return
  if (!_fxGate(300000)) return
  celebrate('ath', _T('New all-time high', 'Nuevo maximo historico'), '$' + fmtUSD(eq),
    _T('The most your account has ever been worth', 'Lo mas que ha valido tu cuenta'))
}

// The value of one wallet inside the combined view, matched on the address that
// _allAcctReaggregate stamps onto every fill it merges. null when we cannot match it,
// which the caller treats as "fall back", never as zero.
function _fxAcctEquity(addr) {
  for (const r of _allAcctLastResults ?? []) {
    if (!r || r.error || String(r.addr).toLowerCase() !== String(addr).toLowerCase()) continue
    const v = parseFloat(r.accountValue ?? 0)
    return Number.isFinite(v) && v > 0 ? v : null
  }
  return null
}

// How recently a trade must have closed for it to still be worth announcing. A
// celebration is meant to land at the moment it happens; one that arrives hours later,
// when you happen to reopen the app, is not a celebration but a report -- and the first
// version of this did exactly that, because a seed taken while the fills were still
// arriving made every trade that landed afterwards look new.
//
// This is the guard that makes that whole class of mistake harmless: however the seed
// goes wrong, an old trade can no longer fire. Missing one because the app was closed is
// the intended trade-off, not a gap.
const FX_WIN_FRESH_MS = 10 * 60 * 1000

// A closed trade that actually made money, sized against the equity of the account that
// made it -- $20 is a great day on a $200 wallet and a rounding error on a $200,000 one.
//
// That distinction is the whole reason this works in the combined view. Every fill merged
// there already carries the wallet it came from, so a win is attributed to that wallet and
// measured against that wallet's own value. Measuring against the nine-wallet total would
// bury a great trade on a small account under a threshold it could never reach.
//
// ONE TRADE, not a session's worth. Grouping is by order -- collapseFills, the same
// function the trade-history sheet uses, so the two can never disagree about what counts
// as a single trade. Partial fills of one order still merge, because that is one trade;
// separate orders stay separate, because they are not. Summing them by market, as this
// first did, invents a number the user never saw on any single trade.
function _fxCheckWin(key, eq) {
  const fills = state.fills ?? []
  if (!fills.length) return
  const newest = fills.reduce((m, f) => Math.max(m, f.time ?? 0), 0)

  // Seed on the first look at an account, so loading a year of history is silent.
  if (_fxWinKey !== key || _fxWinSeen === null) { _fxWinKey = key; _fxWinSeen = newest; return }
  if (newest <= _fxWinSeen) return

  const since = _fxWinSeen
  _fxWinSeen = newest
  const now = Date.now()
  const rows = collapseFills(fills.filter(f => (f.time ?? 0) > since))
    .filter(r => r.closedPnl !== 0 && now - r.time <= FX_WIN_FRESH_MS)
  if (!rows.length) return

  // The best single trade. With the freshness window and the shared cooldown this is
  // almost always the only candidate anyway; when two land together, announcing the
  // larger one beats announcing both or inventing their total.
  const best = rows.reduce((b, r) => r.net > (b?.net ?? -Infinity) ? r : b, null)
  if (!best || best.net <= 0) return

  // Against the wallet that made it when we know which one that was; against the value we
  // were handed otherwise, which is the single-account case.
  const base = best.acctAddr ? (_fxAcctEquity(best.acctAddr) ?? eq) : eq
  if (best.net < 1 || best.net / base < 0.01) return
  if (!_fxGate(60000)) return
  celebrate('win', _T('Closed in profit', 'Cerrado en ganancia'), '+$' + fmtUSD(best.net),
    esc(best.coin) + (best.acct ? ' - ' + esc(best.acct) : '') + ' - ' +
    (best.net / base * 100).toFixed(1) + '% ' + _T('of that account', 'de esa cuenta'))
}

// All Accounts is a real account value too, and for anyone running several wallets it is
// the only number they look at -- so leaving it out meant the feature never fired for the
// people most likely to want it. It only has to be keyed by WHICH wallets are in the
// total: hiding one changes the number without anything having been lost, and a changed
// set is simply a different key, which seeds silently instead of celebrating.
function _fxAllKey() {
  const hidden = _maHiddenLoad()
  const addrs = (_allAcctLastResults ?? [])
    .filter(r => r && !r.error && !hidden.has(r.addr))
    .map(r => String(r.addr).toLowerCase()).sort()
  return addrs.length ? 'all:' + addrs.join(',') : null
}

function _fxAllEquity() {
  // A wallet that has not landed yet leaves the total short by that wallet. Seeding on a
  // partial sum would fire a fake record the instant the rest arrived -- the same
  // empty-is-not-unknown trap as _fxEquity, one level up. _allAcctIncomplete already
  // tracks exactly this, and the portfolio chart skips on it for the same reason.
  if (_allAcctIncomplete) return null
  const hidden = _maHiddenLoad()
  const rows = (_allAcctLastResults ?? []).filter(r => r && !hidden.has(r.addr))
  if (!rows.length || rows.some(r => r.error)) return null
  const total = rows.reduce((s, r) => s + parseFloat(r.accountValue ?? 0), 0)
  return Number.isFinite(total) && total > 0 ? total : null
}

// Called from renderAll, i.e. after any refresh that produced something worth drawing.
function _fxCheck() {
  if (!fxEnabled()) return
  const all = state.isAllAccounts
  const key = all ? _fxAllKey() : _fxKey()
  if (!key) return
  const eq = all ? _fxAllEquity() : _fxEquity()
  if (eq === null) return
  // Both checks run in both views. A thrown celebration must never take down the render.
  try { _fxCheckAth(key, eq); _fxCheckWin(key, eq) } catch {}
}

window.__toggleCelebrate = function (on) { setFxEnabled(on) }

// Shows what the setting actually does. A toggle labelled "Celebrations" tells you nothing
// about how intrusive it is, and the honest answer is "watch it once and decide".
// Deliberately ignores the setting -- you asked for this one.
window.__celebratePreview = function () {
  const wasOn = fxEnabled()
  if (!wasOn) setFxEnabled(true)
  celebrate('ath', _T('New all-time high', 'Nuevo maximo historico'), '$12,480.00',
    _T('This is a preview', 'Esto es una vista previa'))
  if (!wasOn) setFxEnabled(false)
}

// ─── RISK UI ──────────────────────────────────────────────────────────────────
function updateRiskUI() {
  const el = document.getElementById('riskPanel')
  if (!el) return
  // Don't rebuild while the user is typing in a threshold input — the 5s
  // refresh was wiping edits mid-keystroke ("settings don't work")
  if (el.contains(document.activeElement) && document.activeElement?.tagName === 'INPUT') return

  const risk = getRiskState()
  const liq  = state.perpState ? checkLiquidation(state.perpState, state.allMids) : null

  const drawdownColor = risk.drawdownPct >= risk.thresholds.maxDrawdownPct
    ? 'var(--red)' : risk.drawdownPct >= risk.thresholds.maxDrawdownPct * 0.6
    ? 'var(--yellow)' : 'var(--green)'

  const streakColor = risk.lossStreak >= risk.thresholds.maxLossStreak
    ? 'var(--red)' : risk.lossStreak >= risk.thresholds.maxLossStreak - 2
    ? 'var(--yellow)' : 'var(--text)'

  const liqColor = !liq ? 'var(--muted)'
    : liq.bufferPct <= risk.thresholds.liqWarningPct ? 'var(--red)'
    : liq.bufferPct <= risk.thresholds.liqWarningPct * 2 ? 'var(--yellow)'
    : 'var(--green)'

  const _notifPerm = notifPermission()
  const notifBtnLabel = _notifPerm === 'granted'   ? '✓ Notifications On'
    : _notifPerm === 'denied'    ? '✗ Blocked — allow in browser settings'
    : _notifPerm === 'insecure'  ? '✗ Requires HTTPS'
    : _notifPerm === 'unsupported' ? '✗ Not supported on this browser'
    : 'Enable Alerts'
  const notifBtnDisabled = (_notifPerm === 'denied' || _notifPerm === 'insecure' || _notifPerm === 'unsupported') ? 'disabled' : ''
  const notifHint = _notifPerm === 'denied'
    ? 'Open your browser\'s site settings and set Notifications to "Allow", then refresh.'
    : _notifPerm === 'insecure'
    ? 'Browser notifications require a secure connection (HTTPS). The app is currently on HTTP.'
    : _notifPerm === 'unsupported'
    ? 'Your browser does not support web notifications.'
    : ''

  el.innerHTML = `
    <div class="risk-status-bar ${risk.paused ? 'risk-paused' : 'risk-active'}">
      <span class="risk-status-dot"></span>
      <span class="risk-status-label">${risk.paused ? 'TRADING PAUSED' : 'TRADING ACTIVE'}</span>
      ${risk.paused ? `<span class="risk-pause-reason">${esc(risk.pauseReason ?? '')}</span>` : ''}
      ${risk.paused ? `<button class="btn-risk-resume" onclick="window.__resumeRisk()">Resume</button>` : ''}
    </div>

    <div class="risk-metrics">
      <div class="risk-metric">
        <div class="risk-metric-label">Session Drawdown</div>
        <div class="risk-metric-value" style="color:${drawdownColor}">${risk.drawdownPct > 0 ? '−' : ''}${risk.drawdownPct.toFixed(2)}%</div>
        <div class="risk-metric-sub">Now $${fmtUSD(risk.currentValue ?? 0)} · Start $${fmtUSD(risk.sessionStartValue ?? 0)} · Limit ${risk.thresholds.maxDrawdownPct}%</div>
      </div>
      <div class="risk-metric">
        <div class="risk-metric-label">Loss Streak</div>
        <div class="risk-metric-value" style="color:${streakColor}">${risk.lossStreak}</div>
        <div class="risk-metric-sub">Consecutive losses · Limit ${risk.thresholds.maxLossStreak}</div>
      </div>
      <div class="risk-metric">
        <div class="risk-metric-label">Nearest Liq.</div>
        <div class="risk-metric-value" style="color:${liqColor}">
          ${liq ? liq.bufferPct.toFixed(1) + '%' : '—'}
        </div>
        <div class="risk-metric-sub">${liq ? `${liq.coin} ${liq.side} · liq $${fmtPrice(liq.liqPx)} · mark $${fmtPrice(liq.markPx)} · alert ${risk.thresholds.liqWarningPct}%` : 'No open positions'}</div>
      </div>
    </div>

    <div class="risk-thresholds">
      <div class="risk-threshold-title">Thresholds</div>
      <div class="risk-threshold-row">
        <label class="risk-threshold-label">Max Drawdown %</label>
        <input class="risk-threshold-input" id="riskDrawdownInput" type="number" min="1" max="100"
          value="${risk.thresholds.maxDrawdownPct}" oninput="window.__applyThresholds()" />
        <span class="risk-threshold-hint">Pauses trading when your account drops this % from its session peak.</span>
      </div>
      <div class="risk-threshold-row">
        <label class="risk-threshold-label">Max Loss Streak</label>
        <input class="risk-threshold-input" id="riskStreakInput" type="number" min="1" max="50"
          value="${risk.thresholds.maxLossStreak}" oninput="window.__applyThresholds()" />
        <span class="risk-threshold-hint">Pauses after this many consecutive losing closed trades in a row.</span>
      </div>
      <div class="risk-threshold-row">
        <label class="risk-threshold-label">Liq. Warning %</label>
        <input class="risk-threshold-input" id="riskLiqInput" type="number" min="1" max="100"
          value="${risk.thresholds.liqWarningPct}" oninput="window.__applyThresholds()" />
        <span class="risk-threshold-hint">Sends a browser notification when your nearest liquidation is within this % buffer.</span>
      </div>
      <button class="btn-risk-notif" onclick="window.__enableNotifs()" ${notifBtnDisabled}>
        ${notifBtnLabel}
      </button>
      ${notifHint ? `<div class="risk-notif-hint">${notifHint}</div>` : ''}
    </div>`
}

window.__resumeRisk = function () {
  resume()
  updateRiskUI()
  updateSubmitBtn()
}

window.__applyThresholds = function () {
  const drawdown = parseFloat(document.getElementById('riskDrawdownInput')?.value)
  const streak   = parseInt(document.getElementById('riskStreakInput')?.value)
  const liq      = parseFloat(document.getElementById('riskLiqInput')?.value)
  setThresholds({
    maxDrawdownPct: isNaN(drawdown) ? undefined : drawdown,
    maxLossStreak:  isNaN(streak)   ? undefined : streak,
    liqWarningPct:  isNaN(liq)      ? undefined : liq,
  })
  localStorage.setItem('hliq_risk_thresholds', JSON.stringify(getRiskState().thresholds))
}

// Restore persisted thresholds on startup (they were resetting every reload)
try { const _rt = JSON.parse(localStorage.getItem('hliq_risk_thresholds') || 'null'); if (_rt) setThresholds(_rt) } catch {}

window.__enableNotifs = function () {
  requestNotifications().then(() => updateRiskUI())
}

// ─── LIVE REFRESH ─────────────────────────────────────────────────────────────
let liveTimer    = null
let sessionTimer = null
let midsTimer    = null
let refreshFailCount    = 0
let _refreshInProgress  = false

function _updateRetryBtn(mode) {   // mode: null | 'error' | 'retrying'
  const btn = document.getElementById('wsRetryBtn')
  if (!btn) return
  btn.classList.toggle('ws-retry-error',    mode === 'error')
  btn.classList.toggle('ws-retry-spinning', mode === 'retrying')
}

function updateRefreshBanner() {
  const banner = document.getElementById('refreshErrorBanner')
  if (!banner) return
  if (refreshFailCount < 12) {
    banner.classList.remove('active')
    _updateRetryBtn(null)
    return
  }
  banner.classList.add('active')
  banner.innerHTML = `⚠ Live data paused — connection lost. <button class="refresh-error-retry" onclick="window.__retryRefresh()">Retry now</button>`
  _updateRetryBtn('error')
}

const _pollInterval = () => 5000

function _restartLiveTimer() {
  if (liveTimer) clearInterval(liveTimer)
  liveTimer = setInterval(refreshLive, _pollInterval())
  refreshLive()
}

window.__retryRefresh = async function(btn) {
  if (liveTimer) { clearInterval(liveTimer); liveTimer = null }
  refreshFailCount   = 0
  _refreshInProgress = false
  // Clear render caches so everything is force-redrawn on next tick
  _lastPosHash = null; _lastOrdHash = null; _lastAcctHash = null
  // A manual reload must force-fresh history too, not reuse the 8-min combined-view cache.
  // Only the in-memory copy is dropped: the persisted store stays deliberately, so the forced
  // refetch is a delta off what we already hold instead of the all-time walk this used to mean.
  try { _maHistCache2.clear(); _maLedgerCache.clear() } catch {}
  _updateRetryBtn('retrying')
  updateRefreshBanner()
  // Mobile has no #wsRetryBtn — spin the tapped icon so the user sees it working.
  const icon = btn?.querySelector?.('svg')
  const stopSpin = () => { if (icon) icon.style.animation = '' }
  if (icon) icon.style.animation = 'spin 0.8s linear infinite'
  // Failsafe: the HTTP transport has no hard timeout, so a dropped/slow connection can
  // leave refreshLive() pending forever. Stop the spinner after 12s no matter what so
  // the button never gets stuck (the live timer keeps retrying in the background).
  const failsafe = setTimeout(stopSpin, 12000)
  // In the combined view refreshLive() no-ops — drive the All-Accounts fan directly instead.
  if (state.isAllAccounts) {
    try { await _allAcctSilentRefresh(_maLoad()) } catch {} finally { clearTimeout(failsafe); stopSpin() }
    return
  }
  liveTimer = setInterval(refreshLive, _pollInterval())
  try { await refreshLive(true) } catch {} finally { clearTimeout(failsafe); stopSpin() }
}

// Header reload button — full app refresh: nudge the service worker for the
// latest build, then hard-reload the page so everything re-initialises.
window._mobVAppReload = async function(btn) {
  const icon = btn?.querySelector?.('svg')
  if (icon) icon.style.animation = 'spin 0.8s linear infinite'
  try {
    if ('serviceWorker' in navigator) {
      const regs = await navigator.serviceWorker.getRegistrations()
      await Promise.all(regs.map(r => r.update().catch(() => {})))
    }
  } catch {}
  location.reload()
}

document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    if (liveTimer) { clearInterval(liveTimer); liveTimer = null }
  } else if (state.addr) {
    refreshFailCount = 0
    updateRefreshBanner()
    _rlBannerTick()   // a backgrounded interval may have left the rate-limit banner stuck
    setTimeout(_restartLiveTimer, 300)
  }
})

// iOS bfcache restore — fires when page is shown from back/forward cache
window.addEventListener('pageshow', (e) => {
  if (e.persisted && state.addr) {
    refreshFailCount = 0
    _lastPosHash = null; _lastOrdHash = null; _lastAcctHash = null
    _rlBannerTick()
    setTimeout(_restartLiveTimer, 300)
  }
})

// Fallback for mobile browsers that don't reliably fire visibilitychange
window.addEventListener('focus', () => {
  if (!liveTimer && state.addr) {
    refreshFailCount = 0
    updateRefreshBanner()
    _rlBannerTick()
    setTimeout(_restartLiveTimer, 300)
  }
})

function tickSessionUptime() {
  const el = document.getElementById('statSessionUptime')
  if (!el || !state.sessionStart) return
  const ms  = Date.now() - state.sessionStart
  const totalSec = Math.floor(ms / 1000)
  const h = Math.floor(totalSec / 3600)
  const m = Math.floor((totalSec % 3600) / 60)
  const s = totalSec % 60
  el.textContent = h > 0 ? `${h}h ${m}m` : m > 0 ? `${m}m ${s}s` : `${s}s`
}

// (Removed: fetchAllTimeVolume.) state.fills now holds the complete, time-paged
// history, so renderOverview computes all-time Total Volume from it directly —
// no separate fetch, and no hash-dedup bug (HL's 0x0…0 hashes made it undercount).

async function fetchLedger(addr) {
  // Show skeleton while the ledger loads
  const summaryEl = document.getElementById('transfersSummary')
  const cardsEl   = document.getElementById('transfersCards')
  if (summaryEl) summaryEl.innerHTML = skeletonStatCards(4)
  if (cardsEl)   cardsEl.innerHTML   = `<div class="txfr-cards-skeleton">${skeletonStatCards(6)}</div>`

  try {
    const info   = new InfoClient({ transport: _transport })
    const ledger = await info.userNonFundingLedgerUpdates({ user: addr, startTime: 1667260800000 })
    state.ledger = ledger ?? []
    _refreshVisitedSection('transfers')
    _refreshVisitedSection('calendar')
    renderAccountSection()  // refresh Total Deposited card in overview
  } catch (e) {
    console.warn('Ledger fetch failed:', e.message)
    renderTransfers([], state.transferFilter)
  }
}

async function fetchSubAccounts(addr) {
  try {
    const info = new InfoClient({ transport: _transport })
    const subs = await info.subAccounts({ user: addr }).catch(() => null)
    if (!subs?.length) return
    state.subAccounts = subs
    renderWalletStrip(state.addr)
  } catch (e) {
    console.warn('Sub-accounts fetch failed:', e.message)
  }
}

// Fingerprints for skip-render optimization
let _lastPosHash  = null
let _lastOrdHash  = null
let _lastAcctHash = null
let _lastPerpCash = null   // perp balance minus uPnL — used to catch spot↔perp transfers
const _cancelledOids = new Set()  // oids removed optimistically, filtered from refreshes

function _fingerprint(obj) {
  try { return JSON.stringify(obj) } catch (e) { return null }
}

const _domCache = {}
function _dom(id) {
  return _domCache[id] || (_domCache[id] = document.getElementById(id))
}

// ── HL rate-limit circuit breaker ─────────────────────────────────────────────
// One 429 anywhere trips a GLOBAL pause that every poller respects (refresh
// loop, mids fan-out, prediction books, game sparklines…). Exponential: 15s →
// 30s → 60s → 120s cap, reset after the first clean refresh.
let _hlBackoffUntil = 0
let _hlBackoffMs    = 15000
function _hlLimited() { return Date.now() < _hlBackoffUntil }
function _hlTrip() {
  const wasLimited = _hlLimited()
  _hlBackoffUntil = Date.now() + _hlBackoffMs
  console.warn(`[hliq] HL 429 — pausing all polls ${Math.round(_hlBackoffMs / 1000)}s`)
  _hlBackoffMs = Math.min(_hlBackoffMs * 2, 120000)
  _rlBannerStart()   // tell the user why updates paused, instead of silently freezing
  if (!wasLimited) _hlReportLimit()   // report only a fresh episode, not each escalation
}
// Telemetry: log a rate-limit episode server-side (throttled) so we can measure how often real
// users get throttled and under what shape (All Accounts + wallet count is the key dimension).
let _hlReportAt = 0
function _hlReportLimit() {
  const now = Date.now()
  if (now - _hlReportAt < 120000) return
  _hlReportAt = now
  try {
    let lang = 'en'; try { lang = localStorage.getItem('hliq_lang') || 'en' } catch {}
    const n = state.isAllAccounts ? (typeof _maLoad === 'function' ? _maLoad().length : 0) : 1
    const secSinceLoad = Math.round((now - (window.__appLoadedAt || now)) / 1000)
    fetch('/api/error', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, keepalive: true,
      body: JSON.stringify({
        kind: 'ratelimit',
        // Records dedupe by message, so anything that distinguishes one episode from
        // another has to be IN the message. `sinceLoad` lived in the stack, which keeps
        // only the first occurrence's value - so 51 later episodes all reported the age of
        // the first one and there was no way to tell an on-entry trip from a slow leak.
        // Bucketed rather than exact, or every episode would be its own record.
        message: `client 429 · all=${state.isAllAccounts ? 1 : 0} · wallets=${n} · tab=${_activeTab}` +
                 ` · age=${secSinceLoad < 60 ? '<1m' : secSinceLoad < 300 ? '1-5m' : secSinceLoad < 1800 ? '5-30m' : '>30m'}` +
                 ` · ${_hlLastTripReason}`,
        stack: `sinceLoad=${secSinceLoad}s`,
        url: location.pathname, ua: navigator.userAgent, screen: `${window.innerWidth}x${window.innerHeight}`, lang,
      }),
    }).catch(() => {})
  } catch {}
}

// ── RATE-LIMIT "COOLING DOWN" BANNER ──────────────────────────────────────────
// The breaker pauses every poll when HL throttles us; without this the UI just froze
// with no explanation. Shows a thin countdown bar while limited, self-clears after.
let _rlBannerTimer = null
function _rlBannerTick() {
  const el = document.getElementById('rlBanner')
  if (!_hlLimited()) {
    if (el) el.remove()
    if (_rlBannerTimer) { clearInterval(_rlBannerTimer); _rlBannerTimer = null }
    return
  }
  let b = el
  if (!b) {
    b = document.createElement('div')
    b.id = 'rlBanner'
    b.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:100002;background:rgba(245,158,11,0.96);color:#1a1200;font-size:12px;font-weight:700;text-align:center;padding:calc(6px + env(safe-area-inset-top,0px)) 12px 6px;box-shadow:0 2px 8px rgba(0,0,0,.35)'
    document.body.appendChild(b)
  }
  const secs = Math.max(0, Math.ceil((_hlBackoffUntil - Date.now()) / 1000))
  b.textContent = `⏳ Hyperliquid is rate-limiting — updates paused, resuming in ${secs}s`
}
function _rlBannerStart() {
  _rlBannerTick()
  if (!_rlBannerTimer) _rlBannerTimer = setInterval(_rlBannerTick, 1000)
}
function _hlOk() {
  _hlBackoffMs = 15000
  // Data is flowing again — end the pause window and pull the banner NOW rather than
  // waiting on the 1s interval (which iOS suspends in the background, leaving it stuck).
  if (_hlBackoffUntil) { _hlBackoffUntil = 0; _rlBannerTick() }
}
// Returns true (and trips the breaker) when the error is a rate limit OR the
// network/CORS failure a rate limit produces in the browser. HL returns 429s
// WITHOUT CORS headers, so the browser rejects them as "Failed to fetch" / a CORS
// error with no "429" text — meaning the old check never tripped, the breaker never
// backed off, and the app kept hammering HL, flooding the console. Treating the
// network-failure shape as a limit lets it pause and recover.
// HL returns 429s WITHOUT CORS headers, so the browser reports them as a generic network
// failure — which is why the breaker has to treat that shape as a limit. But it means a
// genuine connectivity blip, or a wallet extension breaking the page, shows the same
// banner. Recording which pattern matched is the only way to tell them apart later.
let _hlLastTripReason = 'unknown'
function _hl429(e) {
  const m = String(e?.message ?? e)
  if (/429|too many/i.test(m)) { _hlLastTripReason = 'real-429'; _hlTrip(); return true }
  if (/failed to fetch|load failed|networkerror|err_failed|cors|access-control/i.test(m)) {
    _hlLastTripReason = 'network-shaped'   // could be a 429, could be the network
    _hlTrip(); return true
  }
  return false
}

let _refreshTick  = 0
// After a user action (place/close/cancel), force the NEXT refresh to fetch the
// weight-gated endpoints (orders every 2nd tick, fills every 3rd, spot/portfolio every 12th)
// so the change shows in Orders/History/Calendar immediately instead of up to ~15s later.
let _forceFreshNext = false
let _activeTab    = 'overview'
let _lbTabTimer   = null
let _maTabTimer   = null
let _lbLastFetch  = 0
let _lbFetching   = false
let _maLastFetch  = 0

// Stamp the perp account value seen at portfolio-fetch time onto the snapshot
// so renders can add the live perp-equity delta between (1/min) refetches.
function _anchorPortfolio(portfolio, perpState) {
  if (Array.isArray(portfolio) && perpState?.marginSummary)
    portfolio._perpAnchor = parseFloat(perpState.marginSummary.accountValue ?? 0)
  return portfolio
}

// HIP-3 dexes the wallet currently has positions/orders in — these get fanned
// out every tick so their orders/positions stay as fresh as crypto (instead of
// flickering on the once-a-minute full fan-out).
function _activeDexSet() {
  const s = new Set()
  for (const ap of (state.perpState?.assetPositions ?? [])) {
    const c = ap.position?.coin
    if (c && c.includes(':')) s.add(c.split(':')[0].toLowerCase())
  }
  for (const o of (state.openOrders ?? [])) {
    if (o.coin && o.coin.includes(':')) s.add(o.coin.split(':')[0].toLowerCase())
  }
  return s
}

// allMetas filtered for the fan-out: full set on discovery ticks, else only the
// active dexes (or null when there's no HIP-3 activity → skip fan-out entirely).
function _fanMetas(full) {
  if (full || !state.allMetas) return state.allMetas
  const active = _activeDexSet()
  if (!active.size) return null
  const filtered = state.allMetas.filter((m, i) =>
    i === 0 || active.has(((m.universe?.[0]?.name) || '').split(':')[0].toLowerCase()))
  return filtered.length > 1 ? filtered : null
}

async function refreshLive(force = false) {
  if (force) _forceFreshNext = true
  if (_refreshInProgress) return
  if (state.isAllAccounts) return   // combined view has its own refresh loop
  if (isPaper()) return             // paper has its own loop; the sentinel isn't a real address
  if (_hlLimited()) return   // circuit breaker open — let HL cool down
  _refreshInProgress = true
  // Pin the account this tick is for. If the user switches accounts while these
  // fetches are in flight, the results belong to the OLD account and must be
  // discarded — otherwise they clobber the new account's perpState/portfolio and
  // flash the wrong account value for a few seconds (most visible on mobile).
  const _reqAddr = state.addr
  try {
    const info = new InfoClient({ transport: _transport })
    _refreshTick++

    // Latest known fill timestamp — used to fetch only new fills
    const latestFillTs = state.fills.length > 0
      ? state.fills.reduce((m, f) => Math.max(m, f.time), 0)
      : Date.now() - 60 * 1000

    // A forced refresh (right after a user action) fetches the gated endpoints regardless of
    // the tick, so Orders/History/Calendar/Spot reflect the change immediately. Consumed once.
    const _forced = _forceFreshNext; _forceFreshNext = false
    const shouldFetchOutcomeMeta = _refreshTick === 1 || _refreshTick % 60 === 0
    const _needsPrices = !['history', 'transfers', 'settings', 'leaderboard', 'accounts'].includes(_activeTab)
    const shouldRefreshSpot      = _forced || _refreshTick === 1 || _refreshTick % 12 === 0
    const shouldRefreshPortfolio = _forced || _refreshTick === 1 || _refreshTick % 12 === 0
    // HIP-3 fan-out is the dominant cost of a tick: one clearinghouseState AND one
    // frontendOpenOrders per dex, and frontendOpenOrders is a heavy-weight endpoint.
    // Fanning every 5s tick pushed us over HL's per-minute weight budget and 429'd.
    // Fan the active dexes every 4th tick (~20s) and the full set every 24th (~2min);
    // in between, passing `null` makes the fetch helpers reuse their HIP-3 cache, so
    // positions and orders don't flicker.
    const _fullFan  = _refreshTick === 1 || _refreshTick % 24 === 0
    const _fanTick  = _refreshTick === 1 || _refreshTick % 4 === 0
    const _fanMeta  = _fanTick ? _fanMetas(_fullFan) : null
    // HL's 1200 weight/min IP budget is shared between /info and /exchange, so a
    // chatty poll loop doesn't just 429 the dashboard — it starves order placement.
    // frontendOpenOrders and userFillsByTime are weight-20 (most endpoints are 2),
    // so polling both every 5s tick burned ~480 weight/min on data that tolerates
    // lag. Orders refresh every 2nd tick (~10s), fills every 3rd (~15s).
    // userFillsByTime is keyed off latestFillTs, so a fills tick still returns every
    // fill from the ticks it skipped — nothing is missed, only delayed.
    const _ordTick   = _forced || _refreshTick === 1 || _refreshTick % 2 === 0
    const _fillsTick = _forced || _refreshTick === 1 || _refreshTick % 3 === 0
    const [perpState, openOrders, mainMids, hip3Mids, newRawFills, freshOutcomeMeta, freshSpot, freshPortfolio] = await Promise.all([
      fetchClearinghouseState(state.addr, _fanMeta),
      _ordTick ? fetchFrontendOpenOrders(state.addr, _fanMeta) : Promise.resolve(state.openOrders ?? []),
      (_needsPrices && !_midsWsOk()) ? info.allMids() : Promise.resolve({}),   // WS keeps prices fresh; skip REST when it's delivering
      // HIP-3 dex mids aren't in the main allMids feed (nor the WS), so without this a
      // HIP-3 position's mark comes only from positionValue/sz and lags. Fetch active-dex
      // mids on the fan tick (weight-2 each) so SPCX/GOLD/etc. marks stay live.
      (_needsPrices && _fanMeta) ? fetchHip3Mids(_fanMeta) : Promise.resolve({}),
      // Fetch only fills newer than what we already have (startTime is exclusive on HL).
      // `null` (not []) means "not fetched this tick" — the anchor logic below must not
      // mistake a skipped tick for "no new fills".
      _fillsTick
        ? info.userFillsByTime({ user: state.addr, startTime: latestFillTs + 1 }).catch(() => [])
        : Promise.resolve(null),
      shouldFetchOutcomeMeta  ? info.outcomeMeta().catch(() => null)                              : Promise.resolve(null),
      shouldRefreshSpot       ? info.spotClearinghouseState({ user: state.addr }).catch(() => null) : Promise.resolve(null),
      shouldRefreshPortfolio  ? info.portfolio({ user: state.addr }).catch(() => null)             : Promise.resolve(null),
    ])
    // Account switched mid-flight — this tick's data is for the old account.
    // Drop it entirely so it can't overwrite the freshly-loaded account.
    if (state.addr !== _reqAddr) return

    if (freshSpot)      state.spotState = freshSpot
    if (freshPortfolio) state.portfolio = _anchorPortfolio(freshPortfolio, perpState)

    state.perpState  = perpState
    state.openOrders = openOrders.filter(o => !_cancelledOids.has(o.oid))

    // Catch spot↔perp transfers (e.g. a bot's margin top-up on start): they move
    // money into the perp balance without changing the unified account value, so
    // the live perp-delta would otherwise spike it. perp "cash" = accountValue −
    // uPnL stays flat under pure PnL, but jumps on a transfer/deposit. When it
    // jumps (and it isn't a fill), shift the anchor so the value stays continuous.
    // Only reconcile on ticks where we actually fetched fills. On a skipped tick
    // `newRawFills` is null, so we can't tell a legit realized-PnL move from a
    // transfer — and `_lastPerpCash` deliberately does NOT advance, so the next
    // fills tick compares against the right baseline and sees every fill in between.
    if (_fillsTick) {
      // marginSummary.accountValue is MAIN-DEX ONLY, but assetPositions has HIP-3
      // positions merged into it (see fetchClearinghouseState). Summing uPnL across
      // both subtracts HIP-3 unrealized from a main-only equity figure, so ordinary
      // HIP-3 price drift read as a "transfer" and nudged the anchor every fills
      // tick. Count main-dex positions only, matching the scope of _perpVal.
      const _uPnl    = (perpState.assetPositions ?? [])
        .filter(p => !String(p.position?.coin ?? '').includes(':'))
        .reduce((s, p) => s + parseFloat(p.position?.unrealizedPnl ?? 0), 0)
      const _perpVal = parseFloat(perpState.marginSummary?.accountValue ?? 0)
      const _perpCash = _perpVal - _uPnl
      if (_lastPerpCash != null && Math.abs(_perpCash - _lastPerpCash) > 0.01) {
        // Reconcile ONLY on ticks with no fills — that's a genuine transfer/deposit.
        // On a tick that HAD fills, the difference is dominated by ordinary trading
        // noise: uPnL is marked at mark price while closedPnl realizes at fill price,
        // plus funding, and fees charged in HYPE rather than USDC. Shifting the anchor
        // by that noise is what spiked the value on every close — it moved the number,
        // then the authoritative refetch below yanked it back a second later. Fills
        // already trigger that refetch, which re-baselines snapshot AND anchor exactly
        // (absorbing any real transfer landing on the same tick), so leave the anchor
        // alone and let it settle. The value then stays continuous across a close.
        // Shifting the anchor by the raw delta is only safe with no fills this tick: with
        // fills the difference is dominated by trading noise (uPnL marked at mark vs
        // closedPnl realized at fill, funding, HYPE-denominated fees).
        if (newRawFills.length === 0) {
          const _spurious = _perpCash - _lastPerpCash
          if (Math.abs(_spurious) > 0.01 && state.portfolio && state.portfolio._perpAnchor != null) {
            state.portfolio._perpAnchor += _spurious
          }
        }
        // But the RE-BASELINE has to happen either way, and it did not.
        //
        // Opening a position makes Hyperliquid move USDC spot -> perp to fund the margin.
        // That lifts perp equity without changing the unified account value, so the bridge
        // (snapshot + perpNow - anchor) reads high by the transfer. The reconcile above was
        // skipped because the same tick carried the opening fill, no refetch was scheduled
        // because that lived inside the same branch, and _lastPerpCash advanced regardless
        // - so the jump was baked in and never revisited. A $18.80 margin transfer is
        // exactly how $690 showed as $709 until something else forced a refresh.
        //
        // Re-reading the portfolio pairs a fresh snapshot with a fresh anchor, which
        // absorbs the transfer without trusting the noisy delta.
        const _a = state.addr
        info.portfolio({ user: _a }).catch(() => null).then(p => {
          if (p && state.addr === _a) { state.portfolio = _anchorPortfolio(p, state.perpState); renderAccountSection() }
        })
      }
      _lastPerpCash = _perpCash
    }

    // Rebuild outcome token map so '#N' coins resolve correctly in open orders,
    // then refresh the History table so any newly-resolved outcome names appear.
    if (freshOutcomeMeta) { _buildOcTokenMap(freshOutcomeMeta); _refreshVisitedSection('trades') }

    // Merge fresh prices only when on a price-displaying tab; otherwise reuse cached values.
    // HIP-3 dex mids merge in too (keyed "dex:coin"), keeping HIP-3 position marks live.
    // state.allMids is THE single price store — every view reads its mark from here via
    // _livePx, so nobody derives their own number. Guarantee it always holds a mark for each
    // open position: if a dex mid wasn't fetched this tick, backfill from the position's own
    // notional (HL: positionValue = |szi| × mark). Without this, a position falls back to its
    // notional while the watch strip falls back to a stale ctx/candle → the same asset shows
    // two slightly different prices. One store, one value, read everywhere.
    if (_needsPrices) {
      const _mids = { ...state.allMids, ...mainMids, ...hip3Mids }
      for (const ap of (perpState.assetPositions ?? [])) {
        const p = ap.position
        if (!p?.coin || parseFloat(_mids[p.coin] ?? 0) > 0) continue
        const sz = Math.abs(parseFloat(p.szi ?? 0))
        const pv = Math.abs(parseFloat(p.positionValue ?? 0))
        if (sz > 0 && pv > 0) _mids[p.coin] = String(pv / sz)
      }
      state.allMids = _mids
    }
    const allMids    = state.allMids

    // Auto-select BTC on first data load if no coin chosen yet
    if (!state.selectedCoin && allMids['BTC']) {
      window.__selectCoin('BTC')
    }

    // Merge new fills if any arrived (null = fills weren't fetched this tick)
    if (newRawFills && newRawFills.length > 0) {
      const newFills = parseFills(newRawFills).map(f => ({ ...f, coin: hip3Rename(f.coin) }))
      // userFillsByTime is keyed on a timestamp and many fills share the same ms, so a
      // boundary re-serve can hand back a fill we already hold. Appending it blind would
      // double-count its closedPnl and fee in computeAcctStats — inflating realized and
      // net PnL permanently, since nothing later re-derives state.fills from scratch.
      const _have  = new Set(state.fills.map(fillKey))
      const _fresh = newFills.filter(f => !_have.has(fillKey(f)))
      state.fills = [..._fresh, ...state.fills]
      computeLossStreak(state.fills)
      _refreshVisitedSection('trades')
      if (_activeTab === 'tokens') renderMarkets({ fills: state.fills, allMids, perpState })
      // New trade detected — refresh portfolio chart data in background, then
      // re-baseline the anchor exactly and re-render the account card so the value
      // settles on the authoritative number (no lingering spike).
      const _addr = state.addr
      info.portfolio({ user: _addr }).catch(() => null).then(p => {
        if (p && state.addr === _addr) { state.portfolio = _anchorPortfolio(p, state.perpState); renderChartPeriod(state.currentPeriod); renderAccountSection() }
      })
    }

    const posCount = (perpState.assetPositions ?? []).filter(p => parseFloat(p.position?.szi ?? 0) !== 0).length
    const _pcEl = _dom('posCount');    if (_pcEl) _pcEl.textContent = posCount
    const _pcb  = _dom('posCountBig'); if (_pcb)  _pcb.textContent = posCount
    const _ocEl = _dom('ordCount');    if (_ocEl) _ocEl.textContent = state.openOrders.length
    const _ocb  = _dom('ordCountBig'); if (_ocb)  _ocb.textContent = state.openOrders.length
    _updateMobTabCounts(posCount, state.openOrders.length)

    // Re-render account section only when key values change
    const _acctHash = `${perpState.marginSummary?.accountValue}|${state.fills.length}|${(perpState.assetPositions ?? []).reduce((s, p) => s + parseFloat(p.position.unrealizedPnl ?? 0), 0).toFixed(4)}`
    if (_acctHash !== _lastAcctHash) { renderAccountSection(); _lastAcctHash = _acctHash }
    updateTradeBalance()
    _updateAvailDisplay()

    const posHash  = _fingerprint(perpState.assetPositions)
    const ordHash  = _fingerprint(openOrders)
    const posChanged = posHash !== _lastPosHash
    const ordChanged = ordHash !== _lastOrdHash
    if (posChanged) { _lastPosHash = posHash }
    if (ordChanged) { renderOrders(openOrders, perpState, state.ocTokenMap); renderOutcomePositions(); _lastOrdHash = ordHash }
    if (posChanged || ordChanged) { renderManageTables(perpState, openOrders, allMids); _refreshChartLines(); _refreshMobChartLines() }

    updateAccountValue(totalPerpEquity(perpState))
    // Health & liquidation push notifications are sent SERVER-SIDE ONLY (hliq-notify),
    // which checks all tracked wallets with a streak guard. The client used to also fire
    // these for the loaded account, which could double-send or false-trigger on transient
    // partial-refresh data — so it no longer does. (Price alerts stay client-side: they're
    // a local, user-defined feature the server doesn't track.)
    _checkPriceAlerts(state.allMids)
    updateRiskUI()
    if (isPaused()) updateSubmitBtn()

    refreshFailCount = 0
    updateRefreshBanner()
    updateWatchTicker()
    if (state.selectedCoin) updateChartStats(state.selectedCoin)
    updateMobileView()
    _hlOk()   // clean pass — reset the breaker's escalation

  } catch (e) {
    refreshFailCount++
    console.warn('Live refresh failed:', e.message)
    updateRefreshBanner()
    _hl429(e)   // rate limit → trip the global breaker (all pollers pause)
  } finally {
    _refreshInProgress = false
  }
}

// Pull fresh data right after a user action (place / close / cancel) so Orders, History,
// Positions and Calendar update immediately instead of waiting for the next gated tick.
// Handles all three account modes and waits out any in-flight refresh so the forced fetch
// actually runs. Fires TWICE — a quick pass, then a second ~2.5s later — because HL doesn't
// always have the new fill queryable on the first pass, and the combined view's heavy fan is
// slow; the second pass catches whatever the first missed.
function _doForcedRefresh() {
  try {
    if (state.isAllAccounts) {
      if (_allAcctRefreshing) { setTimeout(_doForcedRefresh, 350); return }   // busy — retry, don't drop it
      _allAcctSilentRefresh(_maLoad())
      return
    }
    if (isPaper()) return                                       // paper state is local — already current
    if (_refreshInProgress) { setTimeout(_doForcedRefresh, 250); return }  // let the in-flight tick finish, then force
    refreshLive(true)
  } catch {}
}
window.__refreshAfterAction = function(delay = 700, addr = null) {
  if (state.isAllAccounts) {
    // The combined view caches each wallet's all-time history (fills/portfolio/funding) for
    // 8 min — so a just-closed trade won't appear until it expires. Force fresh FILLS only:
    // the cached (portfolio snapshot + perp anchor) is a mutually-consistent pair, and the
    // value bridge `_portVal + (perpNow − _perpBase)` already reflects a close through the
    // live perp delta. Re-snapshotting mid-close instead re-baselines against a half-settled
    // account, which is what made equity jump right after closing a trade.
    //
    // If we know WHICH wallet the action hit, refresh only that one (fast, ~1 wallet's
    // requests) instead of re-fanning all N. Fall back to the full fan when it's unknown.
    if (addr) {
      try { _maLedgerCache.delete(String(addr).toLowerCase()) } catch {}
      setTimeout(() => _allAcctRefreshOne(addr), delay)
      setTimeout(() => _allAcctRefreshOne(addr), delay + 2300)
      return
    }
    try { _maFillsStale = true; _maLedgerCache.clear() } catch {}
    setTimeout(_doForcedRefresh, delay)
    return
  }
  setTimeout(_doForcedRefresh, delay)
  setTimeout(_doForcedRefresh, delay + 2300)   // second pass catches fills HL hadn't propagated yet
}

// Outcome (HIP-4 spot) fills reach HL's fill feed slower than perp fills, so the two
// passes above often miss them and History/Calendar only catch up on the ~15s fills tick.
// Poll a few times over ~11s instead, stopping the moment the new fill lands.
window.__refreshOutcomeClose = function(acct = null) {
  const single = !state.isAllAccounts && !isPaper()
  // Combined view: re-render straight from cache NOW so the pending-close clamp hides the
  // just-closed outcome instantly (as the single-account view does), instead of waiting on
  // the slow multi-wallet fan. The forced refreshes below then reconcile fills/history.
  if (state.isAllAccounts) { try { _allAcctReaggregate() } catch {} }
  // Combined view, known wallet: poll only THAT wallet for the new fill (outcome fills reach
  // HL's feed slower than perp fills), instead of re-fanning every account each tick.
  if (state.isAllAccounts && acct) {
    for (const t of [800, 2000, 3800, 6000, 9000]) setTimeout(() => _allAcctRefreshOne(acct), t)
    return
  }
  const start  = single ? (state.fills?.length ?? 0) : -1
  for (const t of [700, 1800, 3200, 5200, 7800, 11000]) {
    setTimeout(() => {
      if (single && (state.fills?.length ?? 0) > start) return   // fill already landed — stop polling
      if (state.isAllAccounts) { try { _maFillsStale = true; _maLedgerCache.clear() } catch {} }
      _doForcedRefresh()
    }, t)
  }
}
function renderChartPeriod(period) {
  state.currentPeriod = period
  document.querySelectorAll('.chart-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.period === period)
  })
  if (!state.portfolio?.length) return
  renderCharts(state.portfolio, period, state.fills ?? [])
}

// ─── AGENT KEY ────────────────────────────────────────────────────────────────
async function connectAgentKeyUI() {
  const keyVal   = document.getElementById('privateKeyInput').value.trim()
  const statusEl = document.getElementById('apiConnectStatus')
  const dotEl    = document.getElementById('apiStatusDot')

  if (!keyVal || !keyVal.startsWith('0x') || keyVal.length < 66) {
    statusEl.textContent = '✗ Invalid key — must be 0x followed by 64 hex characters.'
    statusEl.style.color = 'var(--red)'
    return
  }

  try {
    const addr = await connectAgentKey(keyVal)
    dotEl.classList.add('connected')
    statusEl.innerHTML = `✓ Connected: <span style="color:var(--accent)">${addr.slice(0, 6)}...${addr.slice(-4)}</span>`
    statusEl.style.color = 'var(--green)'
    if (state.addr) localStorage.setItem(_agentKeyForAddr(state.addr), keyVal)
    else localStorage.setItem('hliq_agent_key', keyVal)
    const stratInput = document.getElementById('agentKey')
    if (stratInput) stratInput.value = keyVal
    applyReferrer().catch(() => {})
    updateSubmitBtn()
    updateTradeBalance()
  } catch (e) {
    statusEl.textContent = '✗ ' + e.message
    statusEl.style.color = 'var(--red)'
    dotEl.classList.remove('connected')
  }
}

// ─── MAIN WALLET ──────────────────────────────────────────────────────────────
function openWalletPicker() {
  const list    = document.getElementById('walletPickerList')
  const wallets = getDiscoveredWallets()
  const isMob   = /iPhone|iPad|Android/i.test(navigator.userAgent)
  const appUrl  = encodeURIComponent(window.location.href)

  let html = wallets.map(w => `
    <button class="wallet-picker-btn" onclick="window.__pickWallet('${w.info.rdns}')">
      <img src="${w.info.icon}" width="28" height="28" style="border-radius:6px" onerror="this.style.display='none'"/>
      <span>${w.info.name}</span>
    </button>
  `).join('')

  if (wallets.length === 0 && !isMob) {
    html = `<p style="font-size:11px;color:var(--muted);text-align:center;padding:8px 0 4px">No wallet extensions detected in this browser.</p>`
  }

  const wcSep = (wallets.length > 0)
    ? `<div style="font-size:10px;color:var(--muted);text-align:center;margin:10px 0 6px;letter-spacing:.05em">OR SCAN WITH ANY WALLET</div>`
    : ''
  html += `
    ${wcSep}
    <button class="wallet-picker-btn" onclick="window.__pickWallet('walletconnect')">
      <svg width="28" height="28" viewBox="0 0 32 32" fill="none" style="border-radius:6px;background:#3b99fc;padding:4px">
        <path d="M9.6 12.8c3.5-3.5 9.3-3.5 12.8 0l.4.4a.4.4 0 010 .6l-1.4 1.4a.2.2 0 01-.3 0l-.6-.6c-2.4-2.4-6.4-2.4-8.8 0l-.6.6a.2.2 0 01-.3 0L9.4 13.8a.4.4 0 010-.6l.2-.4zm15.8 3l1.2 1.2a.4.4 0 010 .6l-5.6 5.6a.4.4 0 01-.6 0l-4-4a.1.1 0 00-.2 0l-4 4a.4.4 0 01-.6 0L5.4 17.6a.4.4 0 010-.6l1.2-1.2a.4.4 0 01.6 0l4 4a.1.1 0 00.2 0l4-4a.4.4 0 01.6 0l4 4a.1.1 0 00.2 0l4-4a.4.4 0 01.6 0z" fill="white"/>
      </svg>
      <span>WalletConnect <span style="color:var(--muted);font-size:10px">— Uniswap, Phantom &amp; 300+ wallets</span></span>
    </button>
  `

  list.innerHTML = html
  document.getElementById('walletPickerModal').style.display = 'flex'
}

window.__pickWallet = async function(rdns) {
  document.getElementById('walletPickerModal').style.display = 'none'
  const statusEl = document.getElementById('mainWalletStatus')
  const dotEl    = document.getElementById('mainWalletDot')
  const btn      = document.getElementById('mainWalletBtn')
  statusEl.textContent = 'Connecting...'
  statusEl.style.color = 'var(--muted)'
  try {
    // Only ask for a specific account when we're viewing a real one — the
    // All Accounts / Paper sentinels aren't addresses and would send the wallet
    // hunting for an account that can't exist.
    const _want = /^0x[0-9a-fA-F]{40}$/.test(state.addr ?? '') ? state.addr : null
    const addr = await connectWallet(rdns, _want)
    // Connecting is only needed to ACT on an account (deposit / withdraw / approve an
    // agent key) — all owner operations. Watching is free and never needs a wallet. So
    // the connected wallet MUST equal the address being viewed; otherwise we'd let one
    // wallet sign actions while the UI shows another account. Reject the mismatch.
    const viewing = (state.addr || '').toLowerCase()
    // Reject-and-notify helper: the inline status element is on the (desktop) trade tab
    // and is invisible inside the Settings modal, so surface an alert too — guaranteed
    // visible in any context (desktop trade tab, desktop Settings, mobile Settings).
    const rejectConnect = (inline, popup) => {
      // The wallet is left registered under the address it controls — it just isn't
      // usable from THIS view (All Accounts / Paper aren't single signable accounts).
      if (statusEl) { statusEl.innerHTML = inline; statusEl.style.color = 'var(--red)' }
      dotEl?.classList.remove('connected')
      _refreshWalletUI()
      alert(popup)
    }
    if (viewing === '__all_accounts__') {
      rejectConnect('✗ Open a single account to connect.',
        'Open a single account first — you can\'t connect a wallet in the All Accounts view.')
      return
    }
    // The paper account has no on-chain address, so the mismatch check below would
    // compare against the "__paper__" sentinel and print nonsense. Nothing in paper
    // needs a wallet anyway — it never signs.
    if (viewing === PAPER_ADDR) {
      rejectConnect('✗ The paper account doesn\'t use a wallet.',
        'The paper account is simulated — it never signs anything, so there is nothing to connect.\n\nSwitch to a real account first if you want to connect a wallet.')
      return
    }
    if (viewing && addr.toLowerCase() !== viewing) {
      const w = `${addr.slice(0,6)}…${addr.slice(-4)}`, v = `${viewing.slice(0,6)}…${viewing.slice(-4)}`
      // The wallet is KEPT — it's registered under the address it actually controls,
      // so it's ready the moment that account is opened. Multiple wallets can be
      // connected at once and each account routes to its own, so there's nothing to
      // reject here; just say what happened and offer to jump to that account.
      if (statusEl) { statusEl.innerHTML = `Connected <b>${w}</b> — open that account to use it.`; statusEl.style.color = 'var(--muted)' }
      _refreshWalletUI()
      if (confirm(
        `Connected ${w}.\n\n` +
        `You're viewing ${v}, which this wallet doesn't control, so it stays connected to ${w} and is kept for when you open it.\n\n` +
        `Open ${w} now?`
      )) {
        window.__quickLoad(addr)
      }
      return
    }
    if (state.addr) localStorage.setItem(_walletRdnsForAddr(state.addr), rdns)
    try {
      statusEl.textContent = 'Approving...'
      // Builder-fee approval is a user-signed EIP-712 action — HL accepts it on any
      // chain, so no chain switch is needed (signs on the wallet's current chain).
      const feeResult = await approveBuilderFee(getHlSigner())
      console.log('approveBuilderFee result:', JSON.stringify(feeResult))
      setBuilderFeeEnabled(true)
    } catch (e) {
      console.error('approveBuilderFee failed:', e)
      setBuilderFeeEnabled(false)
    }
    dotEl.classList.add('connected')
    statusEl.innerHTML = `✓ <span style="color:var(--accent)">${addr.slice(0,6)}...${addr.slice(-4)}</span> · Connected`
    statusEl.style.color = 'var(--green)'
    btn.textContent = 'Disconnect'
    btn.onclick = disconnectMainWalletUI
    // Privacy: joining the public leaderboard is OPT-IN. Connecting no longer auto-publishes
    // your address — the user adds themselves explicitly via the "➕ Add me" button, and can
    // remove themselves anytime (signature-proven). Never add an account without asking.
    _updateAutoGenBtnVisibility()   // wallet now connected → auto-gen buttons relabel
    _refreshWalletUI()              // repaint the Settings view so it shows Connected without a reopen
    window.__updateDepositPreview()
    window.__updateWithdrawPreview()
    refreshDefiBalances()
  } catch (e) {
    const msg = /proposal expired/i.test(e.message) ? 'Session expired — please reconnect'
              : /rejected|denied|cancel/i.test(e.message) ? 'Connection rejected'
              : e.message
    statusEl.textContent = '✗ ' + msg
    statusEl.style.color = 'var(--red)'
    dotEl.classList.remove('connected')
  }
}

// Repaint whichever wallet/settings surface is open so a connect/disconnect reflects
// immediately (the mobile Settings modal is re-rendered wholesale; it doesn't share the
// desktop trade-tab's live status element, so without this it only updated on reopen).
function _refreshWalletUI() {
  try {
    if (typeof _isMobView === 'function' && _isMobView() && _mobVActiveTab === 'settings') _mobVRenderContent()
    else _syncSettingsTab()
  } catch {}
}

function disconnectMainWalletUI() {
  if (state.addr) localStorage.removeItem(_walletRdnsForAddr(state.addr))
  disconnectMainWallet()
  setBuilderFeeEnabled(false)
  const dotEl = document.getElementById('mainWalletDot')
  const statusEl = document.getElementById('mainWalletStatus')
  const btn = document.getElementById('mainWalletBtn')
  dotEl.classList.remove('connected')
  statusEl.textContent = 'Connect to enable builder fee'
  statusEl.style.color = 'var(--muted)'
  btn.textContent = 'Connect Wallet'
  btn.onclick = openWalletPicker
  _updateAutoGenBtnVisibility()   // wallet gone → buttons relabel to "Connect wallet"
  _refreshWalletUI()
}

onWalletDisconnect(disconnectMainWalletUI)

window.connectMainWalletUI  = openWalletPicker
window.closeWalletPicker    = () => { document.getElementById('walletPickerModal').style.display = 'none' }
window.__sortOrders         = (key) => { if (!state.perpState) return; setSortOrd(key); renderOrders(state.openOrders, state.perpState, state.ocTokenMap) }
window.__sortMPos           = (key) => { if (!state.perpState) return; setSortMPos(key); renderManageTables(state.perpState, state.openOrders, state.allMids) }
window.__sortMOrd           = (key) => { if (!state.perpState) return; setSortMOrd(key); renderManageTables(state.perpState, state.openOrders, state.allMids) }
window.__tradesPrevPage = () => { if (!state.fills) return; setTradesPage(Math.max(0, getTradesPage() - 1)); renderTrades(state.fills) }
window.__tradesNextPage = () => { if (!state.fills) return; setTradesPage(getTradesPage() + 1); renderTrades(state.fills) }
window.__tradesDateFilter = () => { if (!state.fills) return; setTradesPage(0); renderTrades(state.fills) }

// ─── DEPOSIT / WITHDRAW ───────────────────────────────────────────────────────
let _depositDest = 'perps'

// Prefer element inside open mobile defi modal; fall back to global (desktop) element
function _defiEl(id) {
  const mob = document.getElementById('mobDefiModal')
  return (mob && mob.querySelector('#' + id)) || document.getElementById(id)
}

// Kept for compatibility — the Perps/Spot toggle is gone (a bridge deposit has no
// destination field), so the buttons may not exist. Never assume they do.
window.__setDepositDest = function(dest) {
  _depositDest = dest
  document.getElementById('depDest-perps')?.classList.toggle('active', dest === 'perps')
  document.getElementById('depDest-spot')?.classList.toggle('active', dest === 'spot')
  window.__updateDepositPreview()
}

let _usdcBalance      = null
let _withdrawAvailable = 0

window.__setDepositMax = function() {
  if (!_usdcBalance) return
  const el = _defiEl('depositAmount')
  if (el) { el.value = Math.floor(_usdcBalance * 100) / 100; window.__updateDepositPreview() }
}

window.__setWithdrawMax = function() {
  if (!_withdrawAvailable) return
  const el = _defiEl('withdrawAmount')
  if (el) { el.value = Math.floor(_withdrawAvailable * 100) / 100; window.__updateWithdrawPreview() }
}

window.__updateDepositPreview = function() {
  const amount  = parseFloat(_defiEl('depositAmount')?.value)
  const preview = _defiEl('depositPreview')
  const warning = _defiEl('depositWarning')
  const btn     = _defiEl('depositBtn')
  if (!preview) return

  const connected = isMainWalletConnected()
  const mobBanner = _defiEl('mobWalletBanner')
  if (mobBanner) mobBanner.style.display = connected ? 'none' : ''

  if (!connected) {
    btn.textContent = 'Connect Wallet'
    btn.disabled    = false
    btn.onclick     = () => window.__mobConnectWallet()
    preview.style.opacity = '0.4'
    warning.style.display = 'none'
    return
  }
  btn.onclick = () => window.__executeDeposit()
  if (!amount || amount <= 0) {
    preview.style.opacity = '0.4'
    warning.style.display = 'none'
    btn.disabled = true
    btn.textContent = 'Enter amount'
    return
  }
  if (amount < 5) {
    warning.style.display = 'block'
    warning.textContent   = '⚠ Minimum deposit is 5 USDC. Deposits below this amount will be permanently lost.'
    preview.style.opacity = '0.4'
    btn.disabled = true
    btn.textContent = 'Amount too low'
    return
  }
  if (_usdcBalance !== null && amount > _usdcBalance) {
    warning.style.display = 'block'
    warning.textContent   = `⚠ Insufficient balance. You have ${_usdcBalance.toFixed(2)} USDC on Arbitrum.`
    preview.style.opacity = '0.4'
    btn.disabled = true
    btn.textContent = 'Insufficient balance'
    return
  }
  warning.style.display = 'none'
  preview.style.opacity = '1'
  _defiEl('dp-send').textContent    = `${amount.toFixed(2)} USDC`
  _defiEl('dp-receive').textContent = `${amount.toFixed(2)} USDC`
  _defiEl('dp-dest').textContent    = 'Hyperliquid account'
  btn.disabled    = false
  btn.textContent = 'Deposit'
}

window.__updateWithdrawPreview = function() {
  const amount  = parseFloat(_defiEl('withdrawAmount')?.value)
  const dest    = _defiEl('withdrawDest')?.value.trim()
  const preview = _defiEl('withdrawPreview')
  const warning = _defiEl('withdrawWarning')
  const btn     = _defiEl('withdrawBtn')
  if (!preview) return

  const connected = isMainWalletConnected()
  const mobBanner = _defiEl('mobWalletBanner')
  if (mobBanner) mobBanner.style.display = connected ? 'none' : ''

  if (!connected) {
    btn.textContent = 'Connect Wallet'
    btn.disabled    = false
    btn.onclick     = () => window.__mobConnectWallet()
    preview.style.opacity = '0.4'
    warning.style.display = 'none'
    return
  }
  btn.onclick = () => window.__executeWithdraw()
  if (!amount || amount <= 0) {
    preview.style.opacity = '0.4'
    warning.style.display = 'none'
    btn.disabled = true
    btn.textContent = 'Enter amount'
    return
  }
  const receive = amount - 1
  if (receive <= 0) {
    warning.style.display = 'block'
    warning.textContent   = '⚠ Amount must be greater than the $1 withdrawal fee.'
    preview.style.opacity = '0.4'
    btn.disabled = true
    btn.textContent = 'Amount too low'
    return
  }
  if (!dest || !dest.startsWith('0x') || dest.length !== 42) {
    warning.style.display = 'none'
    preview.style.opacity = '0.4'
    btn.disabled = true
    btn.textContent = 'Enter destination'
    return
  }
  warning.style.display = 'none'
  preview.style.opacity = '1'
  _defiEl('wp-amount').textContent  = `${amount.toFixed(2)} USDC`
  _defiEl('wp-receive').textContent = `${receive.toFixed(2)} USDC`
  _defiEl('wp-dest').textContent    = `${dest.slice(0,8)}...${dest.slice(-6)}`
  btn.disabled    = false
  btn.textContent = 'Withdraw'
}

window.__useConnectedAddress = function() {
  const addr = getMainAddress()
  if (!addr) return
  const el = _defiEl('withdrawDest')
  if (el) { el.value = addr; window.__updateWithdrawPreview() }
}

window.__executeDeposit = async function() {
  const amount   = parseFloat(_defiEl('depositAmount').value)
  const statusEl = _defiEl('depositStatus')
  const btn      = _defiEl('depositBtn')
  btn.disabled = true
  try {
    const hash = await deposit({
      amount,
      destination: _depositDest,
      onStep: msg => { statusEl.innerHTML = `<span style="color:var(--muted)">${msg}</span>` },
    })
    statusEl.innerHTML = `<span style="color:var(--green)">✓ Deposit confirmed · <a href="https://arbiscan.io/tx/${hash}" target="_blank" rel="noopener" style="color:var(--accent)">View on Arbiscan</a></span>`
    _defiEl('depositAmount').value = ''
    window.__updateDepositPreview()
    refreshDefiBalances()
  } catch (e) {
    statusEl.innerHTML = `<span style="color:var(--red)">✗ ${e.message}</span>`
    btn.disabled = false
    window.__updateDepositPreview()
  }
}

/**
 * What a signing failure actually means.
 *
 * The SDK's top-level text is always "Failed to sign typed data with ethers v6 wallet" -
 * the reason lives on .cause, sometimes several deep. Two of those reasons are worth
 * naming rather than passing through:
 *
 *  - a declined prompt, which is not an error at all;
 *  - a broken injected provider. Telemetry recorded "Cannot redefine property: ethereum"
 *    25 times, which is what happens when two wallet extensions both try to install
 *    window.ethereum. Signing then fails no matter what the app does, and the generic
 *    message sends people looking for a bug in the withdrawal.
 */
function _signErrorText(e) {
  const parts = []
  for (let cur = e, n = 0; cur && n < 6; cur = cur.cause, n++) {
    const m = cur?.message || (n === 0 ? String(cur) : '')
    if (m && !parts.includes(m)) parts.push(m)
  }
  const all = parts.join(' — ')
  if (/reject|denied|cancell?ed|user refused/i.test(all)) {
    return _T('Cancelled in your wallet.', 'Cancelado en tu cartera.')
  }
  if (/redefine property: ethereum|only a getter|provider is disconnected|no ethereum provider/i.test(all)) {
    return _T('Your browser has more than one wallet extension fighting over the page, so it cannot sign. Disable the extras (or open the site in a browser with just one) and try again.',
              'Tu navegador tiene más de una extensión de cartera compitiendo por la página y no puede firmar. Desactiva las demás e inténtalo de nuevo.')
  }
  return parts[parts.length - 1] || all || _T('Signing failed', 'Falló la firma')
}

window.__executeWithdraw = async function() {
  const amount   = parseFloat(_defiEl('withdrawAmount').value)
  const dest     = _defiEl('withdrawDest').value.trim()
  const statusEl = _defiEl('withdrawStatus')
  const btn      = _defiEl('withdrawBtn')
  btn.disabled = true
  statusEl.innerHTML = '<span style="color:var(--muted)">Confirm in wallet...</span>'
  try {
    await withdraw({ amount, destination: dest })
    statusEl.innerHTML = `<span style="color:var(--green)">✓ Withdrawal submitted — arrives on Arbitrum in ~1 min</span>`
    _defiEl('withdrawAmount').value = ''
    window.__updateWithdrawPreview()
    refreshDefiBalances()
  } catch (e) {
    statusEl.innerHTML = `<span style="color:var(--red)">✗ ${esc(_signErrorText(e))}</span>`
    btn.disabled = false
    window.__updateWithdrawPreview()
  }
}

async function refreshDefiBalances() {
  const bal = await getUsdcBalance()
  _usdcBalance = bal
  const balEl = _defiEl('depositUsdcBal')
  if (balEl) balEl.textContent = bal !== null ? `${bal.toFixed(2)} USDC on Arbitrum` : '—'
  window.__updateDepositPreview()
}

// ─── TRADE BALANCE ────────────────────────────────────────────────────────────
// The agent wallet holds no funds — margin always lives in the master (state.addr) wallet.
let _tradePerpState = null  // refreshed clearinghouseState for the loaded wallet

function _renderTradeAccountStats(ps) {
  const tb = document.getElementById('tradeBalance')
  const tw = document.getElementById('tradeWithdrawable')
  if (!tb || !tw) return
  // Watch-only session: no wallet can trade, and the core-dex numbers shown here
  // (perp equity/withdrawable) don't match the unified totals elsewhere — dashes
  // are less confusing than balances the viewer can't act on.
  if (!isConnected()) { tb.textContent = '—'; tw.textContent = '—'; return }
  if (!ps?.marginSummary) return
  const val   = parseFloat(ps.marginSummary?.accountValue ?? 0)
  const wdraw = parseFloat(ps.withdrawable ?? 0)
  tb.textContent = '$' + fmtUSD(val)
  tw.textContent = '$' + fmtUSD(wdraw)
}

async function updateTradeBalance() {
  // Always render from the latest perpState so the header shows data without needing an agent key
  _renderTradeAccountStats(_tradePerpState ?? state.perpState)
  _updateAvailDisplay()

  if (!isConnected()) return
  if (_hlLimited()) return   // global 429 breaker
  const addr = state.addr
  if (!addr) return
  try {
    const info = new InfoClient({ transport: _transport })
    const s    = await info.clearinghouseState({ user: addr })
    // Account switched while this fetch was in flight — its balance/positions
    // belong to the old account. Discard so the trade tab never shows A's data
    // (balance, liq lines, size estimates) while B is loaded.
    if (state.addr !== addr) return
    _tradePerpState = s
    _renderTradeAccountStats(s)
    _updateAvailDisplay()
  } catch { /* non-critical */ }
}

// ─── COIN DROPDOWN ────────────────────────────────────────────────────────────
function populateCoinDropdown() {
  renderCoinDropdownItems('')
}

// ─── MARKET DROPDOWN STATE ────────────────────────────────────────────────────
let _mktCtxMap     = {}   // coin → { oi, volume, change24h, funding, markPx, ... }
let _mktCatMap     = {}   // coin → category string
let _spotNameMap   = {}   // @N / 'TOKEN/USDC' → display name
// name → market cap. _mktCtxMap is keyed by '@N' and 'TOKEN/USDC', but everywhere outside
// the markets list a coin is known by its plain name (Pulse rows, positions), so the lookup
// has to go through the name. Several keys can share one name; the biggest is the real token.
let _mktCapByName  = {}
let _spotPairToAt  = {}   // 'TOKEN/USDC' → '@N'  (used to deduplicate allMids entries)
let _spotCommunityKeys = new Set()  // @N keys with deployerTradingFeeShare == 0 (real community tokens)
let _spotProtocolKeys  = new Set()  // @N keys that are protocol-deployed spot (BTC/ETH/stocks/ETFs) — feeShare != 0
let _mktCtxReady   = false
let _mktHip3Ready = false  // separate gate so HIP-3 ctx is fetched once allMetas is available
let _mktDataInFlight = null // dedupe concurrent _ensureMarketData() calls (they each fired a full burst)
let _dropSort    = 'oi'
let _dropCat     = 'all'
let _dropType    = 'all'
// Actual category strings returned by perpCategories (lowercase, API is case-inconsistent)
const _TRADFI_CATS_LC = new Set(['stocks','commodities','indices','fx','metals','energy','preipo','rates'])
const _isTradFiCat = cat => !!cat && _TRADFI_CATS_LC.has(cat.toLowerCase())
// Display labels for raw category strings from the API
const _CAT_LABEL = { stocks:'Stocks', commodities:'Commodities', indices:'Indices', fx:'FX', FX:'FX', preipo:'Pre-IPO', crypto:'Crypto', metals:'Metals', energy:'Energy', rates:'Rates' }

// Main DEX TradFi perps that perpCategories doesn't cover (only HIP-3 DEXes are in that API)
const _MAIN_DEX_TRADFI_CATS = { 'SPX': 'indices' }
// Hardcoded coin base names for commodities subcategories (HL uses "commodities" for all of them)
const _METALS_BASES  = new Set(['GOLD','SILVER','PALLADIUM','PLATINUM','GOLDJM','SILVERJM','PAXG','GLDMINE'])
const _ENERGY_BASES  = new Set(['OIL','GAS','NATGAS','USOIL','WTI','BRENTOIL','CL','USENERGY'])

function _buildCtxEntry(c) {
  const mark = parseFloat(c.markPx ?? 0)
  const prev = parseFloat(c.prevDayPx ?? 0)
  return {
    oi:              parseFloat(c.openInterest ?? 0) * mark,
    volume:          parseFloat(c.dayNtlVlm ?? 0),
    change24:        prev > 0 ? (mark - prev) / prev * 100 : 0,
    change24Abs:     mark - prev,
    funding:         parseFloat(c.funding ?? 0) * 100,
    markPx:          mark,
    oraclePx:        parseFloat(c.oraclePx ?? 0),
    nextFundingTime: c.nextFundingTime ? parseInt(c.nextFundingTime) : null,
    prevDayPx:       prev,
  }
}

function _ensureMarketData() {
  if (_mktCtxReady && _mktHip3Ready) { _startHip3CtxLoader(); return Promise.resolve() }  // periodic staggered ctx refresh
  // Dedupe: several tabs/renders call this on mount; without a guard each fired its own
  // full ctx burst (main + spot + one metaAndAssetCtxs PER HIP-3 dex) concurrently — a
  // wall of weight-20 /info calls that 429'd. Share one in-flight load instead.
  if (_mktDataInFlight) return _mktDataInFlight
  // Don't pile onto an open rate-limit breaker; retry on a later call once it clears.
  if (_hlLimited()) return Promise.resolve()
  _mktDataInFlight = _doEnsureMarketData().finally(() => { _mktDataInFlight = null })
  return _mktDataInFlight
}

async function _doEnsureMarketData() {
  if (!_mktCtxReady) {
    // Use allSettled so any single failure doesn't block the rest
    const [mktR, catR, spotR, spotCtxR] = await Promise.allSettled([
      fetchMarketCtxs(), fetchPerpCategories(), fetchSpotMeta(), fetchSpotMarketCtxs()
    ])
    if (mktR.status === 'fulfilled') {
      const [meta, ctxs] = mktR.value
      _mktCtxMap = {}
      ;(meta.universe ?? []).forEach((u, i) => {
        const c = ctxs[i]
        if (!c) return
        _mktCtxMap[u.name] = _buildCtxEntry(c)
      })
      _mktCtxReady = true
    } else { console.warn('[hliq] fetchMarketCtxs failed:', mktR.reason) }

    if (catR.status === 'fulfilled') {
      _mktCatMap = {}
      for (const [coin, cat] of (catR.value ?? [])) _mktCatMap[coin] = cat
      // perpCategories only covers HIP-3 DEXes; inject known main DEX TradFi coins
      Object.assign(_mktCatMap, _MAIN_DEX_TRADFI_CATS)
    } else { console.warn('[hliq] fetchPerpCategories failed:', catR.reason) }

    if (spotR.status === 'fulfilled') {
      _spotNameMap  = {}
      _spotPairToAt = {}
      _spotCommunityKeys = new Set()
      _spotProtocolKeys  = new Set()
      const { tokens = [], universe = [] } = spotR.value ?? {}
      for (const u of universe) {
        const base    = tokens[u.tokens?.[0]]
        // Alias baked in HERE (not just in the market-list row) so every consumer — trade
        // detail header, chart title, position/order labels — shows "BTC" not "UBTC".
        const display = _spotDisplayAlias(base?.name ?? u.name)
        const atKey   = `@${u.index}`
        _spotNameMap[u.name] = display    // 'PURR/USDC' → 'PURR'
        _spotNameMap[atKey]  = display    // '@0' → 'PURR'
        _spotPairToAt[u.name] = atKey     // 'PURR/USDC' → '@0'
        // Split spot markets by deployer: community-created tokens (deployerTradingFeeShare == 0)
        // vs protocol-deployed synthetic assets (BTC/ETH/stocks/ETFs, feeShare != 0). The Spot tab
        // shows BOTH (like Hyperliquid) — protocol markets are why BTC/ETH/stocks must appear.
        if (parseFloat(base?.deployerTradingFeeShare ?? '0') === 0) _spotCommunityKeys.add(atKey)
        else _spotProtocolKeys.add(atKey)
      }
    } else { console.warn('[hliq] fetchSpotMeta failed:', spotR.reason) }

    if (spotCtxR.status === 'fulfilled') {
      const [, spotCtxs] = spotCtxR.value ?? [null, []]
      // spotCtxs is NOT index-parallel to universe — match via c.coin.
      // HL uses two key formats: '@N' (index) or 'TOKEN/USDC' (pair name).
      // Populate BOTH so the @N entry (only format shown in the list) always has data.
      for (const c of (spotCtxs ?? [])) {
        const key = c?.coin
        if (!key || key.startsWith('#')) continue
        const mark  = parseFloat(c.markPx ?? 0) || parseFloat(state.allMids?.[key] ?? 0)
        const prev  = parseFloat(c.prevDayPx ?? 0)
        const entry = {
          oi: 0, marketCap: parseFloat(c.circulatingSupply ?? 0) * mark,
          volume: parseFloat(c.dayNtlVlm ?? 0),
          change24: prev > 0 ? (mark - prev) / prev * 100 : 0,
          change24Abs: mark - prev, funding: 0,
          markPx: mark, oraclePx: 0, nextFundingTime: null, prevDayPx: prev,
        }
        _mktCtxMap[key] = entry
        const atKey = _spotPairToAt[key]   // if key is 'PURR/USDC', also set '@0'
        if (atKey && atKey !== key) _mktCtxMap[atKey] = entry
      }

      _mktCapByName = {}
      for (const [k, v] of Object.entries(_mktCtxMap)) {
        const name = _spotNameMap[k]
        const cap  = v?.marketCap ?? 0
        if (name && cap > (_mktCapByName[name] ?? 0)) _mktCapByName[name] = cap
      }

      // Deduplicate _spotCommunityKeys: multiple @N keys can share the same display name
      // (e.g. 4 different HYPE tokens). Keep only the highest-market-cap key per name,
      // and require the winner to have mktCap > $100K or dayNtlVlm > 0 to filter dead tokens.
      const _bestByName = {}
      for (const k of _spotCommunityKeys) {
        const name = _spotNameMap[k]
        if (!name) continue
        const ctx = _mktCtxMap[k]
        const mktCap = ctx?.marketCap ?? 0
        const vol    = ctx?.volume   ?? 0
        if (!_bestByName[name] || mktCap > (_mktCtxMap[_bestByName[name]]?.marketCap ?? 0)) {
          _bestByName[name] = k
        }
        // If same mktCap (both 0), prefer lower index (earlier, more canonical)
        if (mktCap === (_mktCtxMap[_bestByName[name]]?.marketCap ?? 0)) {
          const existingIdx = parseInt(_bestByName[name].slice(1))
          const thisIdx     = parseInt(k.slice(1))
          if (thisIdx < existingIdx) _bestByName[name] = k
        }
      }
      _spotCommunityKeys = new Set(
        Object.values(_bestByName).filter(k => {
          const ctx = _mktCtxMap[k]
          return (ctx?.marketCap ?? 0) > 100_000 || (ctx?.volume ?? 0) > 0
        })
      )
    } else { console.warn('[hliq] fetchSpotMarketCtxs failed:', spotCtxR.reason) }

  }
  // HIP-3 ctx is loaded lazily in the background, one dex at a time (see below) — NOT as a
  // burst here. Kick the drain now that _mktCatMap (the dex list) is populated.
  _startHip3CtxLoader()
}

// ─── HIP-3 market ctx: staggered background loader ─────────────────────────────
// metaAndAssetCtxs has no "all dexes" form, so every HIP-3 dex needs its own weight-20
// call. Fetching them all at once (even pooled) was the burst that 429'd and left TradFi
// blank. Instead we drain a queue a couple dexes at a time on a timer, filling _mktCtxMap
// incrementally and repainting the markets list as each lands. Dexes the user holds or
// watches are fetched first. Spreads the weight so it never trips the limiter, and always
// finishes — a rate-limited dex is requeued, not dropped.
let _hip3MetaTried   = false  // one attempt to fetch metas when the loader runs before a wallet
let _hip3CtxQueue    = null   // remaining dex names, or null when idle
let _hip3CtxTimer    = null
let _hip3CtxLoadedAt = 0
const _HIP3_CTX_TTL  = 300_000   // 5 min — refresh the (slow-moving) volume/OI/funding ctx
const _HIP3_CTX_BATCH = 2        // dexes fetched per tick
const _HIP3_CTX_EVERY = 3000     // ms between ticks

function _startHip3CtxLoader(force = false) {
  if (_hip3CtxTimer) return                                   // already draining
  if (!force && _mktHip3Ready && Date.now() - _hip3CtxLoadedAt < _HIP3_CTX_TTL) return
  const dexes = new Set()
  for (const coin of Object.keys(_mktCatMap)) {
    const ci = coin.indexOf(':')
    if (ci > 0) dexes.add(coin.slice(0, ci))
  }
  // perpCategories is NOT the list of dexes — it is the list of dexes that bothered to
  // categorise their markets. Deriving the queue from it alone meant three whole builder
  // dexes (25 markets on one of them) never had their ctx fetched, so their markets did
  // not exist anywhere in this app: not in the picker, not in search, not to a bot.
  // allPerpMetas is the authority on which dexes exist.
  for (const d of hip3DexNames(state.allMetas ?? [])) dexes.add(d)
  if (!dexes.size) {
    // No metas yet (the markets tab is reachable before any wallet loads). Fetch them once
    // and come back, rather than concluding the deployment has no builder dexes.
    if (!state.allMetas?.length && !_hip3MetaTried) {
      _hip3MetaTried = true
      infoClient.allPerpMetas()
        .then(m => { state.allMetas = m; _startHip3CtxLoader(true) })
        .catch(e => _hl429(e))
      return
    }
    _mktHip3Ready = true; return                              // no HIP-3 dexes on this deployment
  }
  // Priority: dexes the wallet holds positions/orders in, then watchlisted, then the rest.
  const priority = new Set([
    ...(state.perpState?.assetPositions ?? []).map(ap => String(ap.position?.coin ?? '').split(':')[0]),
    ...(state.openOrders ?? []).map(o => String(o.coin ?? '').split(':')[0]),
    ...loadWatchlist().map(c => String(c).split(':')[0]),
  ].filter(Boolean))
  _hip3CtxQueue = [...dexes].sort((a, b) => (priority.has(b) ? 1 : 0) - (priority.has(a) ? 1 : 0))
  _hip3CtxTick()                                              // fetch the first batch immediately
  _hip3CtxTimer = setInterval(_hip3CtxTick, _HIP3_CTX_EVERY)
}

async function _hip3CtxTick() {
  if (_hlLimited()) return                                    // breaker open — hold the queue, retry next tick
  if (!_hip3CtxQueue || !_hip3CtxQueue.length) {
    if (_hip3CtxTimer) { clearInterval(_hip3CtxTimer); _hip3CtxTimer = null }
    _hip3CtxQueue = null
    _mktHip3Ready = true
    _hip3CtxLoadedAt = Date.now()
    return
  }
  const batch = _hip3CtxQueue.splice(0, _HIP3_CTX_BATCH)
  const results = await hlPool(batch, dex =>
    fetchDexMarketCtxs(dex).then(r => ({ dex, r })).catch(e => { _hl429(e); return { dex, r: null } }), 2)
  let changed = false
  for (const { dex, r } of results) {
    if (!r) { _hip3CtxQueue.push(dex); continue }             // failed — requeue to retry at the end
    const [meta2, ctxs2] = r
    ;(meta2.universe ?? []).forEach((u, j) => {
      const c2 = ctxs2[j]
      if (!c2) return
      _mktCtxMap[u.name] = _buildCtxEntry(c2)
      changed = true
    })
    _mktHip3Ready = true                                      // partial data is enough to show the tab
  }
  if (changed) _repaintMarketsLive()
}

// Repaint whichever markets view is currently on screen, so staggered ctx fills in live.
function _repaintMarketsLive() {
  const rows = document.getElementById('mobMktRows')
  if (rows && _mobTradeView === 'list') rows.innerHTML = _mobBuildMarketRows()
  const dd = document.getElementById('coinDropdown')
  if (dd && dd.classList.contains('open')) {
    renderCoinDropdownItems(document.getElementById('coinDropdownSearch')?.value ?? '')
  }
}

// ─── FAVORITES ────────────────────────────────────────────────────────────────
function loadFavCoins()     { try { return JSON.parse(localStorage.getItem('favCoins') || '[]') } catch { return [] } }
function saveFavCoins(favs) { localStorage.setItem('favCoins', JSON.stringify(favs)) }
function isFav(coin)        { return loadFavCoins().includes(coin) }

window.__toggleFav = function(coin, e) {
  e.stopPropagation()
  const favs = loadFavCoins()
  const idx  = favs.indexOf(coin)
  if (idx >= 0) favs.splice(idx, 1)
  else favs.unshift(coin)
  saveFavCoins(favs)
  renderCoinDropdownItems(document.getElementById('coinDropdownSearch').value)
}
window.__dropSort = function(s) {
  _dropSort = s
  document.querySelectorAll('.mkt-th-sort').forEach(th => th.classList.toggle('active', th.dataset.col === s))
  renderCoinDropdownItems(document.getElementById('coinDropdownSearch')?.value ?? '')
}
window.__dropCat  = function(c) { _dropCat  = c; renderCoinDropdownItems(document.getElementById('coinDropdownSearch')?.value ?? '') }
window.__dropType = function(t) {
  _dropType = t; _dropCat = 'all'
  document.querySelectorAll('.mkt-type-btn').forEach(b => b.classList.toggle('active', b.dataset.type === t))
  renderCoinDropdownItems(document.getElementById('coinDropdownSearch')?.value ?? '')
}

function _coinColor(coin) {
  let h = 0
  for (let i = 0; i < coin.length; i++) h = (h * 31 + coin.charCodeAt(i)) % 360
  return `hsl(${h},62%,48%)`
}

