// ─── NEWS PAUSE ───────────────────────────────────────────────────────────────
let newsPauseEnabled = false
let newsPaused       = false
let riskMgmtEnabled  = false

window.__toggleNewsPause = function () {
  newsPauseEnabled = !newsPauseEnabled
  const btn = document.getElementById('btnNewsPause')
  if (btn) {
    btn.textContent = newsPauseEnabled ? 'Pause on News' : 'News Pause Off'
    btn.classList.toggle('active', newsPauseEnabled)
  }
  if (!newsPauseEnabled && newsPaused) {
    newsPaused = false
    updateNewsPauseUI(false)
  }
}

window.__checkNewsAlert = function (headline) {
  if (!newsPauseEnabled || !headline.trim()) {
    if (newsPaused) { newsPaused = false; updateNewsPauseUI(false) }
    return
  }
  const raw  = document.getElementById('newsKeywords')?.value ?? ''
  const keys = raw.split(',').map(k => k.trim().toLowerCase()).filter(Boolean)
  const hit  = keys.find(k => headline.toLowerCase().includes(k))
  if (hit && !newsPaused) {
    newsPaused = true
    updateNewsPauseUI(true, hit)
    updateSubmitBtn()
  } else if (!hit && newsPaused) {
    newsPaused = false
    updateNewsPauseUI(false)
    updateSubmitBtn()
  }
}

function updateNewsPauseUI(paused, keyword) {
  const el = document.getElementById('newsPauseStatus')
  if (!el) return
  if (paused) {
    el.innerHTML = `<span class="risk-status-dot" style="background:var(--red)"></span>
      <span style="font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--red)">
        News pause: "${keyword}" detected
      </span>`
  } else {
    el.innerHTML = `<span class="risk-status-dot" style="background:var(--green)"></span>
      <span style="font-family:'JetBrains Mono',monospace;font-size:11px">News: clear</span>`
  }
}

// ─── MOBILE STRATEGIES ────────────────────────────────────────────────────────
let _gridRangeMode     = 'price'   // 'price' | 'pct' — shared desktop + mobile
let _mobGridSpacing    = 'usd'
let _mobDcaMode        = 'time'
let _mobDcaSide        = 'long'
let _mobLongerTrigger  = 'always'
let _mobShorterTrigger = 'always'
let _mobAccumDryRun    = false  // Profit Stack: LIVE by default. Dry-run first meant the common
                                // case was arming a bot that quietly did nothing — the mode is a
                                // segmented control now, so which one is selected is unmissable.
let _mobEditing        = null   // { type, instance } when editing a running bot's config in-place
let _mobExpandedStrat  = null
let _mobLogStream      = null

function _applyGridDefaults(coinId, lowerId, upperId) {
  // Sync the Long/Short toggle + card title with the persisted side
  const sideTog = document.getElementById('tog-grid-side')
  if (sideTog) {
    const isShort = _gridSide === 'short'
    sideTog.textContent = isShort ? 'Short' : 'Long'
    sideTog.classList.toggle('active', !isShort)
  }
  // Sync the Cross/Isolated toggle with the persisted margin mode
  const marginTog = document.getElementById('tog-grid-margin')
  if (marginTog) {
    const isIso = _gridMargin === 'isolated'
    marginTog.textContent = isIso ? 'Isolated' : 'Cross'
    marginTog.classList.toggle('active', !isIso)
  }
  const coinEl = document.getElementById(coinId)
  if (coinEl && !coinEl.value) coinEl.placeholder = state.selectedCoin || 'BTC'
  // Resolve the same way the launch path does. Looking the raw text up in allMids meant a
  // HIP-3 market typed the way it is displayed — "SPCX", "GOPRO" — found no price, so the
  // auto lower/upper bounds silently stayed empty for every builder-dex market.
  const coin = _resolveGridCoin(coinEl?.value?.trim() || coinEl?.placeholder || 'BTC')
  const px = parseFloat(state.allMids?.[coin] ?? 0)
  const lowerEl = document.getElementById(lowerId)
  const upperEl = document.getElementById(upperId)
  // NEVER pre-fill values — empty fields mean the bot auto-ranges ±10% around
  // the live mark of whatever coin it starts with. Placeholders only preview
  // that, and update as the coin changes (pre-filled values went stale).
  if (_gridRangeMode === 'pct') {
    if (lowerEl) lowerEl.placeholder = '-10'
    if (upperEl) upperEl.placeholder = '10'
  } else {
    // Mirror the bot's auto-range: if a position is open in this coin, anchor the
    // band to the AVERAGE ENTRY (long: avg → avg+12%, short: avg−12% → avg); else mark ±10%.
    const BAND = 0.12
    const isShort = _gridSide === 'short'
    const apos = (state.perpState?.assetPositions ?? []).find(a => a.position?.coin === coin)
    const szi  = parseFloat(apos?.position?.szi ?? 0)
    const avg  = parseFloat(apos?.position?.entryPx ?? 0)
    const hasPos = avg > 0 && (isShort ? szi < 0 : szi > 0)
    let lo, up
    if (hasPos) {
      if (isShort) { up = avg; lo = Math.min(avg, px || avg) * (1 - BAND) }
      else         { lo = avg; up = Math.max(avg, px || avg) * (1 + BAND) }
    } else if (px) {
      lo = px * 0.90; up = px * 1.10
    }
    if (lowerEl) lowerEl.placeholder = lo ? `auto ~${lo.toFixed(2)}${hasPos ? ' (avg)' : ''}` : 'auto'
    if (upperEl) upperEl.placeholder = up ? `auto ~${up.toFixed(2)}${hasPos ? ' (avg)' : ''}` : 'auto'
  }
}
window._applyGridDefaults = _applyGridDefaults

// Convert grid lower/upper input to absolute price (handles both price and % mode)
function _gridRangeToPrice(val, coin) {
  if (!val) return ''
  if (_gridRangeMode !== 'pct') return val
  const px = parseFloat(state.allMids?.[(coin || state.selectedCoin || 'BTC').toUpperCase()] ?? 0)
  if (!px) return val
  return (px * (1 + parseFloat(val) / 100)).toFixed(2)
}

function toggleGridRange(btn) {
  const isPct = _gridRangeMode === 'price'   // about to switch TO pct
  _gridRangeMode = isPct ? 'pct' : 'price'

  // Update desktop toggle button + labels
  const togBtn = document.getElementById('tog-grid-range')
  if (togBtn) { togBtn.textContent = isPct ? '%' : '$'; togBtn.classList.toggle('active', isPct) }
  const lblU = document.getElementById('lbl-grid-upper')
  const lblL = document.getElementById('lbl-grid-lower')
  if (lblU) lblU.textContent = isPct ? 'Upper %' : 'Upper Price'
  if (lblL) lblL.textContent = isPct ? 'Lower %' : 'Lower Price'

  // Convert existing values
  const coin = (document.getElementById('grid-coin')?.value?.trim() || state.selectedCoin || 'BTC').toUpperCase()
  const px = parseFloat(state.allMids?.[coin] ?? 0)
  const lowerEl = document.getElementById('grid-lower')
  const upperEl = document.getElementById('grid-upper')
  if (px) {
    if (isPct) {
      if (lowerEl?.value) lowerEl.value = (((parseFloat(lowerEl.value) / px) - 1) * 100).toFixed(1)
      if (upperEl?.value) upperEl.value = (((parseFloat(upperEl.value) / px) - 1) * 100).toFixed(1)
    } else {
      if (lowerEl?.value) lowerEl.value = (px * (1 + parseFloat(lowerEl.value) / 100)).toFixed(2)
      if (upperEl?.value) upperEl.value = (px * (1 + parseFloat(upperEl.value) / 100)).toFixed(2)
    }
  }
  if (lowerEl) lowerEl.placeholder = isPct ? '-10' : 'auto'
  if (upperEl) upperEl.placeholder = isPct ? '10'  : 'auto'

  // Re-render mobile form to pick up new labels/placeholders
  const mobEl = document.getElementById('mobVContent')
  if (mobEl && _mobExpandedStrat === 'grid') _mobVRenderStrategies(mobEl)
}
window.toggleGridRange = toggleGridRange

function _mobExpandStrat(type) {
  if (_mobEditing && _mobEditing.type !== type) _mobEditing = null   // leaving the edited card cancels the edit
  _mobExpandedStrat = _mobExpandedStrat === type ? null : type
  if (!_mobExpandedStrat) _mobEditing = null
  const el = document.getElementById('mobVContent')
  if (el) _mobVRenderStrategies(el)
  if (type === 'grid' && _mobExpandedStrat === 'grid' && !_mobEditing) {
    setTimeout(() => _applyGridDefaults('m-grid-coin', 'm-grid-lower', 'm-grid-upper'), 0)
  }
  // Profit Stack is one-per-account, so opening its card while one is running can only
  // mean editing that one. Enter edit mode automatically — otherwise the card shows a
  // "▶ Run" button that the server rejects with "already running", which is what made
  // changing a setting mid-run look like it silently did nothing.
  if (type === 'accumulator' && _mobExpandedStrat === 'accumulator' && !_mobEditing
      && serverStatus?._configs?.['accumulator:']) {
    setTimeout(() => _mobEditStratInstance('accumulator', ''), 0)
  }
}

// ─── EDIT A RUNNING BOT'S CONFIG IN-PLACE ───────────────────────────────────────
// Parse a launched instance's argv (['--coin','HYPE',...]) back into a {flag: value} map.
function _parseStratArgs(argv) {
  const out = {}
  for (let i = 0; i < (argv || []).length; i++) {
    const a = argv[i]
    if (typeof a !== 'string' || !a.startsWith('--')) continue
    const key = a.slice(2)
    const next = argv[i + 1]
    if (next === undefined || (typeof next === 'string' && next.startsWith('--'))) out[key] = true
    else { out[key] = next; i++ }
  }
  return out
}

// Open the bot's config card pre-filled with a specific running instance's live config.
function _mobEditStratInstance(type, instance) {
  const cfg = serverStatus?._configs?.[`${type}:${instance}`]
  if (!cfg) { alert('Config not available yet — wait a second and try again.'); return }
  const p = _parseStratArgs(cfg.args)
  if (type === 'grid')             _mobEditGridInstance(instance, p)
  else if (type === 'accumulator') _mobEditAccumInstance(instance, p)
}

// Profit Stack edit. Without this the card had no edit path at all: expanding it and
// hitting the button ran runStrategyMob(), which the server rejects with "already
// running" — so changing a setting mid-run appeared to do nothing. One instance per
// account, so `instance` is always ''.
function _mobEditAccumInstance(instance, p) {
  // Toggle state must be set BEFORE the card renders (it drives the field HTML), same
  // rule as the grid editor.
  _mobAccumDryRun   = !!p['dry-run']
  _mobEditing       = { type: 'accumulator', instance }
  _mobExpandedStrat = 'accumulator'
  const el = document.getElementById('mobVContent')
  if (el) _mobVRenderStrategies(el)
  // Inputs exist only after that render — fill them next tick.
  setTimeout(() => {
    const set = (id, v) => { const e = document.getElementById(id); if (e && v != null && v !== true) e.value = v }
    set('m-accum-asset',     p.asset)
    set('m-accum-cut',       p['cut-pct'])
    set('m-accum-threshold', p.threshold)
    set('m-accum-maxdaily',  p['max-daily'])
  }, 0)
}

function _mobEditGridInstance(instance, p) {
  // Toggle state must be set BEFORE the card renders (it drives the field HTML).
  _gridSide       = (p.side === 'short') ? 'short' : 'long'
  _gridMargin     = (p.margin === 'isolated') ? 'isolated' : 'cross'
  _mobGridSpacing = (p['pct-interval'] != null) ? 'pct' : 'usd'
  _gridRangeMode  = 'price'   // args store ABSOLUTE prices; price mode passes them through unchanged
  _mobEditing     = { type: 'grid', instance }
  _mobExpandedStrat = 'grid'
  const el = document.getElementById('mobVContent')
  if (el) _mobVRenderStrategies(el)
  // Inputs exist only after the render above — fill them next tick.
  setTimeout(() => {
    const set = (id, v) => { const e = document.getElementById(id); if (e && v != null && v !== true) e.value = v }
    set('m-grid-coin',      p.coin)
    set('m-grid-lower',     p.lower)
    set('m-grid-upper',     p.upper)
    set('m-grid-levels',    p['pct-interval'] != null ? p['pct-interval'] : p.levels)
    set('m-grid-leverage',  p.leverage)
    set('m-grid-totmargin', p['total-margin'])
    set('m-grid-entry-gap', p['entry-gap'])
    const szEl = document.getElementById('m-grid-size')
    if (szEl && p.size != null && p.size !== true) {
      szEl.value = p.size; szEl.dataset.mode = 'usd'
      const tog = document.getElementById('m-tog-grid-size')
      if (tog) { tog.textContent = 'USD'; tog.classList.remove('active') }
    }
  }, 0)
}

function _mobCancelEdit() {
  _mobEditing = null
  const el = document.getElementById('mobVContent')
  if (el) _mobVRenderStrategies(el)
}

// ─── DESKTOP: EDIT A RUNNING BOT'S CONFIG IN-PLACE (grid only, mirrors mobile) ───
let _deskEditing = null

function _deskEditStratInstance(type, instance) {
  const cfg = serverStatus?._configs?.[`${type}:${instance}`]
  if (!cfg) { alert('Config not available yet — wait a second and try again.'); return }
  const p = _parseStratArgs(cfg.args)
  if (type === 'grid') _deskEditGridInstance(instance, p)
}
window._deskEditStratInstance = _deskEditStratInstance

function _deskEditGridInstance(instance, p) {
  // Toggle state must be set BEFORE filling — args store ABSOLUTE prices in price mode.
  _gridSide      = (p.side === 'short') ? 'short' : 'long'
  _gridMargin    = (p.margin === 'isolated') ? 'isolated' : 'cross'
  _gridSpacing   = (p['pct-interval'] != null) ? 'pct' : 'usd'
  _gridRangeMode = 'price'
  _deskEditing   = { type: 'grid', instance }

  // Sync the desktop toggle buttons to the loaded config.
  const isShort = _gridSide === 'short'
  const togSide = document.getElementById('tog-grid-side')
  if (togSide) { togSide.textContent = isShort ? 'Short' : 'Long'; togSide.classList.toggle('active', !isShort) }
  const isIso = _gridMargin === 'isolated'
  const togMargin = document.getElementById('tog-grid-margin')
  if (togMargin) { togMargin.textContent = isIso ? 'Isolated' : 'Cross'; togMargin.classList.toggle('active', !isIso) }
  const isPctSpace = _gridSpacing === 'pct'
  const togSpace = document.getElementById('tog-grid-spacing')
  if (togSpace) { togSpace.textContent = isPctSpace ? '%' : '$'; togSpace.classList.toggle('active', isPctSpace) }
  const lblLevels = document.getElementById('lbl-grid-levels')
  if (lblLevels) lblLevels.textContent = isPctSpace ? 'Level Spacing %' : 'Grid Levels'
  const togRange = document.getElementById('tog-grid-range')
  if (togRange) { togRange.textContent = '$'; togRange.classList.remove('active') }
  const lblU = document.getElementById('lbl-grid-upper'); if (lblU) lblU.textContent = 'Upper Price'
  const lblL = document.getElementById('lbl-grid-lower'); if (lblL) lblL.textContent = 'Lower Price'

  // Fill inputs.
  const set = (id, v) => { const e = document.getElementById(id); if (e && v != null && v !== true) e.value = v }
  set('grid-coin',      p.coin)
  set('grid-lower',     p.lower)
  set('grid-upper',     p.upper)
  set('grid-levels',    p['pct-interval'] != null ? p['pct-interval'] : p.levels)
  set('grid-leverage',  p.leverage)
  set('grid-totmargin', p['total-margin'])
  set('grid-entry-gap', p['entry-gap'])
  const szEl = document.getElementById('grid-size')
  if (szEl && p.size != null && p.size !== true) {
    szEl.value = p.size; szEl.dataset.mode = 'usd'
    const tog = document.getElementById('tog-grid-size')
    if (tog) { tog.textContent = 'USD'; tog.classList.remove('active') }
  }

  // Inline Update / Cancel banner in the grid card's command-output slot.
  const out = document.getElementById('cmd-grid')
  if (out) {
    out.innerHTML = `<div class="strategy-run-row" style="flex-wrap:wrap;align-items:center;gap:8px">
      <span style="font-size:11px;color:var(--accent);font-weight:700;flex:1 0 100%">✎ Editing ${esc(instance || 'default')} — change fields, then Update</span>
      <button class="btn-run-strategy" onclick="updateStrategy('grid')">✓ Update ${esc(instance || '')}</button>
      <button class="btn-stop-strategy" onclick="_deskCancelEdit()" style="display:inline-block">Cancel</button>
    </div>`
  }
  document.getElementById('strat-grid')?.scrollIntoView({ behavior: 'smooth', block: 'start' })
}

function _deskCancelEdit() {
  _deskEditing = null
  const out = document.getElementById('cmd-grid'); if (out) out.innerHTML = ''
}
window._deskCancelEdit = _deskCancelEdit

// An edit stops the running bot and starts it again with the new settings. If the start
// is refused, the stop has already happened — so without these two the bot is simply gone,
// which is what a "subscription required" on a dev-mode phone actually did: silently
// killed a live bot on an account the operator owns.
//
// Two independent protections, because they fail for different reasons.

/**
 * Is a start going to be ALLOWED, before we stop anything?
 *
 * Mirrors the server's rule (see POST /api/start): an active subscription for that
 * address, OR operator rights proven by the dev PIN. Dev mode is a local flag and the
 * server has only ever recognised the PIN that earned it, so a device where the two
 * drifted apart — dev mode on, PIN missing or rotated — unlocked every button and then
 * got a 402 on the press. Now the PIN is re-verified (and re-prompted if needed) BEFORE
 * anything is stopped, which is the thing dev mode was supposed to give in the first place.
 */
async function _canStartBot(addr) {
  if (isPaper()) return true          // simulated account, simulated orders — nothing to gate
  if (_subStatus?.active) return true
  if (!isDev()) return false
  // Prompt-and-verify self-heals a stale or missing PIN; _lbAdminPin caches on success.
  let pin = _lbGetPin()
  if (pin) {
    try {
      const r = await fetch('/api/leaderboard/verify-pin', { method: 'POST', headers: { 'x-lb-pin': pin } })
      if (r.ok) return true
    } catch { return true }   // offline: don't block on a check we cannot make
    localStorage.removeItem('hliq_lb_pin')   // rotated or wrong — stop sending it
  }
  pin = await _lbAdminPin(true)
  return !!pin
}

/**
 * Put back what the edit took away.
 *
 * The last-resort net for every OTHER reason a restart can fail — a dropped connection,
 * a rejected agent key, the server restarting mid-edit. The instance's original argv is
 * still in serverStatus._configs, so the previous bot can be started again exactly as it
 * was. Reported honestly either way: the user must never be left believing a bot is
 * running when it is not.
 */
async function _restoreBotAfterFailedEdit(type, instance, agentKey, origArgs, why) {
  if (!Array.isArray(origArgs) || !origArgs.length) {
    alert(`Could not update: ${why}\n\nThe previous bot was stopped and could not be restored automatically — please start it again.`)
    return
  }
  try {
    const back = await serverFetch('/api/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, agentKey, args: origArgs, address: _stratTargetAddr(), instance }),
    })
    if (back?.ok) {
      serverStatus[type] = true
      checkServer()
      alert(`Could not update: ${why}\n\nYour previous settings are still running — nothing was lost.`)
      return
    }
    alert(`Could not update: ${why}\n\nThe previous bot was stopped and could not be restarted (${back?.error ?? 'unknown error'}) — please start it again.`)
  } catch {
    alert(`Could not update: ${why}\n\nThe previous bot was stopped and the server is unreachable — please start it again.`)
  }
}

// Apply a desktop edit: stop the edited instance, relaunch with the new args.
async function updateStrategy(type) {
  const ed = _deskEditing
  if (!ed || ed.type !== type) return runStrategy(type)
  const agentKey = (state.addr ? localStorage.getItem(_agentKeyForAddr(state.addr)) : null)
                || document.getElementById('agentKey')?.value?.trim()
  if (!agentKey) { alert('Enter your Agent Private Key above.'); return }
  if (!state.addr) { alert('Load a wallet address before updating a strategy.'); return }
  await ensureAllMids()
  const argv    = buildArgv(type)
  const newInst = _argvInstance(argv)
  // Checked BEFORE the stop, so a refusal costs nothing.
  if (!(await _canStartBot(_stratTargetAddr()))) { alert(_stratLockedMsg()); return }
  const origArgs = serverStatus?._configs?.[`${type}:${ed.instance}`]?.args
  try {
    await _postStop(type, ed.instance)               // stop the instance being edited
    await new Promise(r => setTimeout(r, 600))
    const r = await serverFetch('/api/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, agentKey, args: argv, address: _stratTargetAddr(), instance: newInst }),
    })
    if (!r.ok) { await _restoreBotAfterFailedEdit(type, ed.instance, agentKey, origArgs, r.error); return }
    _deskEditing = null
    const out = document.getElementById('cmd-' + type); if (out) out.innerHTML = ''
    serverStatus[type] = true
    checkServer()
    updateAllStrategyButtons()
    _verifyStarted(type, newInst)
  } catch { alert('Server unreachable. Is hliq-strat running?') }
}
window.updateStrategy = updateStrategy

// Apply an edit: re-launch the SAME (or coin-changed) instance with the new args. Stateful
// bots keep their cumulative counters via --resume; grid/others just re-adopt the position.
async function updateStrategyMob(type) {
  const ed = _mobEditing
  if (!ed || ed.type !== type) return runStrategyMob(type)
  const agentKey = _stratTargetKey()
                || document.getElementById('m-agentKey')?.value?.trim()
                || document.getElementById('agentKey')?.value?.trim()
  if (!agentKey) { alert('Enter your Agent Private Key above.'); return }
  await ensureAllMids()
  const argv    = buildArgvMob(type)
  const newInst = _argvInstance(argv)
  if (type === 'accumulator' || type === 'liqguard' || type === 'levbrake') argv.push('--resume')
  // Checked BEFORE the stop, so a refusal costs nothing.
  if (!(await _canStartBot(_stratTargetAddr()))) { _paperToast(_stratLockedMsg(), 'err'); return }
  const origArgs = serverStatus?._configs?.[`${type}:${ed.instance}`]?.args
  try {
    await _postStop(type, ed.instance)               // stop the instance being edited
    await new Promise(r => setTimeout(r, 600))
    const r = await serverFetch('/api/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, agentKey, args: argv, address: _stratTargetAddr(), instance: newInst }),
    })
    if (!r.ok) { await _restoreBotAfterFailedEdit(type, ed.instance, agentKey, origArgs, r.error); return }
    _mobEditing = null
    serverStatus[type] = true
    checkServer()
    _verifyStarted(type, newInst)
  } catch { alert('Server unreachable. Is hliq-strat running?') }
}

// ─── BOT PREVIEW ──────────────────────────────────────────────────────────────
//
// What the bot would do the moment you press Run, drawn on the price it would do it at.
//
// The plan is NOT recomputed here. The server runs the real strategy with --plan, which
// performs its own setup — resolving the range (it can anchor to an open position's
// average entry), reading how much capital is actually available, deriving the per-level
// size from it — then prints the orders and exits before placing any of them. A second
// implementation in the browser would drift from the bot and show a plan it was never
// going to follow, which is worse than no preview at all.
//
// Only bots whose opening move is knowable up front are listed. A trigger-based bot has
// no orders to show until its condition fires.
const PREVIEWABLE = new Set(['grid'])

window.__botPreview = async function(type) {
  const agentKey = _stratTargetKey()
                || document.getElementById('m-agentKey')?.value?.trim()
                || document.getElementById('agentKey')?.value?.trim()
  const target = _stratTargetAddr()
  if (!target)   { _paperToast(_T('Pick which account to preview on first', 'Elige primero en qué cuenta'), 'err'); return }
  if (!agentKey) { _paperToast(_T('Connect an agent key first', 'Conecta una clave de agente primero'), 'err'); return }

  _botPreviewSheet(type, null, true)
  try {
    await ensureAllMids()
    const argv = buildArgvMob(type)
    const r = await serverFetch('/api/plan', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, agentKey, args: argv, address: target }),
    })
    _botPreviewSheet(type, r, false)
  } catch (e) {
    _botPreviewSheet(type, { ok: false, error: e.message || 'Server unreachable' }, false)
  }
}

window.__closeBotPreview = function() { document.getElementById('botPreviewSheet')?.remove() }

/**
 * The ladder, drawn against price. Levels are placed by PRICE, not by index, so uneven
 * spacing (percentage grids) shows as uneven rungs rather than being flattened into an
 * evenly-spaced picture the bot is not going to trade.
 */
function _previewChartHtml(plan) {
  const orders = (plan.orders ?? []).filter(o => Number.isFinite(+o.px))
  if (orders.length < 2) return ''
  const pxs = orders.map(o => +o.px).concat(+plan.markPx)
  const lo = Math.min(...pxs), hi = Math.max(...pxs)
  const span = (hi - lo) || 1
  const H = Math.max(190, orders.length * 26)
  const y = (px) => 14 + (1 - (px - lo) / span) * (H - 28)

  // Why a level is not going on the book this cycle. 'margin' and 'inventory' are the two
  // that mean "wanted but cannot" — they get the loud treatment. 'resting' and 'near' are
  // ordinary states, so they are merely quiet.
  const WHY = {
    margin:    { txt: () => _T('no margin', 'sin margen'),      loud: true },
    inventory: { txt: () => _T('no inventory', 'sin inventario'), loud: true },
    losing:    { txt: () => _T('would lose', 'cerraría en pérdida'), loud: true },
    resting:   { txt: () => _T('already there', 'ya está'),      loud: false },
    near:      { txt: () => _T('waits for price', 'espera precio'), loud: false, soon: true },
  }
  const rung = (o) => {
    const yy = y(+o.px)
    const buy = o.side === 'buy'
    const why = o.blocked ? WHY[o.blocked] : null
    const live = !o.blocked
    const col = why?.loud ? 'var(--red)' : buy ? 'var(--green)' : 'var(--red)'
    // A held-back level is drawn faint and struck through, so the ladder still shows the
    // shape the grid is aiming for while making clear which rungs are not on the book.
    const dim = live ? '1' : why?.loud ? '.62' : '.34'
    // A level waiting on price is a normal, momentary state - it goes on the book the
    // instant the mark moves off it. Striking it through like a refusal said otherwise.
    const strike = live || why?.soon ? '' : ';text-decoration:line-through'
    return `<div style="position:absolute;left:0;right:0;top:${yy - 9}px;height:18px;display:flex;align-items:center;gap:6px;opacity:${dim}">
      <span style="width:38px;flex-shrink:0;text-align:right;font-size:9.5px;font-weight:800;color:${col};text-transform:uppercase">${buy ? _T('Buy', 'Compra') : _T('Sell', 'Venta')}</span>
      <span style="flex:1;height:0;border-top:1.5px ${live ? (buy ? 'solid' : 'dashed') : 'dotted'} ${col};opacity:.75"></span>
      ${why ? `<span style="flex-shrink:0;font-size:8.5px;font-weight:800;text-transform:uppercase;letter-spacing:.03em;color:${why.loud ? 'var(--red)' : 'var(--fg-3)'};white-space:nowrap">${why.txt()}</span>` : ''}
      <span style="flex-shrink:0;font-size:10.5px;font-family:var(--font-mono);color:var(--fg-2)${strike}">${fmtSize(o.sz)} @ $${fmtPrice(o.px)}</span>
    </div>`
  }
  const markY = y(+plan.markPx)
  return `<div style="position:relative;height:${H}px;margin:10px 0 4px">
    ${orders.map(rung).join('')}
    <div style="position:absolute;left:0;right:0;top:${markY - 9}px;height:18px;display:flex;align-items:center;gap:6px">
      <span style="width:38px;flex-shrink:0;text-align:right;font-size:9.5px;font-weight:800;color:var(--fg)">${_T('Mark', 'Precio')}</span>
      <span style="flex:1;height:0;border-top:2px solid var(--fg)"></span>
      <span style="flex-shrink:0;font-size:11px;font-weight:800;font-family:var(--font-mono)">$${fmtPrice(plan.markPx)}</span>
    </div>
  </div>`
}

/**
 * The position the grid is about to be started on top of.
 *
 * Direction is the part that changes what the bot does, so it leads. A grid pointing the
 * SAME way adds to the position and its exits take profit against the average entry. A
 * grid pointing the other way spends its entries reducing what is already open before it
 * holds anything of its own — and its exits find no inventory at all, because grid.js only
 * counts a position as inventory when it points the same way.
 */
function _previewPositionHtml(plan) {
  const raw = plan.position
  if (!raw) return ''
  // The page and strategies/ deploy separately, so a freshly-loaded UI can meet a plan
  // from the previous bot build for a few minutes. Every field below is optional and a
  // missing one renders as a dash — one absent number must not blank the whole sheet.
  const n = (v) => Number.isFinite(+v) ? +v : null
  const p = {
    ...raw,
    szi: n(raw.szi) ?? 0,
    side: raw.side ?? (n(raw.szi) < 0 ? 'short' : 'long'),
    entryPx: n(raw.entryPx), value: n(raw.value), uPnl: n(raw.uPnl), roe: n(raw.roe),
    marginUsed: n(raw.marginUsed), liqPx: n(raw.liqPx), funding: n(raw.funding),
    aligned: raw.aligned !== false,
  }
  const long = p.side === 'long'
  const tone = long ? 'var(--green)' : 'var(--red)'
  const pnlTone = p.uPnl == null ? 'var(--fg)' : p.uPnl >= 0 ? 'var(--green)' : 'var(--red)'
  const bit = (label, value, col) => `<div style="flex:1;min-width:78px">
    <div style="font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;font-weight:700">${label}</div>
    <div style="font-size:12.5px;font-weight:700;margin-top:1px;color:${col || 'var(--fg)'}">${value}</div>
  </div>`

  return `<div style="margin-top:10px;background:var(--panel-1);border:1px solid ${p.aligned ? 'var(--border2)' : 'var(--red)'};border-radius:9px;padding:11px 12px">
    <div style="display:flex;align-items:center;gap:7px;margin-bottom:9px">
      <span style="font-size:9.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:#000;background:${tone};border-radius:4px;padding:2px 6px">${
        long ? _T('Long', 'Largo') : _T('Short', 'Corto')}</span>
      <span style="font-size:12.5px;font-weight:700">${fmtSize(Math.abs(p.szi))} ${esc(_ocCoinLabel(plan.coin))}</span>
      <span style="flex:1"></span>
      <span style="font-size:10.5px;color:var(--muted)">${_T('open now', 'abierta ahora')}</span>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      ${bit(_T('Entry', 'Entrada'), p.entryPx == null ? '—' : '$' + fmtPrice(p.entryPx))}
      ${bit(_T('Value', 'Valor'), p.value == null ? '—' : '$' + fmtUSD(p.value))}
      ${bit(_T('Unrealized', 'No realizado'), p.uPnl == null ? '—' : `${p.uPnl >= 0 ? '+' : '−'}$${fmtUSD(Math.abs(p.uPnl))}`, pnlTone)}
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:9px">
      ${bit(_T('Return', 'Retorno'), p.roe == null ? '—' : `${p.roe >= 0 ? '+' : ''}${p.roe.toFixed(1)}%`, pnlTone)}
      ${bit(_T('Margin used', 'Margen usado'), p.marginUsed == null ? '—' : '$' + fmtUSD(p.marginUsed))}
      ${bit(_T('Liquidation', 'Liquidación'), p.liqPx > 0 ? '$' + fmtPrice(p.liqPx) : '—', p.liqPx > 0 ? 'var(--orange,#f59e0b)' : null)}
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:9px">
      ${bit(_T('Leverage', 'Apalancamiento'), p.leverage ? p.leverage + '× ' + esc(p.levType ?? '') : '—')}
      ${bit(_T('Funding paid', 'Financiación'), p.funding == null ? '—' : `${p.funding <= 0 ? '+' : '−'}$${fmtUSD(Math.abs(p.funding))}`, p.funding == null || p.funding <= 0 ? 'var(--green)' : 'var(--red)')}
      ${bit(_T('vs this grid', 'vs este grid'), p.aligned ? _T('same way', 'misma dirección') : _T('opposite', 'opuesta'), p.aligned ? 'var(--green)' : 'var(--red)')}
    </div>
    <div style="font-size:10.5px;line-height:1.5;margin-top:9px;color:${p.aligned ? 'var(--fg-3)' : 'var(--red)'}">
      ${p.aligned
        ? _T('The grid adds to this position, and its sells take profit against your average entry — it will not close below it.',
             'El grid añade a esta posición, y sus ventas toman beneficio contra tu entrada media — nunca cierra por debajo.') +
          (plan.autoRange ? ' ' + _T('The range was anchored to that entry.', 'El rango se ancló a esa entrada.') : '')
        : _T('Your position points the other way. The grid\'s entries will reduce it before opening anything of its own, and its exits find no inventory to sell until it does.',
             'Tu posición va en sentido contrario. Las entradas del grid la reducirán antes de abrir nada propio, y sus salidas no encuentran inventario que vender hasta entonces.')}
    </div>
  </div>`
}

function _botPreviewSheet(type, plan, loading) {
  document.getElementById('botPreviewSheet')?.remove()
  const cell = (label, value, tone) => `<div style="flex:1;min-width:86px">
    <div style="font-size:9.5px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;font-weight:700">${label}</div>
    <div style="font-size:13.5px;font-weight:700;margin-top:2px;color:${tone || 'var(--fg)'}">${value}</div>
  </div>`

  let body
  if (loading) {
    body = `<div style="padding:40px 16px;text-align:center;font-size:12.5px;color:var(--muted)">${
      _T('Asking the bot what it would do…', 'Preguntando al bot qué haría…')}</div>`
  } else if (!plan?.ok) {
    // The bot's own refusal is the answer — it is what Run would have said too.
    body = `<div style="padding:22px 16px">
      <div style="font-size:12.5px;color:var(--red);line-height:1.5">${esc(plan?.error || 'Could not build a preview')}</div>
      <div style="font-size:11px;color:var(--fg-3);margin-top:10px;line-height:1.5">${
        _T('This is what the bot itself said when asked to set up with these settings — pressing Run would hit the same thing.',
           'Esto es lo que dijo el propio bot con esta configuración — pulsar Run daría lo mismo.')}</div>
    </div>`
  } else {
    const buys  = plan.orders.filter(o => o.side === 'buy').length
    const sells = plan.orders.length - buys
    // Capital first: the size per level is derived from it, so a plan that does not fit
    // is the single most useful thing this screen can tell you.
    const fitTone = plan.fits ? 'var(--green)' : 'var(--red)'
    body = `<div style="padding:14px 16px 18px">
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        ${cell(_T('Placing now', 'Coloca ahora'), `${plan.willPlace ?? plan.orders.length}`, 'var(--green)')}
        ${cell(_T('Held back', 'Retenidas'), `${plan.heldBack ?? 0}`, (plan.heldBack ?? 0) > 0 ? 'var(--red)' : 'var(--fg)')}
        ${cell(_T('Already there', 'Ya puestas'), `${plan.resting ?? 0}`)}
      </div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:12px">
        ${cell(_T('Buy / Sell', 'Compra / Venta'), `<span style="color:var(--green)">${buys}</span> / <span style="color:var(--red)">${sells}</span>`)}
        ${cell(_T('Per level', 'Por nivel'), '$' + fmtUSD(plan.orderUsd))}
        ${cell(_T('Margin each', 'Margen c/u'), '$' + fmtUSD(plan.perOrderMargin ?? (plan.orderUsd / plan.leverage)))}
      </div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:12px">
        ${cell(_T('Margin needed', 'Margen necesario'), '$' + fmtUSD(plan.requiredMargin), fitTone)}
        ${cell(_T('Your capital', 'Tu capital'), '$' + fmtUSD(plan.capital), 'var(--fg)')}
        ${cell(_T('Leverage', 'Apalancamiento'), plan.leverage + '× ' + plan.margin)}
      </div>
      <div style="font-size:10.5px;color:var(--fg-3);margin-top:8px;line-height:1.5">${
        _T('Sizing comes from', 'El tamaño sale de')} ${esc(plan.capitalSource || '')}${
        plan.autoSize ? ' · ' + _T('size chosen automatically', 'tamaño elegido automáticamente') : ''}${
        plan.autoRange ? ' · ' + _T('range chosen automatically', 'rango elegido automáticamente') : ''}</div>

      ${(() => {
        const short = (plan.orders ?? []).filter(o => o.blocked === 'margin')
        const inv   = (plan.orders ?? []).filter(o => o.blocked === 'inventory')
        const near  = (plan.orders ?? []).filter(o => o.blocked === 'near')
        if (!short.length && !inv.length && !near.length) return ''
        const money = (n) => '$' + fmtPrice(n)
        const bad = short.length || inv.length
        return `<div style="margin-top:10px;font-size:11.5px;color:${bad ? 'var(--red)' : 'var(--fg-2)'};background:${bad ? 'rgba(255,77,109,.08)' : 'var(--panel-1)'};border-radius:8px;padding:10px 12px;line-height:1.55">
          ${short.length ? `<div><b>${short.length} ${short.length === 1 ? _T('level', 'nivel') : _T('levels', 'niveles')}</b> ${
            _T('will not go on the book — not enough margin', 'no se colocarán — falta margen')}: ${short.map(o => money(o.px)).join(', ')}.
            ${_T('The bot keeps retrying them as margin frees.', 'El bot los reintenta cuando se libera margen.')}</div>` : ''}
          ${inv.length ? `<div style="${short.length ? 'margin-top:6px' : ''}"><b>${inv.length} ${inv.length === 1 ? _T('level', 'nivel') : _T('levels', 'niveles')}</b> ${
            (inv.length === 1 ? _T('has nothing left to sell', 'no tiene nada que vender')
                              : _T('have nothing left to sell', 'no tienen nada que vender'))}: ${inv.map(o => money(o.px)).join(', ')}.
            ${_T('Exits are backed by the position, so these appear as it grows.', 'Las salidas se respaldan con la posición, así que aparecen cuando crece.')}</div>` : ''}
          ${near.length ? `<div style="${short.length || inv.length ? 'margin-top:6px' : ''};color:var(--fg-2)">${
            _T('One level sits too close to the mark to be an entry yet', 'Un nivel está demasiado cerca del precio para ser entrada aún')}: ${
            near.map(o => money(o.px)).join(', ')}. ${
            _T('The grid leaves half a level of clearance around the mark so a level cannot flip between entry and exit on ordinary noise. An auto-chosen range centres the mark exactly between two levels, so the nearest one starts right on that line and goes on the book as soon as price moves off it.',
               'El grid deja medio nivel de holgura alrededor del precio para que un nivel no cambie entre entrada y salida por ruido normal. Un rango automático centra el precio justo entre dos niveles, así que el más cercano empieza en esa línea y se coloca en cuanto el precio se mueve.')}</div>` : ''}
        </div>`
      })()}

      ${_previewPositionHtml(plan)}

      ${_previewChartHtml(plan)}

      <div style="font-size:10.5px;color:var(--fg-3);margin-top:8px;line-height:1.5">${
        _T('Every one is a resting limit order. Nothing has been placed — this ran the bot\'s own setup and stopped before it could.',
           'Todas son órdenes límite en espera. No se ha colocado nada — esto ejecutó la preparación del propio bot y se detuvo antes de poder hacerlo.')}</div>
    </div>`
  }

  const wrap = document.createElement('div')
  wrap.id = 'botPreviewSheet'
  wrap.innerHTML = `
    <div onclick="window.__closeBotPreview()" style="position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:8999"></div>
    <div style="position:fixed;bottom:0;left:0;right:0;z-index:9000;background:var(--panel-2);border-radius:20px 20px 0 0;padding:0 0 env(safe-area-inset-bottom);max-height:88vh;overflow-y:auto">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:16px 16px 12px;border-bottom:1px solid var(--border)">
        <div>
          <div style="font-size:16px;font-weight:700">${_T('Preview', 'Vista previa')}${plan?.ok ? ' · ' + esc(_ocCoinLabel(plan.coin)) : ''}</div>
          <div style="font-size:11px;color:var(--muted);margin-top:1px">${
            plan?.ok ? `${esc(plan.side)} ${_T('grid', 'grid')} · $${fmtPrice(plan.lower)} – $${fmtPrice(plan.upper)}`
                     : _T('Nothing is placed', 'No se coloca nada')}</div>
        </div>
        <button onclick="window.__closeBotPreview()" style="background:none;border:none;color:var(--muted);font-size:22px;cursor:pointer;line-height:1;padding:0 4px">×</button>
      </div>
      ${body}
      ${plan?.ok ? `<div style="display:flex;gap:8px;padding:0 16px 18px">
        <button onclick="window.__closeBotPreview();window.runStrategyMob('${type}')" style="flex:1;padding:12px;border-radius:10px;border:none;background:var(--accent);color:#000;font-size:14px;font-weight:700;cursor:pointer">▶ ${_T('Run it', 'Ejecutar')}</button>
        <button onclick="window.__closeBotPreview()" style="flex:1;padding:12px;border-radius:10px;border:1px solid var(--border2);background:transparent;color:var(--fg-2);font-size:14px;font-weight:700;cursor:pointer">${_T('Back', 'Volver')}</button>
      </div>` : ''}
    </div>`
  document.body.appendChild(wrap)
}

