// Read-only list of every bot running across the combined view's accounts.
// Returns the list rather than painting it, so the combined Strategies tab can show the
// running bots ABOVE the launch UI instead of choosing between them.
function _mobVRenderAllAcctStrats(el) { el.innerHTML = `<div style="padding:14px 12px calc(90px + env(safe-area-inset-bottom))">${_allAcctRunningHtml()}</div>` }

function _allAcctRunningHtml() {
  const labels = { dca: 'DCA Bot', grid: 'Grid Bot', trend: 'Trend Follower', longer: 'Longer Bot', shorter: 'Shorter Bot', accumulator: '🪙 Profit Stack', liqguard: '🛡 Liq Guard', levbrake: '🛑 Lev Brake', insolvent: 'Manager', twap: 'TWAP', ocgrid: 'Outcome Grid' }
  const wallets  = _maLoad()
  const hidden   = _maHiddenLoad()
  const labelFor = a => wallets.find(w => w.addr.toLowerCase() === a.toLowerCase())?.label || (a.slice(0, 6) + '…' + a.slice(-4))
  const rows = []
  for (const [addr, bots] of Object.entries(_maBotStatus || {})) {
    if (!Array.isArray(bots) || !bots.length || hidden.has(addr)) continue
    if (!wallets.some(w => w.addr.toLowerCase() === addr.toLowerCase())) continue
    for (const bot of bots) {
      const [type, ...rest] = String(bot).split(':')
      rows.push({ addr, label: labelFor(addr), type, inst: rest.join(':') })
    }
  }
  rows.sort((a, b) => a.label.localeCompare(b.label) || a.type.localeCompare(b.type))
  // The old copy told the user to switch to a single account to start a bot. That is no
  // longer true — the launch UI below arms on whichever account the picker names.
  return `
    <div style="font-size:16px;font-weight:700;margin-bottom:3px">${_T('Running Bots · All Accounts', 'Bots activos · Todas las cuentas')}</div>
    <div style="font-size:11.5px;color:var(--muted);margin-bottom:14px;line-height:1.5">${
      _T('Every bot running across the accounts in this view.', 'Todos los bots activos en las cuentas de esta vista.')}</div>
    ${rows.length ? rows.map(r => `
      <div class="mob-v-row" style="align-items:center">
        <span style="width:9px;height:9px;border-radius:50%;background:var(--green);flex-shrink:0;margin-right:11px;box-shadow:0 0 6px var(--green)"></span>
        <div class="mob-v-row-info">
          <div class="mob-v-row-name">${esc(labels[r.type] || r.type)}${r.inst ? ` · ${esc(r.inst)}` : ''}</div>
          <div class="mob-v-row-sub"><span class="notranslate" style="color:var(--accent)">${esc(r.label)}</span></div>
        </div>
        <button class="mob-v-setting-btn" onclick="window._mobShowStratLogs('${esc(r.type)}','${esc(r.inst)}','${esc(r.addr)}')">Logs</button>
      </div>`).join('') : `<div class="mob-v-empty">${
        _T('No bots running on any account in this view.', 'Ningún bot activo en las cuentas de esta vista.')}</div>`}`
}

// Read a "--flag value" pair out of a persisted bot's launch args.
function _argVal(args, flag, def) { const i = (args || []).indexOf(flag); return (i >= 0 && args[i + 1] != null) ? args[i + 1] : def }

// One-line live status for a running bot (surfaces the state that was previously
// invisible — chiefly the Profit Stack's buffer + LIVE/dry-run mode).
function _stratRunStatus(type) {
  if (type !== 'accumulator') return 'Running'
  const cfg  = serverStatus?._configs?.['accumulator:']
  const args = cfg?.args || []
  const dry  = args.includes('--dry-run')
  const asset = String(_argVal(args, '--asset', 'HYPE')).toUpperCase()
  const thr   = _argVal(args, '--threshold', '11')
  const acc   = serverStatus?._accum?.[asset]
  const parts = [dry ? '🧪 Dry-run' : '🟢 LIVE']
  if (acc) parts.push(`buffer $${(acc.buffer || 0).toFixed(2)}/$${thr}`, `stacked ${(acc.lifetimeQty || 0).toFixed(2)} ${asset}`)
  return parts.join(' · ')
}

// ─── STRATEGY SUBSCRIPTION (client side) ──────────────────────────────────────
//
// This gate is COSMETIC. The real one is in server.js at /api/start, because that is where
// a strategy actually spawns — hiding the tab would stop nobody who can open devtools. What
// lives here is the explanation and the purchase flow, not the enforcement.
//
// Paying is a plain Hyperliquid Send. Nothing is asked of the user afterwards: the server
// watches the treasury's ledger and credits the sending wallet, so there is no transaction
// hash to copy and no form to fill in.
let _subStatus = null      // { active, until, trialAvailable, treasury, ... }
let _subFetchAt = 0
let _subFetching = false
let _subWatchUntil = 0     // ms — poll hard while the user is mid-payment
let _subWatchTimer = null

async function _subRefresh(force = false) {
  const addr = _botApiAddr()
  if (!addr || _subFetching) return
  if (!force && Date.now() - _subFetchAt < 60_000) return
  _subFetching = true
  const was = _stratsUnlocked()
  try {
    const r = await fetch(`/api/sub/status?address=${encodeURIComponent(addr)}`)
    if (r.ok) { _subStatus = await r.json(); _subFetchAt = Date.now() }
  } catch {} finally {
    _subFetching = false
    // Only rebuild when the answer actually changed. A blind re-render every minute would
    // wipe whatever the user is typing into the strategy config forms.
    if (_mobVActiveTab === 'strategies' && _stratsUnlocked() !== was) _mobVRenderContent()
  }
}

// Dev mode is a local override for the owner; a paid subscription is the real entitlement.
// Paper is unlocked because there is nothing to sell there: no real orders, no real money,
// and the whole point of a practice account is to try the product before paying for it.
function _stratsUnlocked() { return isPaper() || isDev() || !!_subStatus?.active }
function _stratLockedMsg() {
  return _T('Running a bot needs a subscription. Nothing was changed and your bot is untouched.',
            'Ejecutar un bot requiere suscripción. No se cambió nada y tu bot sigue igual.')
}

// ── payment watching ─────────────────────────────────────────────────────────
// Once the user says they have sent it we poke the server every few seconds. The server
// polls Hyperliquid on its own timer anyway; this just shortens the wait from ~30s to
// ~5s while someone is staring at the screen. Survives a reload.
function _subWatchRestore() {
  const t = Number(localStorage.getItem('hliq_sub_watch') ?? 0)
  if (t > Date.now()) { _subWatchUntil = t; _subWatchStart() }
}
function _subWatchStart() {
  if (_subWatchTimer) return
  _subWatchTimer = setInterval(_subWatchTick, 6000)
  _subWatchTick()
}
function _subWatchStop() {
  if (_subWatchTimer) { clearInterval(_subWatchTimer); _subWatchTimer = null }
  _subWatchUntil = 0
  try { localStorage.removeItem('hliq_sub_watch') } catch {}
}
async function _subWatchTick() {
  const addr = _botApiAddr()
  if (!addr || Date.now() > _subWatchUntil) { _subWatchStop(); _subPaintWatch(); return }
  try {
    const r = await fetch('/api/sub/check', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address: addr }),
    })
    const j = await r.json().catch(() => ({}))
    if (j.active) {
      _subWatchStop()
      await _subRefresh(true)
      _paperToast(_T('Subscription active — strategies unlocked', 'Suscripción activa'), 'ok')
      window.__subClosePaywall()
      _mobVRenderContent()
      return
    }
    // Partial payment: tell them exactly what is missing rather than leaving them staring
    // at a spinner that will never resolve.
    if (Number(j.credit) > 0 && _subStatus) _subStatus.credit = Number(j.credit)
  } catch {}
  _subPaintWatch()
}
// Repaint just the status line. Re-rendering the whole pane would collapse the "paid from
// another wallet" disclosure and drop focus out of its input.
function _subPaintWatch() {
  const el = document.getElementById('subWatchLine')
  if (el) el.innerHTML = _subWatchHtml()
}
function _subWatchHtml() {
  const price = _subStatus?.priceUsdc ?? 10
  const credit = Number(_subStatus?.credit) || 0
  if (credit > 0) {
    return `<span style="color:#ff9f43">${_T('Received', 'Recibido')} $${credit.toFixed(2)} — ${_T('send', 'envía')} $${(price - credit).toFixed(2)} ${_T('more to activate', 'más para activar')}</span>`
  }
  if (_subWatchUntil > Date.now()) {
    return `<span class="sub-watching">${_T('Watching for your payment…', 'Esperando tu pago…')}</span>`
  }
  return `<span style="color:var(--muted)">${_T('Activation is automatic, usually within a minute.', 'La activación es automática, normalmente en un minuto.')}</span>`
}

// Pay from inside the app. The whole point of the terminal is that a normal user never
// has to open Hyperliquid itself, and sending them there to copy an address was exactly
// the thing this app exists to avoid. One signature, no bridge, no chain switch.
//
// It needs the MAIN wallet connected, not just an agent key: Hyperliquid API wallets can
// trade but cannot move funds. When there is no wallet to sign with we fall back to
// showing the address, which is the only thing left that can work.
window.__subPayNow = async function() {
  const st = _subStatus
  const dest = st?.treasury
  const amount = st?.priceUsdc ?? 10
  if (!dest) { _paperToast(_T('Loading…', 'Cargando…'), 'err'); return }

  if (!isMainWalletConnected()) {
    if (_isMobView()) window.__mobConnectWallet?.(); else openWalletPicker()
    return
  }
  const main = getMainAddress()?.toLowerCase()
  const target = _botApiAddr()?.toLowerCase()
  // The wallet that signs is the wallet that gets credited, because that is what the
  // server sees in the ledger. Say so plainly instead of enabling the wrong account.
  if (main && target && main !== target) {
    const ok = confirm(_T(
      `Your connected wallet is ${main.slice(0,6)}…${main.slice(-4)}, but you are viewing ${target.slice(0,6)}…${target.slice(-4)}.\n\n` +
      `The subscription is credited to the wallet that pays, so this would enable ${main.slice(0,6)}…${main.slice(-4)}.\n\nContinue?`,
      `Tu cartera conectada es ${main.slice(0,6)}…${main.slice(-4)}, pero estás viendo ${target.slice(0,6)}…${target.slice(-4)}.\n\n` +
      `La suscripción se acredita a la cartera que paga, así que esto activaría ${main.slice(0,6)}…${main.slice(-4)}.\n\n¿Continuar?`))
    if (!ok) return
  }

  const btn = document.getElementById('subPayBtn')
  const set = (txt, dis) => { if (btn) { btn.disabled = dis; btn.textContent = txt } }
  set(_T('Check your wallet…', 'Revisa tu billetera…'), true)
  try {
    // Mobile WalletConnect relays the prompt to the wallet app without switching to it,
    // so the signature screen never surfaces — same deep-link nudge the agent-key flow uses.
    const send = sendUsdcOnCore({ from: main, destination: dest, amount, signer: getHlSigner() })
    setTimeout(() => { try { wakeWallet() } catch {} }, 350)
    await send

    _paperToast(_T('Sent — activating…', 'Enviado — activando…'), 'ok')
    // The transfer settles on HyperCore in about a second, but the server still has to
    // see it in the treasury's ledger. Start the watcher rather than claiming success.
    window.__subSent()
  } catch (e) {
    // Walk the whole cause chain. The SDK's top-level message is always the generic
    // "Failed to sign typed data with ethers wallet" — the reason the user actually cares
    // about (and the word "rejected") is nested underneath, sometimes more than one deep.
    const parts = []
    for (let cur = e, n = 0; cur && n < 6; cur = cur.cause, n++) {
      const m = cur?.message || (n === 0 ? String(cur) : '')
      if (m && !parts.includes(m)) parts.push(m)
    }
    const full = parts.join(' · ')
    let msg = full
    if (/rejected|denied|cancel|user ?abort/i.test(full)) msg = _T('Payment cancelled.', 'Pago cancelado.')
    else if (/must deposit|does not exist/i.test(full)) msg = _T('This wallet has no funds on Hyperliquid yet.', 'Esta cartera aún no tiene fondos en Hyperliquid.')
    _paperToast(msg.split('\n')[0].slice(0, 120), 'err')
    console.error('subscription payment failed:', e)
  } finally {
    set(`${_T('Pay')} $${amount} USDC`, false)
  }
}

window.__subSent = function() {
  if (!_botApiAddr()) { _paperToast(_T('Load a wallet first', 'Carga una cuenta primero'), 'err'); return }
  _subWatchUntil = Date.now() + 10 * 60_000
  try { localStorage.setItem('hliq_sub_watch', String(_subWatchUntil)) } catch {}
  _subWatchStart()
  _subPaintWatch()
}

window.__subStartTrial = async function() {
  const addr = _botApiAddr()
  if (!addr) { _paperToast(_T('Load a wallet first', 'Carga una cuenta primero'), 'err'); return }
  try {
    const r = await fetch('/api/sub/trial', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address: addr }),
    })
    const j = await r.json().catch(() => ({}))
    if (!r.ok) { _paperToast(j.error || _T('Could not start the trial', 'No se pudo iniciar la prueba'), 'err'); return }
    _paperToast(_T('Trial started', 'Prueba iniciada'), 'ok')
    await _subRefresh(true)
    window.__subClosePaywall()
    _mobVRenderContent()
  } catch { _paperToast(_T('Server unreachable', 'Servidor no disponible'), 'err') }
}

// Nominate the wallet the payment will come from, when it is not the one being enabled.
window.__subPayFrom = async function() {
  const payer = document.getElementById('subPayer')?.value?.trim()
  const addr = _botApiAddr()
  if (!/^0x[0-9a-fA-F]{40}$/.test(payer || '')) { _paperToast(_T('Enter the paying wallet', 'Introduce la cartera que paga'), 'err'); return }
  try {
    const r = await fetch('/api/sub/payfrom', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address: addr, payer }),
    })
    if (!r.ok) { _paperToast(_T('Could not save that', 'No se pudo guardar'), 'err'); return }
    _paperToast(_T('Saved — send from that wallet', 'Guardado — envía desde esa cartera'), 'ok')
  } catch { _paperToast(_T('Server unreachable', 'Servidor no disponible'), 'err') }
}

window.__subCopyTreasury = function(btn) {
  const a = _subStatus?.treasury ?? ''
  try {
    navigator.clipboard.writeText(a)
    if (btn) { const o = btn.innerHTML; btn.innerHTML = _T('Copied', 'Copiado'); setTimeout(() => { btn.innerHTML = o }, 1400) }
  } catch {}
}

// The compact lock strip that sits above the bot list. It has to answer "what am I
// buying?" on its own, because the full pitch is now one tap away rather than in the way.
function _subLockBanner() {
  const st = _subStatus
  const T = (en, es) => _T(en, es ?? en)
  const price = st?.priceUsdc ?? 10
  const days  = st?.periodDays ?? 30
  const trial = st?.trialAvailable && (st?.trialDays > 0)
  const credit = Number(st?.credit) || 0
  return `<div class="sub-lock">
    <div class="sub-lock-top">
      <span class="sub-lock-badge">🔒 ${T('Locked')}</span>
      <span class="sub-lock-price">$${price}<span> / ${days} ${T('days')}</span></span>
    </div>
    <div class="sub-lock-txt">${T('Browse and configure any bot below. Running one needs a subscription — they trade on our servers around the clock, with the app closed.')}</div>
    ${credit > 0 ? `<div class="sub-lock-credit">${T('Received')} $${credit.toFixed(2)} — ${T('send')} $${(price - credit).toFixed(2)} ${T('more to activate')}</div>` : ''}
    <div class="sub-lock-btns">
      ${trial ? `<button class="sub-lock-b primary" onclick="window.__subStartTrial()">${T('Start free trial')} · ${st.trialDays}d</button>` : ''}
      <button class="sub-lock-b ${trial ? '' : 'primary'}" onclick="window.__subOpenPaywall()">${trial ? T('Subscribe') : `${T('Subscribe')} · $${price}`}</button>
    </div>
  </div>`
}

// The full pitch, as a sheet over the bot list rather than instead of it.
window.__subOpenPaywall = function() {
  let ov = document.getElementById('subPaywallOverlay')
  if (!ov) {
    ov = document.createElement('div')
    ov.id = 'subPaywallOverlay'
    ov.className = 'sub-sheet'
    document.body.appendChild(ov)
  }
  ov.innerHTML = `
    <div class="sub-sheet-head">
      <button onclick="window.__subClosePaywall()" aria-label="Close">✕</button>
      <span>${_T('Automated strategies', 'Estrategias automáticas')}</span>
    </div>
    <div class="sub-sheet-body">${_subPaywallHtml()}</div>`
  ov.style.display = 'flex'
  _subRefresh(true)
  _subWatchRestore()
}

window.__subClosePaywall = function() {
  const ov = document.getElementById('subPaywallOverlay')
  if (ov) ov.style.display = 'none'
}

function _subPaywallHtml() {
  const st = _subStatus
  const T  = (en, es) => _T(en, es ?? en)
  const addr = _botApiAddr() ?? ''
  const treasury = st?.treasury ?? ''
  const price = st?.priceUsdc ?? 10
  const days  = st?.periodDays ?? 30
  const trial = st?.trialAvailable && (st?.trialDays > 0)
  const short = (a) => a ? a.slice(0, 6) + '…' + a.slice(-4) : '—'
  const canPay = isMainWalletConnected()

  const feature = (text) => `<div class="sub-feat"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" width="13" height="13"><path d="M20 6 9 17l-5-5"/></svg><span>${text}</span></div>`

  return `<div class="sub-wrap">
    <div class="sub-hero">
      <div class="sub-kicker">${T('Automated strategies')}</div>
      <div class="sub-title">${T('Let the bots trade while you sleep')}</div>
      <div class="sub-sub">${T('Grid, DCA, Trend and Profit Stack run on our servers around the clock — they keep working with the app closed.')}</div>
      <div class="sub-price"><span class="sub-price-n">$${price}</span><span class="sub-price-u">/ ${days} ${T('days')}</span></div>
    </div>

    <div class="sub-feats">
      ${feature(T('Unlimited bots, on every account you own'))}
      ${feature(T('Runs server-side — no browser left open'))}
      ${feature(T('Stop any bot at any time. No lock-in.'))}
    </div>

    ${trial ? `
      <button class="sub-cta" onclick="window.__subStartTrial()">${T('Start free trial')} · ${st.trialDays} ${T('days')}</button>
      <div class="sub-fine">${T('One per wallet. No card, nothing to cancel.')}</div>
      <div class="sub-or"><span>${T('or pay now')}</span></div>
    ` : ''}

    <div class="sub-card">
      <div class="sub-card-head">
        <span class="sub-chip">${price} USDC</span>
        <span class="sub-card-on">${T('on')} ${esc(st?.chain ?? 'Hyperliquid')}</span>
      </div>
      ${canPay ? `
        <div class="sub-paynow">${T('Paid straight from your Hyperliquid balance. One signature — no bridge, no gas.')}</div>
        <button id="subPayBtn" class="sub-cta" onclick="window.__subPayNow()">${T('Pay')} $${price} USDC</button>
      ` : `
        <div class="sub-paynow">${T('Connect your wallet to pay in one tap, or send the USDC yourself on Hyperliquid.')}</div>
        <button id="subPayBtn" class="sub-cta" onclick="window.__subPayNow()">${T('Connect wallet to pay')}</button>
      `}
      <div id="subWatchLine" class="sub-watchline">${_subWatchHtml()}</div>

      <details class="sub-details">
        <summary>${T('Rather send it yourself?')}</summary>
        <div class="sub-details-body">
          <div>${T('Send')} <b>${price} USDC</b> ${T('on Hyperliquid to this address. We watch for it and unlock automatically.')}</div>
          <div class="sub-addr"><code>${esc(treasury)}</code><button onclick="window.__subCopyTreasury(this)">${T('Copy')}</button></div>
          <div class="sub-details-row" style="margin-top:9px">
            <a class="sub-btn ghost" style="flex:1" href="https://app.hyperliquid.xyz/portfolio" target="_blank" rel="noopener">${T('Open Hyperliquid')}</a>
            <button class="sub-btn ghost" style="flex:1" onclick="window.__subSent()">${T('I sent it')}</button>
          </div>
        </div>
      </details>
    </div>

    <div class="sub-foot">
      <div class="sub-foot-row"><span>${T('Enabling')}</span><code title="${esc(addr)}">${esc(short(addr))}</code></div>
      <details class="sub-details">
        <summary>${T('Paying from a different wallet?')}</summary>
        <div class="sub-details-body">
          <div>${T('By default the wallet that sends the USDC is the one enabled. Name the wallet that will pay and we will credit this one instead.')}</div>
          <div class="sub-details-row">
            <input id="subPayer" placeholder="0x…" spellcheck="false" autocomplete="off">
            <button onclick="window.__subPayFrom()">${T('Save')}</button>
          </div>
        </div>
      </details>
      <div class="sub-fine">${T('Hyperliquid only. Sending on another chain loses the funds — we cannot recover them.')}</div>
    </div>
    <div style="height:calc(80px + env(safe-area-inset-bottom))"></div>
  </div>`
}

// Full-screen toggle for the Strats tab. The config forms are tall — several inputs plus a
// running-bot list — and on a phone they sat in the short area under the header with the
// price strip and tab bar eating most of the viewport.
// What each bot actually does, in the words of someone deciding whether to run it.
//
// Written from the strategy files' own headers rather than invented, because a description
// that flatters a bot is worse than none: the reader finds out the truth from their
// balance. Each carries the mechanism, then the condition it does BADLY in — that second
// line is the one that saves money, and it is the one marketing copy always leaves out.
