// Flip state is per bot and deliberately NOT persisted: the back of a card is something
// you read once, not a mode to be left in.
const _stratFlipped = new Set()
window.__stratFlip = function(type, on) {
  if (on) _stratFlipped.add(type); else _stratFlipped.delete(type)
  document.getElementById('strat-card-' + type)?.classList.toggle('strat-flipped', !!on)
}

let _stratsFull = false
function _stratsApplyFull() {
  document.getElementById('mobileView')?.classList.toggle('mob-strats-full', _stratsFull)
}
// Drop full screen WITHOUT re-rendering: the caller is already mid-render, and re-entering
// _mobVRenderContent from inside itself would recurse.
function _stratsExitFull() {
  _stratsFull = false
  _stratsApplyFull()
}
window.__stratsToggleFull = function() {
  _stratsFull = !_stratsFull
  _stratsApplyFull()
  _mobVRenderContent()
}

// Why is Strats unlocked? Without saying so, a running trial is indistinguishable from dev
// mode: turning dev mode OFF changed nothing visible, the toggle read off, and the tab
// stayed unlocked — because a 7-day trial was active on that wallet the whole time. State
// the reason so that is never a guessing game again.
function _stratsWhyUnlocked() {
  if (isDev()) return `<span class="strat-ent strat-ent-dev">${_T('Dev mode', 'Modo dev')}</span>`
  const st = _subStatus
  if (!st?.active || !(st.until > Date.now())) return ''
  const days = Math.ceil((st.until - Date.now()) / 86_400_000)
  return `<span class="strat-ent">${_T('Active', 'Activa')} · ${days}${_T('d left', 'd restantes')}</span>`
}

// Full screen hides the app's own chrome, so without this the only way back was the
// bottom nav — which is easy to miss when the view fills the screen.
function _stratsCloseBtn() {
  return `<button onclick="window.__stratsClose()" title="${_T('Close', 'Cerrar')}" aria-label="${_T('Close', 'Cerrar')}"
    style="flex-shrink:0;background:rgba(255,255,255,.06);border:1px solid var(--border2);color:var(--muted);
           border-radius:8px;padding:5px 9px;font-size:12px;cursor:pointer;display:inline-flex;align-items:center;gap:5px">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" width="12" height="12"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>${_T('Back', 'Volver')}
  </button>`
}
window.__stratsClose = function() {
  _stratsExitFull()
  window.mobVHome()
}

function _stratsFullBtn() {
  return `<button onclick="window.__stratsToggleFull()" title="${_stratsFull ? 'Exit full screen' : 'Full screen'}"
    style="flex-shrink:0;background:rgba(255,255,255,.06);border:1px solid var(--border2);color:var(--muted);
           border-radius:8px;padding:5px 9px;font-size:12px;cursor:pointer;display:inline-flex;align-items:center;gap:5px">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" width="12" height="12">${
      _stratsFull ? '<path d="M9 3v6H3M15 21v-6h6"/>' : '<path d="M3 9V3h6M21 15v6h-6"/>'
    }</svg>${_stratsFull ? _T('Exit', 'Salir') : _T('Expand', 'Ampliar')}
  </button>`
}

// Spelled out rather than left to the label, because this switch decides whether the bot
// spends real money and "Dry-run" alone does not say that to a first-time reader.
const _ACCUM_MODE_HINT = {
  live: 'Places real transfers and spot buys.',
  dry:  'Logs what it would buy. No funds move.',
}

// Repaint the Mode control in place. A full re-render would wipe whatever the user has
// half-typed into the fields above it.
function _mobPaintAccumMode() {
  document.querySelectorAll('.mob-seg[data-seg="accum-mode"]').forEach(seg => {
    seg.classList.toggle('mob-seg--live', !_mobAccumDryRun)
    seg.querySelectorAll('.mob-seg-b').forEach((b, i) => b.classList.toggle('on', (i === 0) !== _mobAccumDryRun))
    const hint = seg.parentElement?.querySelector('.mob-strat-hint')
    if (hint) hint.textContent = _mobAccumDryRun ? _ACCUM_MODE_HINT.dry : _ACCUM_MODE_HINT.live
  })
}

window._mobSetAccumDryRun = function(dry) {
  _mobAccumDryRun = !!dry
  _mobPaintAccumMode()
}

// Which account a new bot is armed on, in the combined view. Deliberately the same
// selection the trade tab uses — one "which account am I acting as" for the whole view.
function _stratAcctPickerHtml() {
  const cur = String(_stratTargetAddr() ?? '').toLowerCase()
  const rows = _maLoad().map(w => {
    const on  = w.addr.toLowerCase() === cur
    const key = !!localStorage.getItem(_agentKeyForAddr(w.addr))
    const lbl = w.label || (w.addr.slice(0, 6) + '…' + w.addr.slice(-4))
    // An account with no agent key cannot run anything; say so rather than let it be
    // picked and fail at the server.
    return `<button data-strat-acct="${esc(w.addr)}" ${key ? '' : 'disabled'}
      onclick="window.__pickStratAcct('${esc(w.addr)}')"
      style="padding:6px 11px;border-radius:9px;font-size:12px;font-weight:700;cursor:${key ? 'pointer' : 'not-allowed'};
             white-space:nowrap;opacity:${key ? '1' : '.4'};
             border:1px solid ${on ? 'var(--accent)' : 'var(--border2)'};
             background:${on ? 'color-mix(in oklch,var(--accent) 15%,transparent)' : 'var(--panel-2)'};
             color:${on ? 'var(--accent)' : 'var(--fg)'}">${esc(lbl)}${key ? '' : ' 🔑'}</button>`
  }).join('')
  return `<div class="mob-v-setting-group" style="margin-bottom:14px">
    <div class="mob-v-setting-row" style="flex-direction:column;align-items:stretch;gap:8px">
      <div style="font-size:13px;font-weight:600">${_T('Run bots on', 'Ejecutar bots en')}</div>
      <div id="stratAcctPills" data-dragscroll style="display:flex;gap:6px;min-width:0;overflow-x:auto;scrollbar-width:none;padding-bottom:2px">${rows}</div>
      <div style="font-size:11px;color:var(--muted)">${
        _T('Bots are armed on this account and signed with its agent key. 🔑 means no key saved yet.',
           'Los bots se activan en esta cuenta y se firman con su clave de agente. 🔑 significa que aún no hay clave guardada.')}</div>
    </div>
  </div>`
}

window.__pickStratAcct = function(addr) {
  window.__setTradeAcct(addr)
  // A full re-render would wipe half-typed config; repaint the pills in place, like the
  // trade tab does.
  const cur = String(addr).toLowerCase()
  document.querySelectorAll('#stratAcctPills [data-strat-acct]').forEach(b => {
    const on = b.dataset.stratAcct.toLowerCase() === cur
    b.style.borderColor = on ? 'var(--accent)' : 'var(--border2)'
    b.style.background  = on ? 'color-mix(in oklch,var(--accent) 15%,transparent)' : 'var(--panel-2)'
    b.style.color       = on ? 'var(--accent)' : 'var(--fg)'
  })
}

// ─── DEVICE BOTS: the glue ────────────────────────────────────────────────────
//
// src/devicebot.js owns the sandbox and the limits. This owns everything that touches
// money: building the snapshot a bot is allowed to see, and turning an approved intent
// into a real order through the same trading path the buttons use.
//
// The split is the point. The worker cannot read localStorage, so it never holds the agent
// key; and the functions below are not reachable from inside it. A bot asks; this decides.
const _devBots = new Map()   // id → DeviceBot

// Everything a bot is given. Deliberately narrow: the one market it was installed for,
// its own position and resting orders, account equity, and recent candles. It is not
// handed the wallet address, the key, other markets, or the rest of the portfolio.
function _devBotSnapshot(def, bot) {
  const coin = def.coin
  const mark = _livePx(coin)
  if (!(mark > 0)) return null
  const pos = (state.perpState?.assetPositions ?? []).find(p => p.position.coin === coin)
  const raw = _pulseCandles[coin + '|1h']
  return {
    coin,
    mark,
    tick: Date.now(),
    equity: parseFloat(state.perpState?.marginSummary?.accountValue ?? 0),
    position: pos ? {
      szi: parseFloat(pos.position.szi ?? 0),
      entryPx: parseFloat(pos.position.entryPx ?? 0),
      unrealizedPnl: parseFloat(pos.position.unrealizedPnl ?? 0),
    } : null,
    openOrders: (state.openOrders ?? []).filter(o => o.coin === coin).map(o => ({
      oid: o.oid, isBuy: !!o.isBuy, sz: parseFloat(o.sz ?? 0), limitPx: parseFloat(o.limitPx ?? 0),
    })),
    candles: Array.isArray(raw) ? raw.slice(-200).map(k => ({
      t: +k.t, o: +k.o, h: +k.h, l: +k.l, c: +k.c, v: +k.v,
    })) : [],

    // The whole account, for a bot that manages more than the one market it was filed
    // under. `coin` above stays the bot's home market — it is what the simple intent path
    // and the limits key off — but nothing here is restricted to it any more, because a
    // bot that has to be told about only one market is not a bot, it is a widget.
    //
    // Still absent, and staying absent: the wallet address and the agent key. A bot signs
    // by asking (api.exchange), so it has no use for either.
    // Every market this bot may trade, and the mark for each — so a portfolio bot does not
    // have to parse `mids` (strings, whole exchange) to price the fifteen it cares about.
    coins: botCoins(def),
    marks: Object.fromEntries(botCoins(def).map(c => [c, _livePx(c)]).filter(([, p]) => p > 0)),

    mids: { ...(state.allMids ?? {}) },
    positions: (state.perpState?.assetPositions ?? []).map(x => ({
      coin: x.position.coin,
      szi: parseFloat(x.position.szi ?? 0),
      entryPx: parseFloat(x.position.entryPx ?? 0),
      unrealizedPnl: parseFloat(x.position.unrealizedPnl ?? 0),
      leverage: parseFloat(x.position.leverage?.value ?? 0),
      liquidationPx: parseFloat(x.position.liquidationPx ?? 0),
      marginUsed: parseFloat(x.position.marginUsed ?? 0),
    })),
    orders: (state.openOrders ?? []).map(o => ({
      oid: o.oid, coin: o.coin, isBuy: !!o.isBuy,
      sz: parseFloat(o.sz ?? 0), limitPx: parseFloat(o.limitPx ?? 0),
    })),
    margin: {
      accountValue: parseFloat(state.perpState?.marginSummary?.accountValue ?? 0),
      totalMarginUsed: parseFloat(state.perpState?.marginSummary?.totalMarginUsed ?? 0),
      withdrawable: parseFloat(state.perpState?.withdrawable ?? 0),
    },
    paper: isPaper(),

    // The bot's own card, handed back to it. A bot whose risk lives in `const RIESGO =`
    // needs a re-install to change it; one that reads ctx.config.params needs a form field.
    //
    // The caps are in here as information, not as permission: they are enforced in this
    // thread after the bot has spoken, so a bot that lies to itself about maxUsd still gets
    // refused. Reading them lets a bot size an order it knows will pass instead of watching
    // every one bounce.
    config: {
      coin: def.coin,
      coins: botCoins(def),
      maxUsd: def.maxUsd,
      maxPerMin: def.maxPerMin,
      maxOpen: def.maxOpen,
      everySec: def.everySec,
      leverage: def.leverage,
      dry: !!(bot ? bot.dry : _devBots.get(def.id)?.dry),
      params: parseBotParams(def.params ?? ''),
    },
  }
}

// An approved intent becomes an order. Paper accounts go through the paper engine, so a
// device bot can be tried out with no money at risk and no key at all.
async function _devBotExecute(def, it) {
  // An intent may name any market on the bot's card; naming none means the home market.
  // DeviceBot._check has already refused anything off the list — this repeats the check
  // because execute is the thing that actually sends an order, and a guard that lives only
  // in the caller is one refactor away from not existing.
  const coin = it.coin ?? def.coin
  if (!botCoins(def).includes(coin)) return { ok: false, error: `"${coin}" is not one of this bot's markets` }
  const mark = _livePx(coin)
  if (!(mark > 0)) return { ok: false, error: 'no mark price for ' + coin }
  const acct = isPaper() ? null : _stratTargetAddr()

  if (it.type === 'cancel') {
    if (isPaper()) { paperCancel(Number(it.oid)); _paperRefresh(); return { ok: true } }
    await cancelOrder({ coin, oid: Number(it.oid), acct })
    return { ok: true }
  }
  if (it.type === 'close') {
    const pos = (state.perpState?.assetPositions ?? []).find(p => p.position.coin === coin)
    const szi = parseFloat(pos?.position?.szi ?? 0)
    if (!szi) return { ok: false, error: 'no position to close' }
    if (isPaper()) {
      paperOrder({ orders: [{ b: szi < 0, p: mark, s: Math.abs(szi), r: true, t: { limit: { tif: 'Ioc' } } }] }, coin)
      _paperRefresh(); return { ok: true }
    }
    await closePosition({ coin, isBuy: szi < 0, sz: Math.abs(szi), markPrice: mark, acct })
    return { ok: true }
  }

  const px = it.type === 'limit' ? Number(it.px) : mark
  const sz = Number(it.usd) / px
  if (!(sz > 0)) return { ok: false, error: 'size worked out to zero' }

  if (isPaper()) {
    const r = paperOrder({ orders: [{ b: !!it.isBuy, p: px, s: sz,
      t: { limit: { tif: it.type === 'limit' ? 'Gtc' : 'Ioc' } } }] }, coin)
    _paperRefresh()
    const err = r?.response?.data?.statuses?.[0]?.error
    return err ? { ok: false, error: err } : { ok: true }
  }
  const lev = Number(def.leverage) || 3
  if (it.type === 'limit') await placeLimitOrder({ coin, isBuy: !!it.isBuy, sz, limitPx: px, leverage: lev, isIsolated: false, acct })
  else                     await placeMarketOrder({ coin, isBuy: !!it.isBuy, sz, markPrice: mark, leverage: lev, isIsolated: false, acct })
  return { ok: true }
}

/**
 * Trading actions a device bot may ask the app to sign.
 *
 * Everything here places, changes or cancels an order, or adjusts margin on a position
 * the account already has — the same surface the app's own buttons use.
 *
 * What is NOT here matters more. `approveAgent` would let a bot install a SECOND agent
 * key for the account and then act outside this sandbox entirely; that is the one
 * escalation that would undo the whole design. The fund-moving actions (withdraw3,
 * usdSend, spotSend, usdClassTransfer, vaultTransfer, subAccountTransfer) are absent too.
 * An agent key cannot perform those anyway — the app says so in three places — so this
 * costs a bot nothing and closes the door if that ever changes.
 */
const _DEVBOT_METHODS = new Set([
  'order', 'cancel', 'cancelByCloid', 'modify', 'batchModify',
  'updateLeverage', 'updateIsolatedMargin', 'scheduleCancel',
  'twapOrder', 'twapCancel',
])
// Methods that create orders, and so must count against the bot's rate limit.
const _DEVBOT_PLACING = new Set(['order', 'batchModify', 'modify', 'twapOrder'])

/**
 * The same limits, on the other route to the exchange.
 *
 * A bot has two ways to place an order: return an intent, which DeviceBot._check measures
 * against the card, or call api.order() directly. Only the first was checked. The method
 * allow-list and the rate cap applied to both, but the market, the order size and the
 * resting-order cap did not -- so a bot on a card reading "BTC, ETH, max $40" could place
 * $5,000 of anything through api.order() and the app would sign it.
 *
 * That is not a way to steal a key (the worker never has one) but it is a way to lose an
 * account, and it made two of the three caps on the install screen decorative. This closes
 * it: the raw path now answers to the same card the intent path does.
 *
 * Throws with a reason naming what was refused. Returns nothing when the call is fine.
 */
async function _devBotCheckRaw(def, method, args, bot) {
  const allowed = botCoins(def)
  if (!allowed.length) throw new Error('this bot has no markets on its card')

  // Forward, not reverse: resolve the FEW coins on the card to their asset ids and look
  // the order's id up in that. A reverse map over the whole exchange would need the same
  // three id encodings and would be wrong for HIP-3 the moment one drifted.
  const byId = new Map()
  const unresolved = []
  for (const c of allowed) {
    try { byId.set(await assetIdFor(c), c) } catch { unresolved.push(c) }
  }
  const coinOf = (a) => byId.get(Number(a)) ?? null
  // Refusing is right when the id resolved and did not match. It is NOT the same as being
  // unable to look the market up at all -- a network blip must not be reported as the bot
  // having tried to trade something it was not allowed to, or the log sends you hunting a
  // rule violation that never happened.
  const refuse = (a) => {
    if (unresolved.length) {
      throw new Error(`could not look up ${unresolved.join(', ')} to check asset ${a} against this bot's markets — not sent`)
    }
    throw new Error(`asset ${a} is not one of this bot's markets (${allowed.join(', ')})`)
  }

  // Every shape of argument these methods take, and which part of it names a market.
  // `orders` covers order and batchModify; the rest each carry a single asset.
  const orders =
    method === 'order' ? (args?.orders ?? [])
    // batchModify is { modifies: [{ oid, order }] } -- NOT { orders }. Reading it as the
    // latter checks nothing and passes everything, which is worse than not checking at all
    // because it looks checked.
    : method === 'batchModify' ? (args?.modifies ?? []).map(m => m?.order).filter(Boolean)
    : method === 'modify' ? [args?.order].filter(Boolean)
    : method === 'twapOrder' ? [args?.twap].filter(Boolean)
    : []

  for (const o of orders) {
    const coin = coinOf(o?.a)
    if (!coin) refuse(o?.a)
    // Notional from the order's own price, falling back to the mark for a market order
    // that carries none. A size the app cannot price is not waved through -- it is exactly
    // the case where a cap would matter most.
    const px = Number(o?.p) > 0 ? Number(o.p) : _livePx(coin)
    const sz = Math.abs(Number(o?.s) || 0)
    if (def.maxUsd > 0) {
      if (!(px > 0)) throw new Error(`cannot price ${coin} to check it against the $${def.maxUsd} per-order limit`)
      const usd = sz * px
      if (usd > def.maxUsd) {
        throw new Error(`order $${usd.toFixed(2)} of ${coin} is over the $${def.maxUsd} per-order limit you set`)
      }
    }
  }

  // A resting order is one that can sit on the book. An IOC/market order cannot, so it is
  // not counted against a cap on how many may rest.
  const cap = def.maxOpen ?? 0
  if (cap > 0 && (method === 'order' || method === 'batchModify')) {   // both place resting orders
    const resting = orders.filter(o => o?.t?.limit && o.t.limit.tif !== 'Ioc').length
    if (resting > 0) {
      const mine = new Set(allowed)
      const already = (state.openOrders ?? []).filter(o => mine.has(o.coin)).length
      if (already + resting > cap) {
        throw new Error(`already ${already} resting orders, limit ${cap}`)
      }
    }
  }

  // The methods that name one asset without placing anything. Checked for the market only:
  // setting leverage or margin on a market the user never listed is still reaching into a
  // market the user never listed.
  const single =
    method === 'updateLeverage' || method === 'updateIsolatedMargin' ? args?.asset
    : method === 'twapCancel' ? args?.a
    : undefined
  if (single !== undefined && !coinOf(single)) refuse(single)

  for (const c of (args?.cancels ?? [])) {
    const a = c?.a ?? c?.asset
    if (a !== undefined && !coinOf(a)) refuse(a)
  }
}

async function _devBotRequest(def, kind, payload, bot) {
  if (kind === 'info') {
    // Public market data. No key, no account, nothing to gate — the same endpoint any
    // browser tab can call.
    const r = await fetch('https://api.hyperliquid.xyz/info', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload ?? {}),
    })
    if (!r.ok) throw new Error('info request failed: ' + r.status)
    return r.json()
  }

  if (kind === 'exchange') {
    const method = String(payload?.method ?? '')
    const args = payload?.args ?? {}
    if (!_DEVBOT_METHODS.has(method)) throw new Error(`"${method}" is not available to bots`)
    if (_DEVBOT_PLACING.has(method) && bot?.rateBlocked()) {
      throw new Error(`rate limit: ${def.maxPerMin} orders/min reached`)
    }
    // Before the dry-run branch, so a preview also reports what your limits would have
    // refused -- the same order _execute uses for intents, and for the same reason.
    await _devBotCheckRaw(def, method, args, bot)
    // A dry run must close BOTH routes. Stopping only the intent path would let a bot that
    // trades via api.order() place real orders during a preview — the one outcome a
    // preview must never have.
    if (bot?.dry) {
      bot.say('info', 'Would call api.' + method + ' ' + JSON.stringify(args ?? {}).slice(0, 160))
      return { status: 'ok', dryRun: true }
    }
    if (isPaper()) {
      // The paper engine models orders and cancels, not the whole exchange API.
      if (method === 'order')  { const r = paperOrder(args, args?.orders?.[0]?.__coin ?? def.coin); _paperRefresh(); return r }
      if (method === 'cancel') { paperCancelMany(args?.cancels ?? []); _paperRefresh(); return { status: 'ok' } }
      throw new Error(`"${method}" is not simulated on the paper account`)
    }
    const acct = _stratTargetAddr()
    if (!acct) throw new Error('no account selected')
    const res = await exchangeAction(acct, method, args)
    if (_DEVBOT_PLACING.has(method)) bot?.noteSend()
    return res
  }
  throw new Error('unknown request: ' + kind)
}

const _devBotDeps = {
  snapshot: _devBotSnapshot,
  execute:  _devBotExecute,
  request:  _devBotRequest,
  onChange: () => { if (_mobVActiveTab === 'strategies') _mobVRenderStrategies(document.getElementById('mobVContent')) },
}

// NOT behind the subscription gate, deliberately.
//
// The paywall exists because the built-in bots run on our servers around the clock, with
// the app closed — that is the thing being paid for. A device bot runs in the user's own
// browser, on their own machine, and costs us nothing to have running. Charging for it
// would be charging for the privilege of using their own computer.
//
// So __devBotStart never consults _stratsUnlocked() or _canStartBot(), and the section is
// rendered outside the `locked` branch. This comment exists because that was previously
// true only by omission, which is the kind of thing a later edit silently undoes.
window.__devBotStart = function(id, dry = false) {
  const def = devBotsLoad().find(b => b.id === id)
  if (!def) return
  if (!isPaper() && !_stratTargetAddr()) { _paperToast(_T('Open an account first', 'Abre una cuenta primero'), 'err'); return }
  _pulseLoadCandles(def.coin)              // the snapshot's candles come from Pulse's cache
  let bot = _devBots.get(id)
  if (!bot) { bot = new DeviceBot(def, _devBotDeps); _devBots.set(id, bot) }
  bot.def = def
  bot.start(dry)
  _mobVRenderStrategies(document.getElementById('mobVContent'))
}
/**
 * Preview: ask the bot what it would do, and SHOW the answer.
 *
 * Same shape as the built-in bots' preview — press it, read a sheet, then either run it or
 * back out. It runs one real tick against live data with every route to the exchange shut,
 * so what you read is what your file actually decided, not a description of it.
 */
window.__devBotPreview = async function(id) {
  const def = devBotsLoad().find(b => b.id === id)
  if (!def) return
  if (!isPaper() && !_stratTargetAddr()) { _paperToast(_T('Open an account first', 'Abre una cuenta primero'), 'err'); return }
  _pulseLoadCandles(def.coin)
  _devBotPreviewSheet(def, null)

  // A throwaway instance: previewing must never disturb a copy of this bot that is
  // already running, and must not leave one behind either.
  const probe = new DeviceBot(def, { ..._devBotDeps, onChange: () => {} })
  let res
  try { res = await probe.previewOnce() }
  catch (e) { res = { intents: [], log: [{ ts: Date.now(), level: 'error', msg: e?.message ?? String(e) }], timedOut: false } }
  _devBotPreviewSheet(def, res)
}

function _devBotPreviewSheet(def, res) {
  const money = v => '$' + Number(v).toFixed(2)
  const describe = (it) => {
    const t = String(it?.type ?? '?')
    if (t === 'close')  return _T('Close the whole position', 'Cerrar toda la posición')
    if (t === 'cancel') return _T('Cancel order', 'Cancelar orden') + ' #' + esc(String(it.oid ?? '?'))
    const side = it.isBuy ? _T('Buy', 'Comprar') : _T('Sell', 'Vender')
    if (t === 'limit')  return `${side} ${money(it.usd)} ${_T('as a limit at', 'como límite a')} $${fmtPrice(it.px)}`
    return `${side} ${money(it.usd)} ${_T('at market', 'a mercado')}`
  }

  let body
  if (!res) {
    body = `<div style="padding:34px 16px;text-align:center;font-size:12.5px;color:var(--muted)">${
      _T('Running one tick of your bot…', 'Ejecutando un tick de tu bot…')}</div>`
  } else {
    const lines = res.log.filter(l => !/^Loading |^DRY RUN|^Stopped$/.test(l.msg))
    const col = l => l === 'error' ? 'var(--red)' : l === 'warn' ? 'var(--orange,#f59e0b)' : 'var(--fg-2)'
    const failed = res.log.some(l => l.level === 'error')
    // _devBotSheet already pads its body, so this adds none of its own.
    body = `<div>
      <div style="font-size:11.5px;color:var(--fg-3);line-height:1.5;margin-bottom:12px">${
        _T('One tick, on live prices, with nothing sent. This is what your file decided.',
           'Un tick, con precios reales y sin enviar nada. Esto es lo que decidió tu archivo.')}</div>

      <div style="font-size:10px;font-weight:800;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px">${
        _T('It would place', 'Colocaría')}</div>
      ${res.intents.length
        ? res.intents.map(it => `<div style="display:flex;align-items:center;gap:9px;border:1px solid var(--border2);border-radius:10px;background:var(--panel-2);padding:10px 12px;margin-bottom:6px">
            <span style="width:7px;height:7px;border-radius:50%;background:${it.type === 'close' || it.type === 'cancel' ? 'var(--orange,#f59e0b)' : it.isBuy ? 'var(--green)' : 'var(--red)'};flex-shrink:0"></span>
            <span style="font-size:13px;font-weight:700">${esc(describe(it))}</span>
            <span style="flex:1"></span>
            <span style="font-size:10.5px;color:var(--muted)">${esc(_ocCoinLabel(def.coin))}</span>
          </div>`).join('')
        : `<div style="border:1px dashed var(--border2);border-radius:10px;padding:13px;font-size:12.5px;color:var(--fg-3);line-height:1.5">${
            res.timedOut
              ? _T('It did not finish a tick in time. If it awaits something slow, that is expected — press Run and watch the Log instead.',
                   'No terminó un tick a tiempo. Si espera algo lento, es normal — pulsa Ejecutar y mira el Registro.')
              : _T('Nothing, right now. Its conditions were not met on this tick — which is a normal answer, not a failure.',
                   'Nada, ahora mismo. No se cumplieron sus condiciones en este tick — es una respuesta normal, no un fallo.')}</div>`}

      ${lines.length ? `<div style="font-size:10px;font-weight:800;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:16px 0 6px">${
        _T('What it said', 'Lo que dijo')}</div>
        <div style="display:flex;flex-direction:column;gap:4px;font-family:var(--font-mono);font-size:11px;line-height:1.5">${
          lines.slice().reverse().map(l => `<div style="color:${col(l.level)};word-break:break-word">${esc(l.msg)}</div>`).join('')}</div>` : ''}

      <div style="font-size:10.5px;color:var(--fg-3);margin-top:14px;line-height:1.5;border-top:1px solid var(--border);padding-top:10px">${
        failed
          ? _T('Something errored above. Fix it with Edit before running this for real.',
               'Algo falló arriba. Corrígelo con Editar antes de ejecutarlo de verdad.')
          : _T('Nothing was placed and nothing is running — this bot is still stopped.',
               'No se colocó nada y nada está activo — este bot sigue detenido.')}</div>
    </div>`
  }

  _devBotSheet(_T('Preview', 'Vista previa') + ' · ' + esc(def.name), body + (res ? `
    <div style="display:flex;gap:8px;padding:14px 0 0">
      <button onclick="document.getElementById('devBotSheet')?.remove();window.__devBotStart('${def.id}')" style="flex:1;padding:12px;border-radius:10px;border:none;background:var(--accent);color:#000;font-size:14px;font-weight:700;cursor:pointer">▶ ${_T('Run it', 'Ejecutar')}</button>
      <button onclick="document.getElementById('devBotSheet')?.remove()" style="flex:1;padding:12px;border-radius:10px;border:1px solid var(--border2);background:transparent;color:var(--fg-2);font-size:14px;font-weight:700;cursor:pointer">${_T('Back', 'Volver')}</button>
    </div>` : ''))
}
window.__devBotStop = function(id) {
  _devBots.get(id)?.stop()
  _mobVRenderStrategies(document.getElementById('mobVContent'))
}
window.__devBotDelete = async function(id) {
  if (!(await _appConfirm({ title: _T('Delete this bot?', '¿Borrar este bot?'),
    body: _T('Its file and its log are removed from this device. Anything it has already placed stays open.',
             'Su archivo y su registro se borran de este dispositivo. Lo que ya haya colocado sigue abierto.'),
    confirmText: _T('Delete', 'Borrar'), danger: true }))) return
  _devBots.get(id)?.stop()
  _devBots.delete(id)
  devBotsSave(devBotsLoad().filter(b => b.id !== id))
  _mobVRenderStrategies(document.getElementById('mobVContent'))
}
window.__devBotLogs = function(id) {
  const bot = _devBots.get(id)
  const def = devBotsLoad().find(b => b.id === id)
  const lines = bot?.log ?? []
  const col = l => l === 'error' ? 'var(--red)' : l === 'warn' ? 'var(--orange,#f59e0b)' : 'var(--fg-2)'
  _devBotSheet(_T('Log', 'Registro') + ' · ' + esc(def?.name ?? ''), lines.length
    ? `<div style="display:flex;flex-direction:column;gap:5px;font-family:var(--font-mono);font-size:11.5px">${
        lines.map(l => `<div style="display:flex;gap:8px"><span style="color:var(--fg-3);flex-shrink:0">${
          new Date(l.ts).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', second: '2-digit' })}</span><span style="color:${col(l.level)};word-break:break-word">${esc(l.msg)}</span></div>`).join('')}</div>`
    : `<div class="mob-v-empty">${_T('Nothing logged yet.', 'Nada registrado aún.')}</div>`)
}

// One bottom sheet, used by anything that needs one. `pad` is off for a body that brings
// its own padding -- a list that must run edge to edge, for instance.
function _sheet(id, title, body, pad = true) {
  document.getElementById(id)?.remove()
  const wrap = document.createElement('div')
  wrap.id = id
  const close = `document.getElementById('${id}')?.remove()`
  wrap.innerHTML = `
    <div onclick="${close}" style="position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:8999"></div>
    <div style="position:fixed;bottom:0;left:0;right:0;z-index:9000;background:var(--panel-2);border-radius:20px 20px 0 0;border-top:1px solid var(--border2);max-height:86vh;overflow:auto;-webkit-overflow-scrolling:touch;padding-bottom:env(safe-area-inset-bottom)">
      <div style="position:sticky;top:0;background:var(--panel-2);display:flex;align-items:center;justify-content:space-between;padding:15px 16px 11px;border-bottom:1px solid var(--border2)">
        <span style="font-size:15.5px;font-weight:800">${title}</span>
        <button onclick="${close}" aria-label="Close" style="background:none;border:none;color:var(--muted);font-size:22px;line-height:1;cursor:pointer">&times;</button>
      </div>
      <div style="${pad ? 'padding:14px 16px 22px' : ''}">${body}</div>
    </div>`
  document.body.appendChild(wrap)
}

// Kept as its own name because every device-bot caller passes this id, and the id is what
// their inline onclick handlers close.
function _devBotSheet(title, body) { _sheet('devBotSheet', title, body) }

// ── installing one ──────────────────────────────────────────────────────────
let _devBotDraft = null

window.__devBotNew = function() {
  _devBotDraft = { code: DEVBOT_TEMPLATE, name: '' }
  _devBotInstallSheet()
}

// Editing reopens the same sheet with the bot's own values, so there is one form to learn
// rather than two that can drift apart.
window.__devBotEdit = function(id) {
  const def = devBotsLoad().find(b => b.id === id)
  if (!def) return
  _devBotDraft = { ...def }
  _devBotInstallSheet(def)
}

/**
 * Save an edit, and put the bot back the way it was running.
 *
 * A bot that was running when you opened Edit is restarted with the new file, because the
 * worker holds the OLD code — leaving it running would show updated settings next to
 * behaviour from the previous version, which is worse than a brief stop. One that was
 * stopped stays stopped; pressing Update should not start something.
 */
window.__devBotUpdate = function(id) {
  const def = _devBotRead(id)
  if (!def) return
  const was = _devBots.get(id)
  const wasRunning = !!(was && was.worker && !was.stopped)
  was?.stop()
  devBotsSave(devBotsLoad().map(b => b.id === id ? { ...def, id } : b))
  document.getElementById('devBotSheet')?.remove()
  _devBotDraft = null
  if (wasRunning) window.__devBotStart(id)
  else _mobVRenderStrategies(document.getElementById('mobVContent'))
  _paperToast(wasRunning
    ? _T('Updated and restarted', 'Actualizado y reiniciado')
    : _T('Updated', 'Actualizado'), 'success')
}
window.__devBotPickFile = function(input) {
  const f = input.files?.[0]
  if (!f) return
  if (f.size > 200_000) { _paperToast(_T('That file is over 200 KB', 'Ese archivo supera 200 KB'), 'err'); return }
  const r = new FileReader()
  r.onload = () => {
    _devBotDraft = { code: String(r.result ?? ''), name: f.name.replace(/\.[jt]s$/, '') }
    _devBotInstallSheet()
  }
  r.readAsText(f)
}

/**
 * Read and validate the sheet. Shared by Add and Update so the two cannot drift — an edit
 * that skipped a check the install did would be a hole that only opens later.
 * Returns null (having said why) if the form is not usable.
 */
/** The markets on a draft, falling back to its single coin for a bot saved before lists. */
function _devBotCoinsOf(d) {
  const list = botCoins(d)
  return list.length ? list : [d?.coin ?? 'BTC']
}

function _devBotChipsHtml(list) {
  // The home market is first and cannot be removed while it is the only one — a bot with
  // no markets could not place an order and would only look broken.
  return list.map((c, i) => `
    <span style="display:inline-flex;align-items:center;gap:5px;padding:4px 8px;border-radius:8px;font-size:11.5px;font-weight:700;
      border:1px solid ${i === 0 ? 'var(--accent)' : 'var(--border2)'};color:${i === 0 ? 'var(--accent)' : 'var(--fg-2)'}">
      ${i === 0 ? '<span style="opacity:.7;font-size:9.5px;letter-spacing:.05em">HOME</span>' : ''}
      <span class="notranslate">${esc(_ocCoinLabel(c))}</span>
      ${list.length > 1 ? `<button onclick="window.__devBotRemoveCoin('${esc(c)}')" title="${_T('Remove', 'Quitar')}"
        style="border:none;background:transparent;color:inherit;font-size:14px;line-height:1;cursor:pointer;padding:0 1px;opacity:.65">&times;</button>` : ''}
    </span>`).join('')
}

function _devBotCoinsGet() {
  try { const v = JSON.parse(document.getElementById('devBotCoins')?.value ?? '[]'); return Array.isArray(v) ? v : [] }
  catch { return [] }
}

function _devBotCoinsSet(list) {
  const el = document.getElementById('devBotCoins')
  const chips = document.getElementById('devBotCoinChips')
  if (el) el.value = JSON.stringify(list)
  // Only the chip row is repainted. Re-rendering the sheet would throw away the file the
  // user has pasted into the code box, which is the last thing they want on a mis-tap.
  if (chips) chips.innerHTML = _devBotChipsHtml(list)
}

window.__devBotAddCoin = function(sel) {
  const c = sel?.value
  if (!c) return
  const list = _devBotCoinsGet()
  if (list.includes(c)) return _paperToast(_T('Already on the list', 'Ya está en la lista'), 'err')
  _devBotCoinsSet([...list, c])
}

window.__devBotRemoveCoin = function(c) {
  const list = _devBotCoinsGet().filter(x => x !== c)
  if (!list.length) return
  _devBotCoinsSet(list)
}

function _devBotRead(existingId) {
  const g = id => document.getElementById(id)?.value?.trim() ?? ''
  const code = g('devBotCode')
  if (!code) { _paperToast(_T('The file is empty', 'El archivo está vacío'), 'err'); return null }
  if (!/onTick/.test(code)) { _paperToast(_T('No onTick(ctx) found in this file', 'No se encontró onTick(ctx)'), 'err'); return null }
  if (!document.getElementById('devBotAck')?.checked) {
    _paperToast(_T('Please confirm you understand what this runs', 'Confirma que entiendes qué se ejecuta'), 'err'); return null
  }
  // 0 on a cap means "no limit" — a deliberate choice, so these floor at 0 rather than 1.
  //
  // An EMPTY field is not that. Number('') is 0, so a naive read turns a field the user
  // cleared (or never filled) into an unlimited one — the most dangerous possible default,
  // arrived at by accident. Empty falls back to the default; only a typed 0 removes a cap.
  const cap = (v, dflt, max) => {
    const s = String(v ?? '').trim()
    if (s === '') return dflt
    const n = Number(s)
    if (!Number.isFinite(n)) return dflt
    return Math.max(0, Math.min(max, n))
  }
  // The list is the truth; `coin` is its first entry. An empty list would be a bot allowed
  // to trade nothing, which is a confusing way to say "the market in the picker", so the
  // picker fills in.
  let coinList = []
  try { coinList = JSON.parse(document.getElementById('devBotCoins')?.value ?? '[]') } catch {}
  if (!Array.isArray(coinList)) coinList = []
  coinList = [...new Set(coinList.filter(c => typeof c === 'string' && c))]
  if (!coinList.length) coinList = [g('devBotCoin') || 'BTC']

  return {
    id: existingId ?? ('d' + Date.now().toString(36)),
    name: g('devBotName') || 'My bot',
    coin: coinList[0],
    coins: coinList,
    maxUsd: cap(g('devBotMaxUsd'), 25, 1e9),
    maxPerMin: cap(g('devBotMaxMin'), 4, 600),
    maxOpen: cap(g('devBotMaxOpen'), 10, 1000),
    everySec: Math.max(5, Number(g('devBotEvery')) || 15),
    leverage: Math.max(1, Number(g('devBotLev')) || 3),
    // Stored as the TEXT the user typed, not as the parsed object: comments, order and
    // blank lines are how a settings block stays readable, and re-serialising from a
    // parsed map would quietly throw all three away on the next edit.
    params: document.getElementById('devBotParams')?.value ?? '',
    code,
  }
}

/**
 * Offer a device bot for inclusion in the app.
 *
 * It sends the file's text and its settings. Nothing about this makes the bot run anywhere
 * but in the browser it already runs in -- a submission is a message, and shipping one is
 * a person reading it and committing it.
 */
window.__devBotSubmit = function(id) {
  const def = devBotsLoad().find(b => b.id === id)
  if (!def) return
  _sheet('devSubmitSheet', _T('Submit this bot', 'Enviar este bot'), `
    <div style="font-size:12px;color:var(--fg-2);line-height:1.5;margin-bottom:12px">${
      _T('This sends the file and its settings so it can be considered for the app. It keeps running on your device either way, and sending it does not run it anywhere else.',
         'Esto envía el archivo y su configuración para que se considere incluirlo. Sigue ejecutándose en tu dispositivo igualmente.')}</div>
    <label style="display:block;font-size:11px;font-weight:700;color:var(--fg-2)">${_T('Your name or handle', 'Tu nombre')}
      <input id="devSubAuthor" type="text" maxlength="64" placeholder="${_T('optional', 'opcional')}"
        style="width:100%;margin-top:4px;padding:8px 9px;border-radius:8px;border:1px solid var(--border2);background:var(--panel-2);color:var(--fg);font-size:13px"></label>
    <label style="display:block;font-size:11px;font-weight:700;color:var(--fg-2);margin-top:10px">${_T('What does it do?', '¿Qué hace?')}
      <textarea id="devSubNote" rows="3" maxlength="1000" placeholder="${_T('A sentence or two helps.', 'Una o dos frases ayudan.')}"
        style="width:100%;margin-top:4px;padding:8px 9px;border-radius:8px;border:1px solid var(--border2);background:var(--panel-2);color:var(--fg);font-size:13px;font-family:inherit;resize:vertical"></textarea></label>
    <div style="display:flex;gap:8px;margin-top:14px">
      <button onclick="window.__devBotSubmitSend('${esc(id)}')"
        style="flex:1;padding:11px;border-radius:10px;border:none;background:var(--accent);color:#000;font-size:14px;font-weight:800;cursor:pointer">${_T('Send', 'Enviar')}</button>
      <button onclick="document.getElementById('devSubmitSheet')?.remove()"
        style="padding:11px 14px;border-radius:10px;border:1px solid var(--border2);background:transparent;color:var(--fg-2);font-size:13px;font-weight:700;cursor:pointer">${_T('Cancel', 'Cancelar')}</button>
    </div>`)
}

window.__devBotSubmitSend = async function(id) {
  const def = devBotsLoad().find(b => b.id === id)
  if (!def) return
  const author = document.getElementById('devSubAuthor')?.value ?? ''
  const note = document.getElementById('devSubNote')?.value ?? ''
  document.getElementById('devSubmitSheet')?.remove()
  try {
    const r = await fetch('/api/bot-submit', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: def.name, code: def.code, author, note,
        // The settings it was running with, which say as much about the bot as the code.
        config: { coin: def.coin, maxUsd: def.maxUsd, maxPerMin: def.maxPerMin,
                  maxOpen: def.maxOpen, everySec: def.everySec, leverage: def.leverage },
      }),
    })
    const j = await r.json().catch(() => ({}))
    if (r.ok && j.ok) _paperToast(_T('Sent — thank you', 'Enviado — gracias'), 'success')
    else _paperToast(j.error || _T('Could not send', 'No se pudo enviar'), 'err')
  } catch {
    _paperToast(_T('Could not send', 'No se pudo enviar'), 'err')
  }
}

// ── the review queue, dev mode only ───────────────────────────────────────────
let _subsCache = null

window.__openBotSubmissions = async function() {
  _sheet('botSubsSheet', _T('Bot submissions', 'Bots enviados'),
    `<div style="padding:18px 4px;font-size:12px;color:var(--muted)">${_T('Loading…', 'Cargando…')}</div>`)
  try {
    const pin = _lbGetPin()
    const r = await fetch('/api/bot-submissions', { headers: pin ? { 'x-lb-pin': pin } : {} })
    if (r.status === 403) { _subsCache = null; return _botSubsRender('forbidden') }
    _subsCache = await r.json()
    _botSubsRender()
  } catch {
    _subsCache = null
    _botSubsRender('error')
  }
}

window.__botSubStatus = async function(id, status) {
  try {
    const pin = _lbGetPin()
    await fetch('/api/bot-submission-status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(pin ? { 'x-lb-pin': pin } : {}) },
      body: JSON.stringify({ id, status }),
    })
    const row = (_subsCache ?? []).find(x => x.id === id)
    if (row) row.status = status
    _botSubsRender()
  } catch {}
}

/** Show one submission's code. Escaped and read-only -- it is a stranger's file. */
window.__botSubCode = function(id) {
  const row = (_subsCache ?? []).find(x => x.id === id)
  if (!row) return
  _sheet('botSubCodeSheet', esc(row.name), `
    <div style="font-size:10.5px;color:var(--muted);margin-bottom:8px">${
      _T('Read it before running it anywhere. It is somebody else\'s code.',
         'Léelo antes de ejecutarlo en cualquier sitio. Es código de otra persona.')}</div>
    <pre style="max-height:52vh;overflow:auto;background:var(--panel-2);border:1px solid var(--border2);border-radius:8px;padding:10px;font-size:11px;line-height:1.5;white-space:pre;-webkit-overflow-scrolling:touch">${esc(row.code)}</pre>
    <button onclick="window.__botSubCopy()"
      style="width:100%;margin-top:10px;padding:10px;border-radius:9px;border:1px solid var(--border2);background:transparent;color:var(--fg-2);font-size:13px;font-weight:700;cursor:pointer">${_T('Copy', 'Copiar')}</button>`)
}

/** Copies from the rendered element, so the code never has to survive a trip through an
 *  inline attribute -- which is where quoting bugs and injection both live. */
window.__botSubCopy = function() {
  const pre = document.querySelector('#botSubCodeSheet pre')
  if (!pre) return
  try {
    navigator.clipboard?.writeText(pre.textContent ?? '')
    _paperToast(_T('Copied', 'Copiado'), 'success')
  } catch { _paperToast(_T('Could not copy', 'No se pudo copiar'), 'err') }
}

/** Rebuilds the whole sheet. Simpler than reaching into it, and there is nothing in it
 *  worth preserving between renders. */
function _botSubsRender(state) {
  const title = _T('Bot submissions', 'Bots enviados')
  if (state === 'forbidden') {
    return _sheet('botSubsSheet', title, `<div style="font-size:12px;color:var(--red)">${
      _T('The server did not accept the dev PIN.', 'El servidor no aceptó el PIN.')}</div>`)
  }
  if (state === 'error' || !Array.isArray(_subsCache)) {
    return _sheet('botSubsSheet', title, `<div style="font-size:12px;color:var(--red)">${
      _T('Could not load submissions.', 'No se pudieron cargar.')}</div>`)
  }
  if (!_subsCache.length) {
    return _sheet('botSubsSheet', title, `<div style="font-size:12px;color:var(--muted)">${
      _T('Nothing submitted yet.', 'Nada enviado todavía.')}</div>`)
  }
  const tone = { new: 'var(--accent)', kept: 'var(--green)', declined: 'var(--muted)' }
  _sheet('botSubsSheet', title, _subsCache.map(s => `
    <div style="border:1px solid ${tone[s.status] ?? 'var(--border2)'};border-radius:11px;padding:10px 11px;margin-bottom:9px">
      <div style="display:flex;align-items:baseline;gap:8px">
        <span style="font-size:13px;font-weight:800;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(s.name)}</span>
        <span style="flex:1"></span>
        <span style="font-size:9.5px;color:${tone[s.status] ?? 'var(--muted)'};text-transform:uppercase;letter-spacing:.06em;font-weight:800">${esc(s.status)}</span>
      </div>
      <div style="font-size:10.5px;color:var(--muted);margin-top:2px">${
        esc(s.author || _T('anonymous', 'anónimo'))} · ${esc(String(s.receivedAt ?? '').slice(0, 10))} · ${
        esc(String(s.config?.coin ?? '?'))} · ${(s.code ?? '').length} ${_T('chars', 'car.')}</div>
      ${s.note ? `<div style="font-size:11.5px;color:var(--fg-2);margin-top:6px;line-height:1.45">${esc(s.note)}</div>` : ''}
      <div style="display:flex;gap:6px;margin-top:9px;flex-wrap:wrap">
        <button onclick="window.__botSubCode('${esc(s.id)}')" style="padding:5px 10px;border-radius:7px;border:1px solid var(--border2);background:transparent;color:var(--fg-2);font-size:11px;font-weight:700;cursor:pointer">${_T('Read code', 'Ver código')}</button>
        <button onclick="window.__botSubStatus('${esc(s.id)}','kept')" style="padding:5px 10px;border-radius:7px;border:1px solid var(--green);background:transparent;color:var(--green);font-size:11px;font-weight:700;cursor:pointer">${_T('Keep', 'Guardar')}</button>
        <button onclick="window.__botSubStatus('${esc(s.id)}','declined')" style="padding:5px 10px;border-radius:7px;border:1px solid var(--border2);background:transparent;color:var(--muted);font-size:11px;font-weight:700;cursor:pointer">${_T('Decline', 'Descartar')}</button>
      </div>
    </div>`).join('') + `
    <div style="font-size:10.5px;color:var(--muted);line-height:1.5;margin-top:4px;border-top:1px solid var(--border);padding-top:9px">${
      _T('Keeping one marks it for you to ship through the normal path. Nothing here installs or runs a submitted file.',
         'Guardar solo lo marca para revisarlo. Nada aquí instala ni ejecuta un archivo enviado.')}</div>`)
}

// ── the bug inbox, dev mode only ──────────────────────────────────────────────
// Reports were write-only until now: they landed in bug-reports.json on the server and
// reading one meant SSHing in, so nobody did.
let _bugsCache = null

window.__openBugReports = async function() {
  _sheet('bugRepSheet', _T('Bug reports', 'Reportes de fallos'),
    `<div style="padding:18px 4px;font-size:12px;color:var(--muted)">${_T('Loading…', 'Cargando…')}</div>`)
  try {
    const pin = _lbGetPin()
    const r = await fetch('/api/bug-reports', { headers: pin ? { 'x-lb-pin': pin } : {} })
    if (r.status === 403) { _bugsCache = null; return _bugsRender('forbidden') }
    _bugsCache = await r.json()
    _bugsRender()
  } catch {
    _bugsCache = null
    _bugsRender('error')
  }
}

window.__bugStatus = async function(id, status) {
  try {
    const pin = _lbGetPin()
    await fetch('/api/bug-report-status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(pin ? { 'x-lb-pin': pin } : {}) },
      body: JSON.stringify({ id, status }),
    })
    const row = (_bugsCache ?? []).find(x => x.id === id)
    if (row) row.status = status
    _bugsRender()
  } catch {}
}

function _bugsRender(state) {
  const title = _T('Bug reports', 'Reportes de fallos')
  if (state === 'forbidden') {
    return _sheet('bugRepSheet', title, `<div style="font-size:12px;color:var(--red)">${
      _T('The server did not accept the dev PIN.', 'El servidor no aceptó el PIN.')}</div>`)
  }
  if (state === 'error' || !Array.isArray(_bugsCache)) {
    return _sheet('bugRepSheet', title, `<div style="font-size:12px;color:var(--red)">${
      _T('Could not load reports.', 'No se pudieron cargar.')}</div>`)
  }
  if (!_bugsCache.length) {
    return _sheet('bugRepSheet', title, `<div style="font-size:12px;color:var(--muted)">${
      _T('No reports yet.', 'Ningún reporte todavía.')}</div>`)
  }
  const open = _bugsCache.filter(b => b.status !== 'done').length
  // Every field here is a stranger's text typed into a form. One report in the live inbox
  // is an <img onerror> that posts document.cookie to someone's domain — it is inert only
  // because it goes through esc() and lands in text, never in markup.
  const row = (b) => {
    const done = b.status === 'done'
    const d = b.diag ?? {}
    const bits = [d.tab, d.lang, d.screen, d.url].filter(Boolean).map(x => esc(String(x).slice(0, 60)))
    return `
    <div style="border:1px solid ${done ? 'var(--border2)' : 'var(--accent)'};border-radius:11px;padding:10px 11px;margin-bottom:9px;opacity:${done ? '.55' : '1'}">
      <div style="display:flex;align-items:baseline;gap:8px">
        <span style="font-size:10.5px;color:var(--muted)">${esc(String(b.receivedAt ?? '').replace('T', ' ').slice(0, 16))}</span>
        <span style="flex:1"></span>
        <span style="font-size:9.5px;color:${done ? 'var(--muted)' : 'var(--accent)'};text-transform:uppercase;letter-spacing:.06em;font-weight:800">${done ? _T('done', 'hecho') : _T('new', 'nuevo')}</span>
      </div>
      <div style="font-size:12.5px;color:var(--fg);margin-top:6px;line-height:1.5;white-space:pre-wrap;word-break:break-word">${esc(b.message ?? '')}</div>
      ${bits.length ? `<div style="font-size:10px;color:var(--muted);margin-top:6px;word-break:break-all">${bits.join(' · ')}</div>` : ''}
      ${d.ua ? `<div style="font-size:9.5px;color:var(--muted);margin-top:3px;word-break:break-all;opacity:.75">${esc(String(d.ua).slice(0, 140))}</div>` : ''}
      <div style="display:flex;gap:6px;margin-top:9px">
        <button onclick="window.__bugStatus('${esc(b.id)}','${done ? 'new' : 'done'}')"
          style="padding:5px 10px;border-radius:7px;border:1px solid var(--border2);background:transparent;color:var(--fg-2);font-size:11px;font-weight:700;cursor:pointer">${
          done ? _T('Reopen', 'Reabrir') : _T('Mark done', 'Marcar hecho')}</button>
      </div>
    </div>`
  }
  _sheet('bugRepSheet', title,
    `<div style="font-size:11px;color:var(--muted);margin-bottom:9px">${
      open} ${_T('open', 'abiertos')} · ${_bugsCache.length} ${_T('total', 'en total')}</div>` +
    _bugsCache.map(row).join(''))
}

window.__devBotInstall = function() {
  const def = _devBotRead(null)
  if (!def) return
  devBotsSave([...devBotsLoad(), def])
  document.getElementById('devBotSheet')?.remove()
  _devBotDraft = null
  _mobVRenderStrategies(document.getElementById('mobVContent'))
  _paperToast(_T('Bot added — press Run when you are ready', 'Bot añadido — pulsa Ejecutar cuando quieras'), 'success')
}

/**
 * The file format, written out in full.
 *
 * Kept in the app rather than in a README because the person writing the file is often not
 * the person who has the repo — a friend hands you a .js and never sees this codebase. If
 * the contract only existed in a comment next to the runner, they would be guessing.
 */
window.__devBotSpec = function() {
  const h = (txt) => `<div style="font-size:10px;font-weight:800;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:16px 0 6px">${txt}</div>`
  const p = (txt) => `<p style="font-size:12px;line-height:1.6;color:var(--fg-2);margin:0 0 8px">${txt}</p>`
  const pre = (txt) => `<pre style="background:var(--panel-1);border:1px solid var(--border);border-radius:9px;padding:10px 11px;font-family:var(--font-mono);font-size:11px;line-height:1.55;overflow-x:auto;margin:0 0 8px;color:var(--fg-2)">${esc(txt)}</pre>`

  _devBotSheet(_T('Bot file format', 'Formato del archivo'), `
    ${p(_T('A plain <b>.js</b> file. No imports, no exports, no build step — paste it or upload it as it is.',
           'Un archivo <b>.js</b> normal. Sin imports, sin exports, sin compilación — pégalo o súbelo tal cual.'))}

    ${h(_T('The one thing it must have', 'Lo único obligatorio'))}
    ${p(_T('A function called <b>onTick</b>. Nothing else is required, and nothing else is looked for.',
           'Una función llamada <b>onTick</b>. Nada más es obligatorio ni se busca.'))}
    ${pre('function onTick(ctx) {\n  // your logic\n}')}
    ${p(_T('It may be <b>async</b>. It is called once every N seconds, where N is the interval you set when adding the bot.',
           'Puede ser <b>async</b>. Se llama cada N segundos, según el intervalo que definas al añadir el bot.'))}

    ${h(_T('What you get: ctx', 'Lo que recibes: ctx'))}
    ${pre(`ctx = {
  coin:      "BTC",        // the market you chose for this bot
  mark:      78123.5,      // its current mark price
  tick:      1735600000000,// ms timestamp of this tick
  paper:     true,         // true on a practice account
  equity:    1042.11,      // account value, USDC

  position:  { szi, entryPx, unrealizedPnl } | null,   // in ctx.coin
  openOrders:[ { oid, isBuy, sz, limitPx } ],          // in ctx.coin
  candles:   [ { t, o, h, l, c, v } ],   // ~200 recent 1h, oldest first

  // the whole account, if you want more than one market
  mids:      { BTC: "78123.5", ETH: "2431.0", ... },
  positions: [ { coin, szi, entryPx, unrealizedPnl,
                 leverage, liquidationPx, marginUsed } ],
  orders:    [ { oid, coin, isBuy, sz, limitPx } ],
  margin:    { accountValue, totalMarginUsed, withdrawable },
}`)}
    ${p(_T('Numbers are numbers, except <b>mids</b>, which Hyperliquid gives as strings.',
           'Los números son números, salvo <b>mids</b>, que Hyperliquid entrega como cadenas.'))}
    ${p(_T('<b>ctx.candles</b> is a convenience and is often <b>empty on the first few ticks</b> while history loads — always check its length. When you need history you can rely on, ask for it directly with <b>api.candles()</b>, which fetches on the spot.',
           '<b>ctx.candles</b> es una comodidad y suele estar <b>vacío en los primeros ticks</b> mientras carga el historial — comprueba siempre su longitud. Si necesitas historial fiable, pídelo con <b>api.candles()</b>, que lo trae al momento.'))}

    ${h(_T('The simple way to act: return an intent', 'La forma simple de actuar: devuelve una intención'))}
    ${p(_T('Return one object, an array of them, or nothing at all.', 'Devuelve un objeto, un array, o nada.'))}
    ${pre(`{ type: "market", isBuy: true,  usd: 25 }
{ type: "limit",  isBuy: false, usd: 25, px: 80000 }
{ type: "cancel", oid: 123456789 }
{ type: "close" }`)}
    ${p(_T('Sizes are in <b>USD</b>, not coins — the app converts at the price it sends at. Every intent is checked against the limits you set; a refusal is logged and dropped.',
           'Los tamaños van en <b>USD</b>, no en monedas — la app convierte al precio de envío. Cada intención se comprueba contra tus límites; un rechazo se registra y se descarta.'))}

    ${h(_T('The full way: api', 'La forma completa: api'))}
    ${pre(`await api.info({ type: "l2Book", coin: "BTC" })   // any public /info
await api.candles("ETH", "15m", Date.now() - 86400000)
await api.order({ orders: [ ... ], grouping: "na" })
await api.cancel({ cancels: [ { a: 0, o: 123 } ] })
await api.exchange("updateLeverage",
  { asset: 0, isCross: true, leverage: 5 })`)}
    ${p(_T('These are signed by the app, not by your file — your key is never inside the sandbox. Anything that moves funds, or approves another agent, is refused.',
           'La app las firma, no tu archivo — tu clave nunca está en el entorno aislado. Todo lo que mueva fondos, o apruebe otro agente, se rechaza.'))}

    ${h(_T('Logging', 'Registro'))}
    ${pre('log("anything", 123, obj)')}
    ${p(_T('Writes to the Log panel for this bot. <b>console.log</b> goes nowhere you can see.',
           'Escribe en el panel de Registro de este bot. <b>console.log</b> no se ve en ningún sitio.'))}

    ${h(_T('Names you can use', 'Nombres que puedes usar'))}
    ${p(_T('All of them. Your file runs in its own scope, so declaring your own <b>log</b>, <b>api</b> or anything else will not clash with the app — it only shadows the helper for your file.',
           'Todos. Tu archivo corre en su propio ámbito, así que declarar tu propio <b>log</b>, <b>api</b> o cualquier otro no choca con la app — solo oculta la ayuda para tu archivo.'))}

    ${h(_T('What is not available', 'Lo que no está disponible'))}
    ${p(_T('<b>window</b>, <b>document</b>, <b>localStorage</b>, and <b>import</b> / <b>require</b>. This is a Web Worker, so there is no page and no module loader — put everything in the one file. <b>fetch</b> does work.',
           '<b>window</b>, <b>document</b>, <b>localStorage</b> e <b>import</b> / <b>require</b>. Es un Web Worker: no hay página ni cargador de módulos — todo en un solo archivo. <b>fetch</b> sí funciona.'))}

    ${h(_T('Errors', 'Errores'))}
    ${p(_T('A throw inside one tick is logged and the bot keeps running. A file with no <b>onTick</b>, or one that fails to parse, is refused at install with the reason.',
           'Un error en un tick se registra y el bot sigue. Un archivo sin <b>onTick</b>, o que no compila, se rechaza al instalar indicando el motivo.'))}

    ${h(_T('A complete example', 'Un ejemplo completo'))}
    ${pre(`function onTick(ctx) {
  if (!ctx.candles || ctx.candles.length < 20) return

  const closes = ctx.candles.map(k => Number(k.c))
  const sma20  = closes.slice(-20).reduce((a, b) => a + b, 0) / 20
  const long   = ctx.position && Number(ctx.position.szi) > 0

  if (ctx.mark > sma20 && !long)  return { type: "market", isBuy: true, usd: 20 }
  if (ctx.mark < sma20 && long)   return { type: "close" }
}`)}
  `)
}

function _devBotInstallSheet(existing = null) {
  const d = _devBotDraft ?? { code: DEVBOT_TEMPLATE, name: '' }
  const ed = !!existing
  const inp = 'width:100%;box-sizing:border-box;background:var(--panel-1);border:1px solid var(--border);border-radius:9px;padding:8px 10px;font-size:13px;color:var(--fg);outline:none'
  const lbl = 'font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px;display:block'
  const coins = [...new Set([
    ...(state.perpState?.assetPositions ?? []).map(p => p.position.coin),
    'BTC', 'ETH', 'SOL', 'HYPE',
  ])].filter(c => c && !String(c).startsWith('@')).slice(0, 20)

  _devBotSheet(ed ? _T('Edit bot', 'Editar bot') : _T('Add a bot', 'Añadir un bot'), `
    <div style="font-size:12px;line-height:1.6;color:var(--fg-2)">
      ${_T('This runs on your device, in a sandbox with no access to your keys — it cannot sign anything. It asks this app to place orders, and this app checks every request against the limits you set below.',
           'Se ejecuta en tu dispositivo, en un entorno aislado sin acceso a tus claves — no puede firmar nada. Pide a la app que coloque órdenes, y la app comprueba cada petición contra los límites que definas.')}
    </div>
    <div style="font-size:11.5px;line-height:1.6;color:var(--fg-2);background:rgba(255,138,42,.10);border:1px solid rgba(255,138,42,.28);border-radius:10px;padding:10px 12px;margin-top:10px">
      ${_T('It <b>can</b> still send what it is given — the market it runs on, your position in it, your equity — to any server it likes. It <b>cannot</b> read your private key, your other markets, or the rest of your portfolio. Only run a file you wrote or have read.',
           'Sí <b>puede</b> enviar lo que recibe — el mercado, tu posición en él, tu capital — a cualquier servidor. <b>No puede</b> leer tu clave privada, tus otros mercados ni el resto de tu cartera. Ejecuta solo un archivo que hayas escrito o leído.')}
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px">
      <div><label style="${lbl}">${_T('Name', 'Nombre')}</label><input id="devBotName" style="${inp}" value="${esc(d.name)}" placeholder="My bot"></div>
      <div><label style="${lbl}">${_T('Add a market', 'Añadir mercado')}</label>
        <select id="devBotCoin" onchange="window.__devBotAddCoin(this)" style="${inp}">${coins.map(c => `<option value="${esc(c)}"${c === d.coin ? ' selected' : ''}>${esc(_ocCoinLabel(c))}</option>`).join('')}</select></div>
      <div><label style="${lbl}">${_T('Max per order', 'Máx. por orden')} ($)</label><input id="devBotMaxUsd" type="number" min="0" style="${inp}" value="${d.maxUsd ?? 25}"></div>
      <div><label style="${lbl}">${_T('Max orders / min', 'Máx. órdenes/min')}</label><input id="devBotMaxMin" type="number" min="0" max="600" style="${inp}" value="${d.maxPerMin ?? 4}"></div>
      <div><label style="${lbl}">${_T('Max resting orders', 'Máx. órdenes en espera')}</label><input id="devBotMaxOpen" type="number" min="0" max="1000" style="${inp}" value="${d.maxOpen ?? 10}"></div>
      <div><label style="${lbl}">${_T('Run every (s)', 'Ejecutar cada (s)')}</label><input id="devBotEvery" type="number" min="5" style="${inp}" value="${d.everySec ?? 15}"></div>
      <div><label style="${lbl}">${_T('Leverage', 'Apalancamiento')}</label><input id="devBotLev" type="number" min="1" style="${inp}" value="${d.leverage ?? 3}"></div>
    </div>
    <input type="hidden" id="devBotCoins" value="${esc(JSON.stringify(_devBotCoinsOf(d)))}">
    <div style="margin-top:10px">
      <label style="${lbl}">${_T('Markets this bot may trade', 'Mercados que este bot puede operar')}</label>
      <div id="devBotCoinChips" style="display:flex;flex-wrap:wrap;gap:6px;margin-top:5px">${_devBotChipsHtml(_devBotCoinsOf(d))}</div>
      <div style="font-size:10.5px;color:var(--fg-3);margin-top:6px;line-height:1.5">${
        _T('The bot can only touch these. The first is its home market — the one its candles are loaded for, and the one an order that names no market goes to.',
           'El bot solo puede tocar estos. El primero es su mercado principal: aquel del que se cargan las velas y al que va una orden que no nombre mercado.')}
      </div>
    </div>

    <div style="font-size:10.5px;color:var(--fg-3);margin-top:7px;line-height:1.5">${
      _T('Set any of the three caps to 0 to turn that limit off.', 'Pon cualquiera de los tres límites a 0 para desactivarlo.')}
    </div>

    <div style="margin-top:14px">
      <label style="${lbl}">${_T('Settings', 'Ajustes')}</label>
      <div style="font-size:10.5px;color:var(--fg-3);margin:2px 0 5px;line-height:1.5">${
        _T('The knobs this bot declares, one <b>name = value</b> per line. They reach it as <b>ctx.config.params</b>, so changing one is a form field rather than an edit to the file.',
           'Los ajustes del bot, uno por línea como <b>nombre = valor</b>. Llegan como <b>ctx.config.params</b>, así que cambiar uno no obliga a editar el archivo.')}
      </div>
      <textarea id="devBotParams" rows="4" spellcheck="false" placeholder="riesgo = 0.03&#10;usarPesos = false"
        style="${inp};font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;line-height:1.6;resize:vertical;white-space:pre">${esc(d.params ?? '')}</textarea>
    </div>

    <div style="display:flex;align-items:center;margin-top:12px">
      <label style="${lbl};margin:0">${_T('Bot file', 'Archivo del bot')}</label>
      <span style="flex:1"></span>
      <button onclick="window.__devBotSpec()" style="background:transparent;border:1px solid var(--border2);border-radius:7px;color:var(--fg-2);font-size:11px;font-weight:700;padding:3px 9px;cursor:pointer">${_T('File format', 'Formato')}</button>
    </div>
    <textarea id="devBotCode" rows="12" spellcheck="false" style="${inp};font-family:var(--font-mono);font-size:11.5px;line-height:1.5;resize:vertical">${esc(d.code)}</textarea>

    <label style="display:flex;align-items:flex-start;gap:9px;margin-top:12px;font-size:12px;line-height:1.5;color:var(--fg-2);cursor:pointer">
      <input type="checkbox" id="devBotAck" style="margin-top:2px;flex-shrink:0">
      <span>${_T('I wrote this file or I have read it, and I understand it will place real orders within the limits above.',
                 'Escribí este archivo o lo he leído, y entiendo que colocará órdenes reales dentro de los límites anteriores.')}</span>
    </label>
    <button onclick="${ed ? `window.__devBotUpdate('${existing.id}')` : 'window.__devBotInstall()'}" style="width:100%;margin-top:12px;background:var(--accent);color:#000;border:none;border-radius:10px;padding:11px;font-size:14px;font-weight:700;cursor:pointer">${
      ed ? _T('Update bot', 'Actualizar bot') : _T('Add bot', 'Añadir bot')}</button>
    ${ed ? `<div style="font-size:10.5px;color:var(--fg-3);margin-top:8px;line-height:1.5;text-align:center">${
      _T('If it is running it will be restarted, so the new file is what actually runs.',
         'Si está activo se reiniciará, para que el archivo nuevo sea el que corre.')}</div>` : ''}
  `)
}

// ── the section in Strats ───────────────────────────────────────────────────
/**
 * A device bot rendered as one of the ordinary bot cards.
 *
 * Same markup as the built-ins — the flip, the badge, the accent, the expanding body — so
 * a bot you wrote sits in the list as a peer rather than in a bolt-on section underneath.
 * The only honest difference is the "on this device" chip, which is information, not status.
 *
 * The back of the card shows the file's own opening comment. A bot author documents at the
 * top of the file whether anyone asked them to or not, so that text already exists; this
 * just puts it where a reader looks.
 */
function _devBotHeaderDoc(code) {
  const lines = String(code ?? '').split(String.fromCharCode(10))
  const out = []
  for (const raw of lines) {
    const l = raw.trim()
    if (!l) { if (out.length) break; continue }
    if (l.startsWith('//')) {
      const t = l.replace(/^\/+\s?/, '').trim()
      if (/^[-─=]{3,}$/.test(t)) continue          // rule lines, not prose
      out.push(t)
      if (out.join(' ').length > 400) break
    } else break                                    // first line of real code ends the doc
  }
  return out.join(' ').trim()
}

function _devBotCardHtml(b) {
  const bot = _devBots.get(b.id)
  const running = !!(bot && bot.worker && !bot.stopped)
  const dry = running && bot.dry
  const accent = dry ? 'var(--orange,#f59e0b)' : '#8b5cf6'
  const expanded = _mobExpandedStrat === 'dev-' + b.id
  const doc = _devBotHeaderDoc(b.code)
  const sb = 'padding:6px 10px;border-radius:8px;font-size:11.5px;font-weight:700;cursor:pointer;white-space:nowrap'

  const body = `
    <div style="display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--fg-2);margin-bottom:11px">
      <span>${(() => { const m = botCoins(b)
        return m.length > 1
          ? `${_T('Markets', 'Mercados')} <b>${m.length}</b> · ${esc(m.map(_ocCoinLabel).join(', '))}`
          : `${_T('Market', 'Mercado')} <b>${esc(_ocCoinLabel(b.coin))}</b>` })()}</span>
      <span>${b.maxUsd > 0 ? `${_T('max', 'máx')} <b>$${b.maxUsd}</b>/${_T('order', 'orden')}` : `<b>${_T('no size cap', 'sin límite')}</b>`}</span>
      <span>${b.maxPerMin > 0 ? `<b>${b.maxPerMin}</b>/${_T('min', 'min')}` : `<b>${_T('no rate cap', 'sin límite')}</b>`}</span>
      <span>${_T('every', 'cada')} <b>${b.everySec}s</b></span>
      <span>${_T('leverage', 'apalanc.')} <b>${b.leverage}×</b></span>
      ${bot?.blocked ? `<span style="color:var(--orange,#f59e0b)"><b>${bot.blocked}</b> ${_T('blocked', 'bloqueadas')}</span>` : ''}
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      ${running
        ? `<button onclick="window.__devBotStop('${b.id}')" style="${sb};flex:1;border:1px solid var(--red);background:transparent;color:var(--red)">■ ${_T('Stop', 'Parar')}</button>`
        : `<button onclick="window.__devBotStart('${b.id}')" style="${sb};flex:1;border:none;background:var(--accent);color:#000">▶ ${_T('Run', 'Ejecutar')}</button>`}
      <button class="mob-strat-logs-btn" onclick="window.__devBotPreview('${b.id}')" title="${_T('See what it would do, without doing it', 'Ver qué haría, sin hacerlo')}">👁 ${_T('Preview', 'Vista previa')}</button>
      <button class="mob-strat-logs-btn" onclick="window.__devBotEdit('${b.id}')">✎ ${_T('Edit', 'Editar')}</button>
      <button class="mob-strat-logs-btn" onclick="window.__devBotLogs('${b.id}')">${_T('Log', 'Registro')}</button>
      <button class="mob-strat-logs-btn" onclick="window.__devBotSubmit('${b.id}')">${_T('Submit', 'Enviar')}</button>
      <button class="mob-strat-logs-btn" onclick="window.__devBotDelete('${b.id}')">${_T('Delete', 'Borrar')}</button>
    </div>`

  return `<div class="mob-strat-card${running ? ' mob-strat-running' : ''}" id="strat-card-dev-${b.id}" style="--strat-accent:${accent}">
    <div class="strat-flip">
      <div class="strat-face strat-front">
        <div class="mob-strat-header" onclick="window._mobExpandStrat('dev-${b.id}')">
          <span class="strat-badge">🧩</span>
          <div style="flex:1;min-width:0">
            <div class="strat-name">${esc(b.name)}${
              running ? `<span class="strat-live"><i></i>${dry ? _T('Dry run', 'Simulación') : _T('Running', 'Activo')}</span>` : ''}</div>
            <div class="strat-tag">${(() => {
              const m = botCoins(b)
              const where = m.length > 1 ? m.length + ' ' + _T('markets', 'mercados') : esc(_ocCoinLabel(b.coin))
              return running
                ? where + ' · ' + (dry ? _T('sending nothing', 'sin enviar nada') : _T('live', 'en vivo'))
                : _T('Your file', 'Tu archivo') + ' · ' + where })()}</div>
          </div>
          ${doc ? `<button class="strat-info" title="${_T('What does this do?', '¿Qué hace esto?')}" aria-label="${_T('What does this do?', '¿Qué hace esto?')}"
            onclick="event.stopPropagation();window.__stratFlip('dev-${b.id}',true)">?</button>` : ''}
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="color:var(--muted);flex-shrink:0;transform:rotate(${expanded ? 180 : 0}deg);transition:transform .2s"><polyline points="6 9 12 15 18 9"/></svg>
        </div>
      </div>
      ${doc ? `<div class="strat-face strat-back">
        <div class="strat-back-head">
          <span class="strat-badge">🧩</span>
          <span class="strat-name">${esc(b.name)}</span>
          <span style="flex:1"></span>
          <button class="strat-info" aria-label="${_T('Back', 'Volver')}" onclick="event.stopPropagation();window.__stratFlip('dev-${b.id}',false)">&times;</button>
        </div>
        <p class="strat-about"><b>${_T('From the file', 'Del archivo')}</b> ${esc(doc)}</p>
        <p class="strat-about sig-caveat"><b>${_T('Runs where', 'Dónde corre')}</b> ${
          _T('In this browser, on your machine. It stops when you close the app, and it is not covered by a subscription.',
             'En este navegador, en tu máquina. Se detiene al cerrar la app y no requiere suscripción.')}</p>
      </div>` : ''}
    </div>
    ${expanded ? `<div class="mob-strat-body">${body}</div>` : ''}
  </div>`
}

function _devBotsHtml() {
  const list = devBotsLoad()
  const row = (b) => {
    const bot = _devBots.get(b.id)
    const running = !!(bot && bot.worker && !bot.stopped)
    const dry = running && bot.dry
    // The dangerous confusion is believing a live bot is a preview, so a running bot always
    // states which it is — in its own colour, on the card, not only in the log.
    const tone = !running ? 'var(--border2)' : dry ? 'var(--orange,#f59e0b)' : 'var(--green)'
    const sb = 'padding:5px 9px;border-radius:7px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap'
    return `<div style="border:1px solid ${tone};border-radius:12px;background:var(--panel-2);padding:11px 12px;margin-bottom:8px">
      <div style="display:flex;align-items:center;gap:8px">
        <span style="width:8px;height:8px;border-radius:50%;background:${tone};flex-shrink:0"></span>
        <span style="font-size:13.5px;font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(b.name)}</span>
        ${dry ? `<span style="font-size:9px;font-weight:800;color:var(--orange,#f59e0b);border:1px solid var(--orange,#f59e0b);border-radius:4px;padding:1px 4px;white-space:nowrap">${_T('DRY RUN', 'SIMULACIÓN')}</span>` : ''}
        <span style="font-size:10.5px;color:var(--muted);white-space:nowrap">${esc(_ocCoinLabel(b.coin))}</span>
        <span style="flex:1"></span>
        ${running
          ? `<button onclick="window.__devBotStop('${b.id}')" style="${sb};border:1px solid var(--red);background:transparent;color:var(--red)">■ ${_T('Stop', 'Parar')}</button>`
          : `<button onclick="window.__devBotPreview('${b.id}')" title="${_T('Run it for real, but send nothing', 'Ejecútalo de verdad, sin enviar nada')}" style="${sb};border:1px solid var(--orange,#f59e0b);background:transparent;color:var(--orange,#f59e0b)">👁 ${_T('Preview', 'Vista previa')}</button>
             <button onclick="window.__devBotStart('${b.id}')" style="${sb};border:none;background:var(--accent);color:#000">▶ ${_T('Run', 'Ejecutar')}</button>`}
        <button onclick="window.__devBotEdit('${b.id}')" style="${sb};border:1px solid var(--accent);background:transparent;color:var(--accent)">✎ ${_T('Edit', 'Editar')}</button>
        <button onclick="window.__devBotLogs('${b.id}')" style="${sb};border:1px solid var(--border2);background:transparent;color:var(--muted)">${_T('Log', 'Registro')}</button>
        <button onclick="window.__devBotDelete('${b.id}')" aria-label="Delete" style="${sb};border:none;background:transparent;color:var(--muted);font-size:16px">&times;</button>
      </div>
      <div style="font-size:10.5px;color:var(--fg-3);margin-top:6px">
        ${b.maxUsd > 0 ? `${_T('max', 'máx')} $${b.maxUsd}/${_T('order', 'orden')}` : _T('no size cap', 'sin límite de tamaño')} · ${
          b.maxPerMin > 0 ? `${b.maxPerMin}/${_T('min', 'min')}` : _T('no rate cap', 'sin límite de ritmo')} · ${_T('every', 'cada')} ${b.everySec}s${
          bot?.blocked ? ` · <span style="color:var(--orange,#f59e0b)">${bot.blocked} ${_T('blocked', 'bloqueadas')}</span>` : ''}
      </div>
    </div>`
  }
  // Device bots are rendered as ordinary bot cards, in the same list as the built-ins —
  // this returns only the "add one" affordance that follows them.
  return `<div style="display:flex;gap:8px;margin:2px 0 6px">
      <button onclick="window.__devBotNew()" style="flex:1;background:transparent;border:1px dashed var(--border2);border-radius:10px;color:var(--fg-2);font-size:12.5px;font-weight:700;padding:11px;cursor:pointer">+ ${_T('Write your own bot', 'Escribe tu propio bot')}</button>
      <label style="flex:1;background:transparent;border:1px dashed var(--border2);border-radius:10px;color:var(--fg-2);font-size:12.5px;font-weight:700;padding:11px;cursor:pointer;text-align:center">
        ${_T('Upload .js', 'Subir .js')}<input type="file" accept=".js,.txt,text/javascript" style="display:none" onchange="window.__devBotPickFile(this)">
      </label>
    </div>
    <div style="font-size:11px;color:var(--fg-3);line-height:1.5;margin:0 2px 4px">${
      _T('Your own bots run in this browser, not on our servers — they stop when you close the app, and need no subscription.',
         'Tus bots corren en este navegador, no en nuestros servidores — se detienen al cerrar la app y no requieren suscripción.')}
      <button onclick="window.__devBotSpec()" style="background:none;border:none;padding:0;color:var(--accent);font-size:11px;font-weight:700;cursor:pointer;text-decoration:underline">${_T('File format', 'Formato del archivo')}</button>
    </div>`
}

function _mobVRenderStrategies(el) {
  // Combined view: the launch UI targets one account, so instead show a read-only list
  // of every bot running across all accounts in the view. Starting/configuring new bots
  // is done by switching to a single account.
  // Combined view used to be read-only here. It no longer is: the running-bot list stays,
  // and the launch UI below it arms bots on whichever account the picker names.
  if (state.isAllAccounts && !_stratTargetAddr()) { _mobVRenderAllAcctStrats(el); return }
  // Kick a status refresh (throttled). Dev mode bypasses locally; the server bypasses for
  // admin; everyone else hits 402 at /api/start whatever this renders.
  //
  // The bots stay VISIBLE when locked. Hiding them behind the paywall meant nobody could
  // see what the $10 actually buys — the page asked for money to unlock a list of names.
  // So the cards, their descriptions and every config field stay browsable, and only the
  // two controls that would call /api/start are locked. Stop, Pause, Resume, Restart and
  // Logs stay live: those endpoints are not gated server-side either, because a lapsed
  // subscription must not strand someone's running position.
  _subRefresh()
  const locked = !_stratsUnlocked()
  if (locked) _subWatchRestore()
  // Preserve in-progress edits across re-renders. This view rebuilds via innerHTML on a
  // server-status poll or any toggle (Cross/Isolated, Long/Short, %/$, size unit). The
  // config inputs carry no value= attribute, so without this a re-render mid-typing wipes
  // them back to placeholders (looked like fields "changing to random numbers"). Snapshot
  // every input's value + size-unit data-mode now, restore after the rebuild below.
  const _preserved = {}
  el.querySelectorAll('input[id]').forEach(i => { _preserved[i.id] = { v: i.value, mode: i.dataset.mode } })
  const _focusedId = (document.activeElement && el.contains(document.activeElement)) ? document.activeElement.id : null
  // The key belongs to the TARGET account, not to state.addr — which in the combined view
  // is the "__all_accounts__" sentinel and owns no key. Reading it there showed an empty
  // box and "Not connected" for accounts whose keys were already saved and already signing
  // closes, and asked the user to paste all nine again.
  const savedKey = _stratTargetKey() || ''
  const serverBadge = serverOnline
    ? `<span style="font-size:11px;color:var(--green)">server ● online</span>`
    : `<span style="font-size:11px;color:var(--red)">server ○ offline</span>`
  // isConnected()/getWalletAddress() describe the ONE globally-connected client, which in
  // the combined view is whichever account happened to connect last — not the one selected.
  // hasAgentFor asks the per-account registry instead.
  const _tgt        = _stratTargetAddr()
  const _hasKey     = !!savedKey
  const agentAddr   = _hasKey ? (() => { try { return agentAddressOf(savedKey) } catch { return null } })()
                    : (isConnected() ? getWalletAddress() : null)
  const agentStatus = agentAddr
    ? `<span style="color:var(--green)">✓ ${_T('Saved for this account', 'Guardada para esta cuenta')}: ${agentAddr.slice(0,6)}...${agentAddr.slice(-4)}</span>`
    : `<span style="color:var(--muted)">${_T('No key saved for this account', 'Sin clave guardada para esta cuenta')}</span>`

  const stratsConfig = [
    { type: 'accumulator', label: _T('🪙 Profit Stack', '🪙 Pila de ganancias'), desc: _T('Skim a % of winning trades into spot', 'Aparta un % de las operaciones ganadoras en spot') },
    { type: 'dca',     label: _T('DCA Bot', 'Bot DCA'),               desc: _T('Dollar-cost average into a position', 'Promedia el costo hacia una posición')      },
    { type: 'grid',    label: _T('Grid Bot', 'Bot de rejilla'),      desc: _T('Range grid with automatic rebalancing', 'Rejilla de rango con reajuste automático') },
    { type: 'trend',   label: _T('Trend Follower', 'Seguidor de tendencia'), desc: _T('EMA crossover trend following', 'Seguimiento por cruce de EMA')          },
    { type: 'longer',  label: _T('Longer Bot', 'Bot Largo'),         desc: _T('Long bias with take-profit / stop-loss', 'Sesgo largo con toma de ganancias / stop de pérdida') },
    { type: 'shorter', label: _T('Shorter Bot', 'Bot Corto'),        desc: _T('Short bias with take-profit / stop-loss', 'Sesgo corto con toma de ganancias / stop de pérdida')},
    { type: 'copytrade', label: _T('⇄ Copy Trade', '⇄ Copiar operaciones'), desc: _T('Mirror another wallet\'s trades', 'Refleja las operaciones de otra billetera') },
  ]

  const cards = stratsConfig.map(s => {
    const running  = !!serverStatus[s.type]
    const expanded = _mobExpandedStrat === s.type
    const dot = `<span style="width:8px;height:8px;border-radius:50%;flex-shrink:0;background:${running ? 'var(--green)' : 'var(--border2)'};display:inline-block;margin-right:8px"></span>`

    let bodyHtml = ''
    if (expanded) {
      if (s.type === 'accumulator') {
        bodyHtml = `
          <div style="font-size:11px;color:var(--muted);line-height:1.5;margin-bottom:12px">${_T('Takes a cut of every <b style="color:var(--green)">net-profitable</b> window across <b>all</b> your bots and buys spot — a stack that\'s ring-fenced from perp risk (only USDC is collateral, not your accumulated token). One per account.', 'Toma una parte de cada ventana <b style="color:var(--green)">con ganancia neta</b> de <b>todos</b> tus bots y compra spot — una pila aislada del riesgo de perps (solo USDC es garantía, no tu token acumulado). Una por cuenta.')}</div>
          <div class="mob-strat-field"><span class="mob-strat-label" title="Spot token to accumulate (must have a SYM/USDC spot pair)">Accumulate</span><input class="mob-strat-input" id="m-accum-asset" placeholder="HYPE"></div>
          <div class="mob-strat-field"><span class="mob-strat-label" title="% of net realized profit skimmed each window">Cut %</span><input class="mob-strat-input" id="m-accum-cut" type="number" placeholder="25"></div>
          <div class="mob-strat-field"><span class="mob-strat-label" title="Buffer up to this USD before each spot buy. ~$11 is the floor — it fires as soon as that stacks, clearing HL's $10 min after fees. Set higher to batch bigger buys.">Buy at ($)</span><input class="mob-strat-input" id="m-accum-threshold" type="number" placeholder="11"></div>
          <div class="mob-strat-field"><span class="mob-strat-label" title="Optional cap on USD skimmed per day (0 = no cap)">Max / day ($)</span><input class="mob-strat-input" id="m-accum-maxdaily" type="number" placeholder="0"></div>
          <div class="mob-strat-field mob-strat-field--full">
            <span class="mob-strat-label">${_T('Mode', 'Modo')}</span>
            <div class="mob-seg${_mobAccumDryRun ? '' : ' mob-seg--live'}" data-seg="accum-mode">
              <button class="mob-seg-b${_mobAccumDryRun ? '' : ' on'}" onclick="window._mobSetAccumDryRun(false, this)">${_T('Live', 'En vivo')}</button>
              <button class="mob-seg-b${_mobAccumDryRun ? ' on' : ''}" onclick="window._mobSetAccumDryRun(true, this)">${_T('Dry-run', 'Simulación')}</button>
            </div>
            <div class="mob-strat-hint">${_mobAccumDryRun ? _ACCUM_MODE_HINT.dry : _ACCUM_MODE_HINT.live}</div>
          </div>`
      } else if (s.type === 'dca') {
        bodyHtml = `
          <div class="mob-strat-field"><span class="mob-strat-label">Coin</span><input class="mob-strat-input" id="m-dca-coin" placeholder="BTC"></div>
          <div class="mob-strat-field">
            <span class="mob-strat-label">Side</span>
            <button class="btn-size-unit active" style="color:var(--green)" onclick="window._mobToggleDcaSide(this)">${_mobDcaSide === 'long' ? 'Long' : 'Short'}</button>
          </div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Size</span><button class="btn-size-unit" id="m-tog-dca-size" onclick="window._mobToggleSizeMode('m-dca-size','m-dca-coin',this)">TKN</button></div>
            <input class="mob-strat-input" id="m-dca-size" type="number" placeholder="100" data-mode="usd">
          </div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Mode</span><button class="btn-size-unit${_mobDcaMode === 'time' ? ' active' : ''}" onclick="window._mobToggleDcaMode(this)">${_mobDcaMode === 'time' ? 'Time' : 'Drop'}</button></div>
          </div>
          <div id="m-dca-drop-row" class="mob-strat-field" style="display:${_mobDcaMode === 'drop' ? 'block' : 'none'}"><span class="mob-strat-label">Drop % trigger</span><input class="mob-strat-input" id="m-dca-droppct" type="number" placeholder="2"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Interval (min)</span><input class="mob-strat-input" id="m-dca-interval" type="number" placeholder="${_mobDcaMode === 'drop' ? '5' : '60'}"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Max Orders</span><input class="mob-strat-input" id="m-dca-maxorders" type="number" placeholder="10"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Max Position ($)</span><input class="mob-strat-input" id="m-dca-maxpos" type="number" placeholder="0"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Leverage</span><input class="mob-strat-input" id="m-dca-leverage" type="number" placeholder="1"></div>`
      } else if (s.type === 'grid') {
        bodyHtml = `
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Direction</span>
              <button class="btn-size-unit${_gridSide === 'long' ? ' active' : ''}" onclick="window.toggleGridSide()">${_gridSide === 'short' ? 'Short ↓' : 'Long ↑'}</button>
            </div>
          </div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Margin</span>
              <button class="btn-size-unit${_gridMargin === 'cross' ? ' active' : ''}" onclick="window.toggleGridMargin()">${_gridMargin === 'isolated' ? 'Isolated' : 'Cross'}</button>
            </div>
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Coin</span><input class="mob-strat-input" id="m-grid-coin" placeholder="${esc(state.selectedCoin || 'BTC')}" oninput="_applyGridDefaults('m-grid-coin','m-grid-lower','m-grid-upper')"></div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">${_gridRangeMode === 'pct' ? 'Lower %' : 'Lower Price'}</span><button class="btn-size-unit${_gridRangeMode === 'pct' ? ' active' : ''}" onclick="window.toggleGridRange(this)">${_gridRangeMode === 'pct' ? '%' : '$'}</button></div>
            <input class="mob-strat-input" id="m-grid-lower" type="number" placeholder="${_gridRangeMode === 'pct' ? '-10' : 'auto'}">
          </div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">${_gridRangeMode === 'pct' ? 'Upper %' : 'Upper Price'}</span></div>
            <input class="mob-strat-input" id="m-grid-upper" type="number" placeholder="${_gridRangeMode === 'pct' ? '10' : 'auto'}">
          </div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" id="m-lbl-grid-levels" style="margin:0">${_mobGridSpacing === 'pct' ? 'Level Spacing %' : 'Grid Levels'}</span><button class="btn-size-unit${_mobGridSpacing === 'pct' ? ' active' : ''}" onclick="window._mobToggleGridSpacing(this)">${_mobGridSpacing === 'pct' ? '%' : '$'}</button></div>
            <input class="mob-strat-input" id="m-grid-levels" type="number" placeholder="10">
          </div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Size per Level</span><button class="btn-size-unit active" id="m-tog-grid-size" onclick="window._mobToggleSizeMode('m-grid-size','m-grid-coin',this)">TKN</button></div>
            <input class="mob-strat-input" id="m-grid-size" type="number" placeholder="auto" data-mode="token">
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Leverage</span><input class="mob-strat-input" id="m-grid-leverage" type="number" placeholder="10"></div>
          <div class="mob-strat-field" id="m-grid-totmargin-row"><span class="mob-strat-label" title="Cap the margin THIS position may use. The grid stops adding once its margin hits this — only profit-taking exits continue. Per grid, independent of your other bots. Blank = no cap.">Max Margin ($)</span><input class="mob-strat-input" id="m-grid-totmargin" type="number" placeholder="no cap"></div>
          <div class="mob-strat-field"><span class="mob-strat-label" title="% below entry price before placing first buy when a long exists">Entry Gap %</span><input class="mob-strat-input" id="m-grid-entry-gap" type="number" placeholder="3"></div>`
      } else if (s.type === 'trend') {
        bodyHtml = `
          <div class="mob-strat-field"><span class="mob-strat-label">Coin</span><input class="mob-strat-input" id="m-trend-coin" placeholder="BTC"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Fast EMA</span><input class="mob-strat-input" id="m-trend-fast" type="number" placeholder="9"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Slow EMA</span><input class="mob-strat-input" id="m-trend-slow" type="number" placeholder="21"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Timeframe</span><input class="mob-strat-input" id="m-trend-tf" placeholder="1h"></div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Size</span><button class="btn-size-unit" id="m-tog-trend-size" onclick="window._mobToggleSizeMode('m-trend-size','m-trend-coin',this)">TKN</button></div>
            <input class="mob-strat-input" id="m-trend-size" type="number" placeholder="500" data-mode="usd">
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Leverage</span><input class="mob-strat-input" id="m-trend-leverage" type="number" placeholder="3"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Stop Loss %</span><input class="mob-strat-input" id="m-trend-stoploss" type="number" placeholder="0"></div>`
      } else if (s.type === 'longer') {
        bodyHtml = `
          <div class="mob-strat-field"><span class="mob-strat-label">Coins (comma-separated)</span><input class="mob-strat-input" id="m-longer-coins" placeholder="BTC"></div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Size</span><button class="btn-size-unit" id="m-tog-longer-size" onclick="window._mobToggleSizeMode('m-longer-size','m-longer-coins',this)">TKN</button></div>
            <input class="mob-strat-input" id="m-longer-size" type="number" placeholder="100" data-mode="usd">
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Leverage</span><input class="mob-strat-input" id="m-longer-leverage" type="number" placeholder="2"></div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Trigger</span><button class="btn-size-unit${_mobLongerTrigger === 'always' ? ' active' : ''}" onclick="window._mobToggleLongerTrigger(this)">${_mobLongerTrigger === 'always' ? 'Always' : 'On Dump'}</button></div>
          </div>
          <div id="m-longer-dump-row" class="mob-strat-field" style="display:${_mobLongerTrigger === 'dump' ? 'block' : 'none'}">
            <span class="mob-strat-label">Dump %&nbsp;/&nbsp;Window</span>
            <div style="display:flex;gap:6px"><input class="mob-strat-input" id="m-longer-dumppct" type="number" placeholder="7" style="flex:1"><input class="mob-strat-input" id="m-longer-dumpwindow" placeholder="1d" style="flex:1"></div>
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Take Profit %</span><input class="mob-strat-input" id="m-longer-tp" type="number" placeholder="3"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Stop Loss %</span><input class="mob-strat-input" id="m-longer-sl" type="number" placeholder="2"></div>`
      } else if (s.type === 'shorter') {
        bodyHtml = `
          <div class="mob-strat-field"><span class="mob-strat-label">Coins (comma-separated)</span><input class="mob-strat-input" id="m-shorter-coins" placeholder="BTC"></div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Size</span><button class="btn-size-unit" id="m-tog-shorter-size" onclick="window._mobToggleSizeMode('m-shorter-size','m-shorter-coins',this)">TKN</button></div>
            <input class="mob-strat-input" id="m-shorter-size" type="number" placeholder="100" data-mode="usd">
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Leverage</span><input class="mob-strat-input" id="m-shorter-leverage" type="number" placeholder="2"></div>
          <div class="mob-strat-field">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span class="mob-strat-label" style="margin:0">Trigger</span><button class="btn-size-unit${_mobShorterTrigger === 'always' ? ' active' : ''}" onclick="window._mobToggleShorterTrigger(this)">${_mobShorterTrigger === 'always' ? 'Always' : 'On Pump'}</button></div>
          </div>
          <div id="m-shorter-pump-row" class="mob-strat-field" style="display:${_mobShorterTrigger === 'pump' ? 'block' : 'none'}">
            <span class="mob-strat-label">Pump %&nbsp;/&nbsp;Window</span>
            <div style="display:flex;gap:6px"><input class="mob-strat-input" id="m-shorter-pumppct" type="number" placeholder="7" style="flex:1"><input class="mob-strat-input" id="m-shorter-pumpwindow" placeholder="1d" style="flex:1"></div>
          </div>
          <div class="mob-strat-field"><span class="mob-strat-label">Take Profit %</span><input class="mob-strat-input" id="m-shorter-tp" type="number" placeholder="3"></div>
          <div class="mob-strat-field"><span class="mob-strat-label">Stop Loss %</span><input class="mob-strat-input" id="m-shorter-sl" type="number" placeholder="2"></div>`
      }
      if (s.type === 'copytrade') {
        bodyHtml = `<div style="font-size:11px;color:var(--muted);line-height:1.5;margin-bottom:4px">${_T(
          'Follows a wallet and mirrors every <b>new</b> perp trade it makes onto this account, scaled down. Its current positions are not bought. Start one from any row on the <b>Leaderboard</b>, or with ▶ Run below.',
          'Sigue una billetera y refleja cada <b>nueva</b> operación de perps en esta cuenta, a escala. No compra sus posiciones actuales. Inícialo desde cualquier fila del <b>Ranking</b>, o con ▶ Run.')}</div>`
      }
      const _insts = Object.keys(serverStatus?._instances ?? {}).filter(k => k.startsWith(s.type + ':')).map(k => k.slice(s.type.length + 1))
      const _editing = _mobEditing && _mobEditing.type === s.type
      bodyHtml += `
        ${_editing ? `<div style="font-size:11px;color:var(--accent);font-weight:700;margin-top:10px">✎ Editing ${esc(_mobEditing.instance || 'default')} — change fields, then Update</div>` : ''}
        <div style="display:flex;gap:8px;margin-top:${_editing ? '6' : '14'}px">
          ${locked
            ? `<button class="mob-strat-locked" onclick="window.__subOpenPaywall()">🔒 ${_T('Subscribe to run', 'Suscríbete para usar')}</button>`
            : `<button id="m-run-btn-exp-${s.type}" onclick="window.${_editing ? 'updateStrategyMob' : 'runStrategyMob'}('${s.type}')"
            style="display:flex;flex:1;align-items:center;justify-content:center;padding:8px 0;border-radius:8px;border:none;background:var(--accent);color:#000;font-size:13px;font-weight:700;cursor:pointer">${_editing ? '✓ Update ' + esc(_mobEditing.instance || '') : '▶ Run'}</button>`}
          ${_editing
            ? `<button onclick="window._mobCancelEdit()" style="display:flex;flex:1;align-items:center;justify-content:center;padding:8px 0;border-radius:8px;border:1px solid var(--muted);background:transparent;color:var(--muted);font-size:13px;font-weight:700;cursor:pointer">Cancel</button>`
            : `<button id="m-stop-btn-exp-${s.type}" onclick="window.stopStrategyMob('${s.type}')"
            style="display:${running ? 'flex' : 'none'};flex:1;align-items:center;justify-content:center;padding:8px 0;border-radius:8px;border:1px solid var(--red);background:transparent;color:var(--red);font-size:13px;font-weight:700;cursor:pointer">■ Stop All</button>`}
          ${PREVIEWABLE.has(s.type)
            ? `<button class="mob-strat-logs-btn" onclick="window.__botPreview('${s.type}')" title="${_T('See what it would do, without doing it', 'Ver qué haría, sin hacerlo')}">👁 ${_T('Preview', 'Vista previa')}</button>`
            : ''}
          <button class="mob-strat-logs-btn" onclick="window._mobShowStratLogs('${s.type}')">Logs</button>
        </div>
        ${_insts.length ? `<div style="margin-top:12px;display:flex;flex-direction:column;gap:7px">
          <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.06em">Running instances</div>
          ${_insts.map(i => {
            const paused = !!serverStatus?._paused?.[`${s.type}:${i}`]
            const sb = 'padding:5px 8px;border-radius:7px;font-size:11px;font-weight:700;cursor:pointer;touch-action:manipulation;white-space:nowrap'
            const pr = paused
              ? `<button onclick="window.resumeStrategyMob('${s.type}','${esc(i)}')" style="${sb};border:1px solid var(--green);background:transparent;color:var(--green)">▶ Resume</button>`
              : `<button onclick="window.pauseStrategyMob('${s.type}','${esc(i)}')" style="${sb};border:1px solid var(--orange);background:transparent;color:var(--orange)">⏸ Pause</button>`
            return `
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:9px 12px;border:1px solid var(--border2);border-radius:10px;background:var(--panel-2)">
            <span style="width:8px;height:8px;border-radius:50%;background:${paused ? 'var(--orange)' : 'var(--green)'};flex-shrink:0"></span>
            <span style="font-size:13px;font-weight:700">${esc(i || 'default')}${paused ? ' <span style="font-size:10px;color:var(--orange);font-weight:600">paused</span>' : ''}</span>
            <span style="flex:1"></span>
            ${(s.type === 'grid' || s.type === 'accumulator') ? `<button onclick="window._mobEditStratInstance('${s.type}','${esc(i)}')" style="${sb};border:1px solid var(--accent);background:transparent;color:var(--accent)">✎ Edit</button>` : ''}
            <button onclick="window.restartStrategyMob('${s.type}','${esc(i)}',this)" style="${sb};border:1px solid var(--accent);background:transparent;color:var(--accent)"><span style="display:inline-block">⟳</span> Restart</button>
            ${pr}
            <button onclick="window.stopStrategyMob('${s.type}','${esc(i)}')" style="${sb};border:none;background:var(--red);color:#fff">■ Stop</button>
            <button onclick="window._mobShowStratLogs('${s.type}','${esc(i)}')" style="${sb};border:1px solid var(--border2);background:transparent;color:var(--muted);font-weight:600">Logs</button>
          </div>`}).join('')}</div>` : ''}`
    }

    const meta = _STRAT_ABOUT[s.type]
    const tag  = meta ? meta.tag() : s.desc
    return `<div class="mob-strat-card${running ? ' mob-strat-running' : ''}${_stratFlipped.has(s.type) ? ' strat-flipped' : ''}" id="strat-card-${s.type}" style="--strat-accent:${meta?.accent || 'var(--accent)'}">
      <div class="strat-flip">
        <div class="strat-face strat-front">
          <div class="mob-strat-header" onclick="window._mobExpandStrat('${s.type}')">
            <span class="strat-badge">${meta?.icon || '🤖'}</span>
            <div style="flex:1;min-width:0">
              <div class="strat-name">${esc(s.label)}${running ? `<span class="strat-live"><i></i>${_T('Running', 'Activo')}</span>` : ''}</div>
              <div class="strat-tag">${running ? esc(_stratRunStatus(s.type)) : esc(tag)}</div>
            </div>
            ${meta ? `<button class="strat-info" title="${_T('What does this do?', '¿Qué hace esto?')}" aria-label="${_T('What does this do?', '¿Qué hace esto?')}"
              onclick="event.stopPropagation();window.__stratFlip('${s.type}',true)">?</button>` : ''}
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="color:var(--muted);flex-shrink:0;transform:rotate(${expanded ? 180 : 0}deg);transition:transform .2s"><polyline points="6 9 12 15 18 9"/></svg>
          </div>
        </div>
        ${meta ? `<div class="strat-face strat-back">
          <div class="strat-back-head">
            <span class="strat-badge">${meta.icon}</span>
            <span class="strat-name">${esc(s.label)}</span>
            <span style="flex:1"></span>
            <button class="strat-info" aria-label="${_T('Back', 'Volver')}" onclick="event.stopPropagation();window.__stratFlip('${s.type}',false)">&times;</button>
          </div>
          <p class="strat-about"><b>${_T('What it does', 'Qué hace')}</b> ${esc(meta.what())}</p>
          <p class="strat-about"><b>${_T('Why', 'Por qué')}</b> ${esc(meta.why())}</p>
          <p class="strat-about strat-risk"><b>${_T('Watch out', 'Cuidado')}</b> ${esc(meta.risk())}</p>
        </div>` : ''}
      </div>
      ${expanded ? `<div class="mob-strat-body">${bodyHtml}</div>` : ''}
    </div>`
  }).join('')

  const autoGenBtn = savedKey ? '' :
    `<button class="auto-gen-agent-btn" onclick="window.__quickConnectAgent()" style="width:100%;padding:10px;border-radius:9px;border:none;background:rgba(255,138,42,0.14);color:var(--accent);font-size:13px;font-weight:700;cursor:pointer">${isMainWalletConnected() ? '⚡ Auto-generate Agent Key' : '🔗 Connect wallet'}</button>`

  el.innerHTML = `<div style="padding:4px 0 80px">
    ${state.isAllAccounts ? `<div style="padding:2px 12px 10px">${_allAcctRunningHtml()}</div>` + _stratAcctPickerHtml() : ''}
    <div class="mob-v-setting-group" style="margin-bottom:14px">
      <div class="mob-v-setting-row" style="flex-direction:column;align-items:stretch;gap:8px">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <span style="font-size:13px;font-weight:600">Agent Key</span>
          <span style="flex:1"></span>
          ${_stratsWhyUnlocked()}${_stratsFullBtn()}${_stratsCloseBtn()}${serverBadge}
        </div>
        <div id="m-agentKeyStatus" style="font-size:11px">${agentStatus}</div>
        ${_hasKey ? `
          <!-- A key is already saved for this account and is what signs its closes. Asking
               for it again — nine times, once per wallet — was the complaint. Keep the
               controls, behind a disclosure. -->
          <details>
            <summary style="list-style:none;cursor:pointer;font-size:11px;color:var(--muted);padding:2px 0">${_T('Replace or clear this key', 'Reemplazar o borrar esta clave')} ▾</summary>
            <input type="password" id="m-agentKey" class="mob-strat-input" placeholder="0x private key…"
              value="${esc(savedKey)}"
              oninput="window.__saveAgentKey(this.value);const dk=document.getElementById('agentKey');if(dk)dk.value=this.value"
              autocomplete="off" style="font-family:monospace;font-size:12px;margin-top:6px">
            <div style="display:flex;gap:6px;margin-top:6px">
              <button onclick="window.__mobConnectAgentKey()" style="flex:1;padding:8px 0;border-radius:8px;border:none;background:var(--accent);color:#000;font-size:12px;font-weight:700;cursor:pointer">Connect</button>
              <button onclick="window.__clearAgentKey()" style="padding:8px 14px;border-radius:8px;border:1px solid var(--panel-3);background:transparent;color:var(--muted);font-size:12px;cursor:pointer">Clear</button>
            </div>
          </details>
        ` : `
          <input type="password" id="m-agentKey" class="mob-strat-input" placeholder="0x private key…"
            value=""
            oninput="window.__saveAgentKey(this.value);const dk=document.getElementById('agentKey');if(dk)dk.value=this.value"
            autocomplete="off" style="font-family:monospace;font-size:12px">
          <div style="display:flex;gap:6px">
            <button onclick="window.__mobConnectAgentKey()" style="flex:1;padding:8px 0;border-radius:8px;border:none;background:var(--accent);color:#000;font-size:12px;font-weight:700;cursor:pointer">Connect</button>
            <button onclick="window.__clearAgentKey()" style="padding:8px 14px;border-radius:8px;border:1px solid var(--panel-3);background:transparent;color:var(--muted);font-size:12px;cursor:pointer">Clear</button>
          </div>
          ${autoGenBtn}
        `}
      </div>
    </div>
    ${locked ? _subLockBanner() : ''}
    <div class="mob-v-setting-group">${cards}${devBotsLoad().map(_devBotCardHtml).join('')}</div>
    ${isDev() ? `<div style="padding:10px 12px 0">
      <button onclick="window.__openBotSubmissions()" style="width:100%;padding:9px;border-radius:9px;border:1px dashed var(--border2);background:transparent;color:var(--fg-2);font-size:12px;font-weight:700;cursor:pointer">${
        _T('Bot submissions', 'Bots enviados')}</button>
    </div>` : ''}
    <div style="padding:10px 12px 0">${_devBotsHtml()}</div>
  </div>`

  // Restore the snapshotted edits onto the freshly-rendered inputs (skip the agent key —
  // it already re-fills from storage via value=). Re-apply size-unit data-mode so the
  // TKN/USD choice survives, and re-focus the field the user was typing in.
  for (const [id, snap] of Object.entries(_preserved)) {
    if (id === 'm-agentKey') continue
    const node = el.querySelector('#' + (window.CSS?.escape ? CSS.escape(id) : id))
    if (!node) continue
    if (snap.v != null && snap.v !== '') node.value = snap.v
    if (snap.mode != null) node.dataset.mode = snap.mode
  }
  if (_focusedId) {
    const f = el.querySelector('#' + (window.CSS?.escape ? CSS.escape(_focusedId) : _focusedId))
    if (f) { try { f.focus(); const n = f.value.length; f.setSelectionRange?.(n, n) } catch {} }
  }
}

function buildArgvMob(type) {
  const get = id => document.getElementById(id)?.value?.trim() ?? ''
  const argv = []
  const push = (f, v) => { if (v) argv.push(f, v) }

  if (type === 'accumulator') {
    push('--asset',     get('m-accum-asset')     || 'HYPE')
    push('--cut-pct',   get('m-accum-cut')       || '25')
    push('--threshold', get('m-accum-threshold') || '11')
    push('--max-daily', get('m-accum-maxdaily')  || '0')
    if (_mobAccumDryRun) argv.push('--dry-run')
  } else if (type === 'dca') {
    push('--coin',         get('m-dca-coin')      || 'BTC')
    push('--side',         _mobDcaSide)
    push('--size',         getSizeUsd('m-dca-size', 'm-dca-coin') || '100')
    push('--mode',         _mobDcaMode)
    push('--interval',     get('m-dca-interval')  || (_mobDcaMode === 'drop' ? '5' : '60'))
    if (_mobDcaMode === 'drop') push('--drop-pct', get('m-dca-droppct') || '2')
    push('--max-orders',   get('m-dca-maxorders') || '10')
    push('--max-position', get('m-dca-maxpos')    || '0')
    push('--leverage',     get('m-dca-leverage')  || '1')
  } else if (type === 'grid') {
    const _mCoin = _resolveGridCoin(get('m-grid-coin') || state.selectedCoin || 'BTC')
    const lower  = _gridRangeToPrice(get('m-grid-lower'), _mCoin)   // '' = bot auto-ranges
    const upper  = _gridRangeToPrice(get('m-grid-upper'), _mCoin)
    const levVal = parseFloat(get('m-grid-levels') || '10')
    push('--coin',  _mCoin)
    if (_gridSide === 'short') push('--side', 'short')
    push('--lower', lower)
    push('--upper', upper)
    if (_mobGridSpacing !== 'usd') push('--pct-interval', String(levVal))
    else                           push('--levels',       String(levVal))
    push('--size',      getSizeUsd('m-grid-size', 'm-grid-coin'))   // empty = auto-size from balance
    push('--leverage',  get('m-grid-leverage') || '10')
    if (_gridMargin === 'isolated') push('--margin', 'isolated')
    push('--total-margin', get('m-grid-totmargin'))   // per-position margin cap — works in cross or isolated
    const mEntryGap = get('m-grid-entry-gap')
    if (mEntryGap) push('--entry-gap', mEntryGap)
  } else if (type === 'trend') {
    push('--coin',          get('m-trend-coin')     || 'BTC')
    push('--fast-ema',      get('m-trend-fast')     || '9')
    push('--slow-ema',      get('m-trend-slow')     || '21')
    push('--candle-tf',     get('m-trend-tf')       || '1h')
    push('--size',          getSizeUsd('m-trend-size', 'm-trend-coin') || '500')
    push('--leverage',      get('m-trend-leverage') || '3')
    push('--interval',      get('m-trend-interval') || '5')
    push('--stop-loss-pct', get('m-trend-stoploss') || '0')
  } else if (type === 'longer') {
    push('--coins',           get('m-longer-coins')    || 'BTC')
    push('--size',            getSizeUsd('m-longer-size', 'm-longer-coins') || '100')
    push('--leverage',        get('m-longer-leverage') || '2')
    push('--trigger',         _mobLongerTrigger)
    if (_mobLongerTrigger === 'dump') {
      push('--dump-pct',    get('m-longer-dumppct')    || '7')
      push('--dump-window', get('m-longer-dumpwindow') || '1d')
    }
    push('--take-profit-pct', get('m-longer-tp') || '3')
    push('--stop-loss-pct',   get('m-longer-sl') || '2')
    push('--interval',        get('m-longer-interval') || '5')
  } else if (type === 'shorter') {
    push('--coins',           get('m-shorter-coins')    || 'BTC')
    push('--size',            getSizeUsd('m-shorter-size', 'm-shorter-coins') || '100')
    push('--leverage',        get('m-shorter-leverage') || '2')
    push('--trigger',         _mobShorterTrigger)
    if (_mobShorterTrigger === 'pump') {
      push('--pump-pct',    get('m-shorter-pumppct')    || '7')
      push('--pump-window', get('m-shorter-pumpwindow') || '1d')
    }
    push('--take-profit-pct', get('m-shorter-tp') || '3')
    push('--stop-loss-pct',   get('m-shorter-sl') || '2')
    push('--interval',        get('m-shorter-interval') || '5')
  }
  return argv
}

// Which wallet a strategy is armed on.
//
// Everything else in the combined view already routes per account — orders, closes,
// cancels, margin all take an `acct` and use that wallet's agent key. Strategies were the
// only holdout, and only because runStrategyMob read state.addr, which is
// "__all_accounts__" there and matches no key. The restriction was historical, not
// structural, so this reuses the SAME selection the trade tab uses rather than introducing
// a second "which account" concept for the user to keep in sync.
function _stratTargetAddr() {
  return state.isAllAccounts ? (window.__getTradeAcct?.() ?? null) : state.addr
}

function _stratTargetKey() {
  const a = _stratTargetAddr()
  return a ? localStorage.getItem(_agentKeyForAddr(a)) : null
}

async function runStrategyMob(type) {
  // Copy trade is armed against a person, not a coin, so it has its own sheet — reached
  // from a leaderboard row, or from here with the address left blank.
  if (type === 'copytrade') { window.__lbCopyTrade(''); return }
  const _target = _stratTargetAddr()
  if (!_target) {
    alert(state.isAllAccounts
      ? 'Pick which account to run this bot on first.'
      : 'Load a wallet address first.')
    return
  }
  // The paper account never reaches the server: no agent key exists for it, and its
  // address is a sentinel HL has never heard of.
  if (isPaper()) {
    await ensureAllMids()
    if (window.__paperBotStart(type)) { checkServer(); _mobVRenderContent() }
    return
  }
  const agentKey = _stratTargetKey()
                || document.getElementById('m-agentKey')?.value?.trim()
                || document.getElementById('agentKey')?.value?.trim()
  if (!agentKey) { alert('Enter your Agent Private Key above.'); return }
  await ensureAllMids()
  const argv = buildArgvMob(type)
  try {
    const r = await serverFetch('/api/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, agentKey, args: argv, address: _target, instance: _argvInstance(argv) }),
    })
    if (!r.ok) {
      // The server enforces the paywall; a client reaching here has a stale gate.
      if (r.subscribe) {
        _subRefresh(true)
        // In dev mode the server should have accepted the PIN. Getting here means we do not
        // hold one — dev mode was enabled in a session before it was cached, or it was
        // cleared. Say that, rather than asking the owner to buy their own product.
        _paperToast(isDev()
          ? _T('Dev mode has no saved PIN — turn Dev Mode off and on to re-enter it', 'El modo dev no tiene PIN guardado — apaga y enciende Modo Dev para reintroducirlo')
          : _T('Subscription required to run strategies', 'Se requiere suscripción para usar estrategias'), 'err')
        return
      }
      alert(`Could not start: ${r.error}`); return
    }
    serverStatus[type] = true
    updateAllStrategyButtons()
    _verifyStarted(type, _argvInstance(argv))
  } catch { alert('Server unreachable. Is hliq-strat running?') }
}

// Bots validate config (min order size, margin) right after spawn, but the
// strat server may reply "ok" before that. Re-check a few seconds later and
// surface the silent death instead of leaving the user staring at nothing.
function _verifyStarted(type, instance) {
  setTimeout(async () => {
    try {
      await checkServer()   // refreshes serverStatus, buttons, mobile strategies tab
      const alive = instance ? !!serverStatus?._instances?.[`${type}:${instance}`] : !!serverStatus?.[type]
      if (!alive) alert(`The ${type} bot${instance ? ' (' + instance + ')' : ''} exited right after starting.\n\nOpen its Logs for the exact reason — most common: capital too low for Hyperliquid's $10 minimum order size, or no free margin (other bots' orders reserve margin).`)
    } catch {}
  }, 5000)
}

async function stopStrategyMob(type, instance) {
  try {
    if (instance !== undefined) {
      await _postStop(type, instance)
      if (serverStatus._instances) delete serverStatus._instances[`${type}:${instance}`]
      if (!_typeInstances(type).length) serverStatus[type] = false
    } else {
      const insts = _typeInstances(type)
      for (const i of (insts.length ? insts : [''])) await _postStop(type, i)
      serverStatus[type] = false
    }
    checkServer()
    updateAllStrategyButtons()
    if (typeof _mobVActiveTab !== 'undefined' && _mobVActiveTab === 'strategies') _mobVRenderContent()
  } catch { alert('Server unreachable.') }
}

async function _mobShowStratLogs(type, inst = '', addrOverride = '') {
  const labels = { dca: 'DCA', grid: 'Grid', trend: 'Trend', longer: 'Longer', shorter: 'Shorter', accumulator: '🪙 Profit Stack', liqguard: '🛡 Liq Guard', levbrake: '🛑 Lev Brake' }
  let overlay = document.getElementById('mobStratLogOverlay')
  if (!overlay) {
    overlay = document.createElement('div')
    overlay.id = 'mobStratLogOverlay'
    overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:var(--bg);display:flex;flex-direction:column'
    document.body.appendChild(overlay)
  }
  overlay.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px;padding:16px 16px 12px;border-bottom:1px solid var(--border);flex-shrink:0">
      <button onclick="document.getElementById('mobStratLogOverlay').style.display='none'"
        style="background:none;border:none;color:var(--fg);font-size:22px;padding:0;line-height:1;cursor:pointer">✕</button>
      <span style="font-size:15px;font-weight:700">${labels[type] || type}${inst ? ' · ' + inst : ''} — Live Logs</span>
      <span id="mob-log-stopped" style="display:none;margin-left:auto;font-size:11px;padding:2px 8px;border-radius:10px;background:var(--red);color:#fff">Stopped</span>
    </div>
    <div id="mobStratLogOut" style="flex:1;overflow-y:auto;padding:12px 14px;font-size:11px;font-family:'JetBrains Mono',monospace;line-height:1.65;white-space:pre-wrap;word-break:break-all"></div>`
  overlay.style.display = 'flex'

  if (_mobLogStream) { _mobLogStream.close(); _mobLogStream = null }
  const out  = document.getElementById('mobStratLogOut')
  const addr = addrOverride || state.addr || ''   // combined view passes the owning account
  const token = await _ensureBotToken(addr)   // owner-gated logs need a session token
  const authHdr = token ? { Authorization: 'Bearer ' + token } : {}

  // Load today's log file from disk first, then attach SSE for live tail
  const today = (inst ? inst.toUpperCase() + '-' : '') + new Date().toISOString().slice(0, 10) + '.log'
  fetch(`/api/history/${type}/${today}?address=${encodeURIComponent(addr)}`, { headers: authHdr })
    .then(r => r.ok ? r.text() : null).catch(() => null)
    .then(text => {
      if (text) {
        text.split('\n').filter(Boolean).forEach(line => {
          const color = line.includes('[WIN') ? '#22c55e' : line.includes('[ERROR') ? '#ef4444' : line.includes('[PLACE') ? '#60a5fa' : null
          _appendMobLog(out, line, color)
        })
        _appendMobLog(out, '─── live ───', '#6b7280')
      }
    })

  const es = new EventSource(`/api/logs/${type}?address=${encodeURIComponent(addr)}&instance=${encodeURIComponent(inst)}${token ? '&token=' + encodeURIComponent(token) : ''}`)
  _mobLogStream = es
  es.onmessage = e => {
    const d = JSON.parse(e.data)
    if (d.exit !== undefined) {
      serverStatus[type] = false
      updateAllStrategyButtons()
      const b = document.getElementById('mob-log-stopped')
      if (b) b.style.display = 'inline'
      _appendMobLog(out, `[process exited — code ${d.exit}]`, '#ef4444')
      return
    }
    const color = d.line.includes('[WIN') ? '#22c55e' : d.line.includes('[ERROR') ? '#ef4444' : d.line.includes('[PLACE') ? '#60a5fa' : null
    _appendMobLog(out, d.line, color)
  }
  es.onerror = () => _appendMobLog(out, '[connection lost]', '#ef4444')
}

function _appendMobLog(container, text, color) {
  const div = document.createElement('div')
  div.textContent = _logLineLocal(text)
  if (color) div.style.color = color
  container.appendChild(div)
  container.scrollTop = container.scrollHeight
}

window.runStrategyMob      = runStrategyMob
window.updateStrategyMob   = updateStrategyMob
window._mobEditStratInstance = _mobEditStratInstance
window._mobCancelEdit      = _mobCancelEdit
window.stopStrategyMob     = stopStrategyMob
window._mobExpandStrat     = _mobExpandStrat
window._mobToggleGridSpacing   = _mobToggleGridSpacing
window._mobToggleDcaMode       = _mobToggleDcaMode
window._mobToggleDcaSide       = _mobToggleDcaSide
window._mobToggleLongerTrigger = _mobToggleLongerTrigger
window._mobToggleShorterTrigger = _mobToggleShorterTrigger
window._mobToggleSizeMode      = _mobToggleSizeMode
window._mobShowStratLogs       = _mobShowStratLogs

// Open the live log viewer for the guard currently shown in the guard modal. The guard's
// log instance is its uppercased coin (matches the server's per-instance log filenames).
window.__guardShowLogs = function () {
  const g = state.guardCfg
  if (!g) return
  _mobShowStratLogs(g.mode, String(g.coin).toUpperCase())
}

// ─── STRATEGY SERVER INTEGRATION ──────────────────────────────────────────────
let serverOnline  = false
let serverStatus  = {}          // { insolvent: bool, dca: bool, ... }
const logStreams   = {}          // type → EventSource

// ─── BOT-SERVER AUTH ──────────────────────────────────────────────────────────
// The bot-control API is owner-gated: mutations and log reads require a session token
// proving control of the account's agent key. We obtain one by signing a server nonce
// with the agent key held in localStorage — silent, no wallet popup. Tokens are cached
// per account until they near expiry.
const _botTokens = {}   // addrLower -> { token, exp }

function _botAgentKeyFor(address) {
  if (!address) return null
  return localStorage.getItem(_agentKeyForAddr(address))   // strictly this account's own key
}

async function _ensureBotToken(address) {
  if (!address) return null
  const key    = address.toLowerCase()
  const cached = _botTokens[key]
  if (cached && cached.exp - 60_000 > Date.now()) return cached.token
  const agentKey = _botAgentKeyFor(address)
  if (!agentKey) return null           // watch-only for this account — can't authenticate
  try {
    const { nonce } = await (await fetch('/api/auth/nonce')).json()
    if (!nonce) return null
    const msg = `Insolvent Trade — bot control login\nAccount: ${key}\nNonce: ${nonce}`
    const signature = await signWithAgentKey(agentKey, msg)
    const r = await fetch('/api/auth/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address, nonce, signature }),
    })
    const j = await r.json()
    if (j.token) { _botTokens[key] = { token: j.token, exp: j.exp ?? (Date.now() + 11 * 3600_000) }; return j.token }
  } catch { /* server unreachable / no key — fall through unauthenticated */ }
  return null
}

// Best-effort: pull the account this request concerns from an explicit opt, the query
// string, or the JSON body, so a token can be attached without touching every call site.
function _botReqAddr(path, opts) {
  if (opts.authAddr) return opts.authAddr
  const q = path.split('?')[1]
  if (q) { const m = new URLSearchParams(q).get('address'); if (m) return m }
  if (typeof opts.body === 'string') { try { const a = JSON.parse(opts.body).address; if (a) return a } catch {} }
  return null
}

// Return a token for the given account, for callers that build their own URL (SSE).
async function _botTokenParam(address) {
  const t = await _ensureBotToken(address)
  return t ? '&token=' + encodeURIComponent(t) : ''
}

/**
 * The bot API is keyed by a real on-chain address and owner-gated. The All Accounts
 * and Paper sentinels are not addresses, so any request carrying one is rejected 401
 * — and because these run on a refresh loop it produced a stream of failures in the
 * console. Callers use this to skip the request entirely instead.
 */
function _botApiAddr() {
  const a = state.addr ?? ''
  return /^0x[0-9a-fA-F]{40}$/.test(a) ? a : null
}

async function serverFetch(path, opts = {}) {
  const addr = _botReqAddr(path, opts)
  if (addr) {
    const tok = await _ensureBotToken(addr)
    if (tok) opts = { ...opts, headers: { ...(opts.headers ?? {}), Authorization: 'Bearer ' + tok } }
  }
  // Dev mode is a local flag; the server only recognises the PIN that earned it. Send it on
  // the one route that checks it, so the unlocked Run button and the server actually agree.
  if (path === '/api/start' && isDev()) {
    const pin = _lbGetPin()
    if (pin) opts = { ...opts, headers: { ...(opts.headers ?? {}), 'x-lb-pin': pin } }
  }
  const r = await fetch(path, opts)
  const ct = r.headers.get('content-type') ?? ''
  if (ct.includes('application/json')) return r.json()
  const txt = await r.text()
  return { ok: false, error: txt.trim() || 'Strategy server unreachable' }
}

let _lastStatusHash = ''
async function checkServer() {
  if (!state.addr) return
  // Paper has no server process to poll; its bots are in localStorage. Synthesising the
  // same shape here is what makes the Strats UI show Running / Stop without every call
  // site needing to know where the bot actually lives.
  if (isPaper()) {
    const bots = _paperBotsLoad()
    serverStatus = { ok: true, _configs: {} }
    for (const [t, cfg] of Object.entries(bots)) {
      serverStatus[t] = true
      serverStatus._configs[`${t}:`] = { args: ['--coin', cfg.coin] }
    }
    serverOnline = true
    updateAllStrategyButtons()
    return
  }
  try {
    serverStatus = await serverFetch(`/api/status?address=${encodeURIComponent(_botApiAddr() ?? state.addr)}`)
    const justCameOnline = !serverOnline
    serverOnline = true
    updateServerBadge()
    updateAllStrategyButtons()
    // Mobile strategies tab renders from serverStatus — refresh it when the
    // running set changes (e.g. a bot was started/stopped from another device)
    const _sh = JSON.stringify(serverStatus)
    if (_sh !== _lastStatusHash) {
      _lastStatusHash = _sh
      if (typeof _mobVActiveTab !== 'undefined' && _mobVActiveTab === 'strategies') {
        try { _mobVRenderContent() } catch {}
      }
    }
    if (justCameOnline) {
      // Inject Run/Stop into any command outputs already on screen
      for (const type of ['insolvent','dca','grid','trend','longer','shorter']) {
        const outputEl = document.getElementById('cmd-' + type)
        if (outputEl && outputEl.innerHTML.trim() && !document.getElementById('run-btn-' + type)) {
          injectRunButtons(type)
        }
      }
      renderWinsPanel()
    }
  } catch {
    if (serverOnline) {
      serverOnline = false
      updateServerBadge()
      updateAllStrategyButtons()
    }
  }
}

function updateServerBadge() {
  const el = document.getElementById('serverBadge')
  if (!el) return
  el.textContent   = serverOnline ? '● Server connected' : '○ Server offline'
  el.className     = 'server-badge ' + (serverOnline ? 'server-online' : 'server-offline')
}

// ── Inject Run/Stop row into a strategy command output area ──────────────────
let _deskDevSig = ''

function updateAllStrategyButtons() {
  // The desktop panel has no render pass of its own, so this poll is where it learns the
  // subscription state. Throttled inside _subRefresh, so calling it here is cheap.
  _subRefresh()

  // Device bots, on desktop. Same two renderers the mobile tab uses, so the two layouts
  // cannot drift. Two guards, because this is a poll rather than an event: skip while the
  // focus is inside (an innerHTML swap would eat the keystroke), and skip when nothing
  // changed (it would close an open <details> and drop the caret every second otherwise).
  const dvHost = document.getElementById('deskDevBots')
  if (dvHost && !dvHost.contains(document.activeElement)) {
    const html = devBotsLoad().map(_devBotCardHtml).join('') + _devBotsHtml()
    if (html !== _deskDevSig) { _deskDevSig = html; dvHost.innerHTML = html }
  }
  const labels  = { insolvent:'Insolvent', dca:'DCA', grid:'Grid', trend:'Trend', longer:'Longer', shorter:'Shorter' }
  const running = []
  for (const type of ['insolvent','dca','grid','trend','longer','shorter']) {
    const isRunning = !!serverStatus[type]

    // Desktop buttons
    const runBtn  = document.getElementById(`run-btn-${type}`)
    const stopBtn = document.getElementById(`stop-btn-${type}`)
    if (runBtn)  runBtn.style.display  = 'inline-block'   // always — allows starting another token
    if (stopBtn) stopBtn.style.display = isRunning ? 'inline-block' : 'none'
    // Ensure each card always has its Run/Stop row + instance list, even if the user
    // never clicked "Generate Command" — otherwise running bots have no visible controls.
    // Re-inject when the row is missing, and also when its lock state has gone stale —
    // otherwise activating a subscription leaves a "Subscribe to run" button sitting there
    // until the page is reloaded.
    const _row = document.getElementById(`cmd-${type}`)?.querySelector('.strategy-run-row')
    const _rowLocked = !!_row?.querySelector('.mob-strat-locked')
    if (serverOnline && _deskEditing?.type !== type && document.getElementById(`cmd-${type}`)
        && (!document.getElementById(`inst-list-${type}`) || (_row && _rowLocked === _stratsUnlocked()))) {
      _row?.remove()
      injectRunButtons(type)
    }
    const instList = document.getElementById(`inst-list-${type}`)
    if (instList) {
      const lb = 'background:none;border:none;cursor:pointer;padding:0;font-size:11px;font-weight:600'
      instList.innerHTML = _typeInstances(type).map(i => {
        const paused  = !!serverStatus?._paused?.[`${type}:${i}`]
        const dotCol  = paused ? 'var(--orange)' : 'var(--green)'
        const pauseBtn = paused
          ? `<button onclick="resumeStrategyMob('${type}','${esc(i)}')" title="Resume" style="${lb};color:var(--green)">▶ Resume</button>`
          : `<button onclick="pauseStrategyMob('${type}','${esc(i)}')" title="Pause" style="${lb};color:var(--orange)">⏸ Pause</button>`
        const editBtn = type === 'grid'
          ? `<button onclick="_deskEditStratInstance('${type}','${esc(i)}')" title="Edit" style="${lb};color:var(--accent)">✎ Edit</button>` : ''
        return `<span style="display:inline-flex;align-items:center;gap:8px;margin-left:8px;padding:3px 9px;border:1px solid var(--border2);border-radius:14px;font-size:11px"><span style="color:${dotCol}">●</span>${esc(i || 'default')}${paused ? ' <span style="color:var(--orange);font-size:10px;font-weight:600">paused</span>' : ''}${editBtn}<button onclick="restartInstance('${type}','${esc(i)}',this)" title="Restart" style="${lb};color:var(--accent)">⟳ Restart</button>${pauseBtn}<button onclick="stopInstance('${type}','${esc(i)}')" title="Stop" style="${lb};color:var(--red)">■ Stop</button><button onclick="showStrategyLogs('${type}','${esc(i)}')" style="${lb};color:var(--muted);font-weight:400">Logs</button></span>`
      }).join('')
    }
    const card = document.getElementById(`strat-${type === 'insolvent' ? 'manager' : type}`)
    if (card) card.classList.toggle('strategy-running', isRunning)

    // Mobile buttons (present when strategies tab is open)
    const mRunBtn  = document.getElementById(`m-run-btn-${type}`)
    const mStopBtn = document.getElementById(`m-stop-btn-${type}`)
    if (mRunBtn)  mRunBtn.style.display  = 'flex'   // always — allows starting another token
    if (mStopBtn) mStopBtn.style.display = isRunning ? 'flex' : 'none'
    // Refresh card border
    const mCard = mRunBtn?.closest?.('.mob-strat-card') || mStopBtn?.closest?.('.mob-strat-card')
    if (mCard) mCard.classList.toggle('mob-strat-running', isRunning)

    if (isRunning) {
      const insts = _typeInstances(type).filter(Boolean)
      running.push(labels[type] + (insts.length ? ` (${insts.join(', ')})` : ''))
    }
  }
  const statusEl = document.getElementById('runningBotsStatus')
  if (statusEl) {
    if (running.length) {
      statusEl.style.display = 'block'
      statusEl.innerHTML = `<span style="color:var(--green)">▶</span> Running: <strong style="color:var(--green)">${running.join(', ')}</strong>`
    } else {
      statusEl.style.display = 'none'
    }
  }
  // Mobile Strats tab badge — count only trading-strategy bots, NOT the per-position
  // risk guards (liqguard/levbrake), which are managed from the position rows.
  // Skip in the combined view: there this badge is driven by _updateMobTabCounts from the
  // all-accounts poll, and serverStatus here is a single account's — writing it would zero
  // the combined count (the badge flickering in and out).
  const mobStrat = document.getElementById('mobStratCount')
  if (mobStrat && !state.isAllAccounts) {
    const isGuard = k => k.startsWith('liqguard:') || k.startsWith('levbrake:')
    const inst  = Object.keys(serverStatus?._instances ?? {}).filter(k => !isGuard(k)).length
    const count = inst || Object.keys(serverStatus ?? {}).filter(k => k !== '_instances' && k !== '_paused' && k !== '_guards' && k !== 'liqguard' && k !== 'levbrake' && serverStatus[k] === true).length
    mobStrat.textContent = count
    mobStrat.style.display = count > 0 ? '' : 'none'
  }
}

// Called by generateCommand after it sets innerHTML — injects run/stop buttons
function injectRunButtons(type) {
  if (!serverOnline) return
  const outputEl = document.getElementById('cmd-' + type)
  if (!outputEl) return
  const running = !!serverStatus[type]

  const div = document.createElement('div')
  div.className = 'strategy-run-row'
  // Same rule as the mobile tab: the card and its config stay usable, only the control
  // that calls /api/start is locked. Without this the desktop panel would let someone
  // fill the whole form and then hand them a raw 402.
  const locked = !_stratsUnlocked()
  div.innerHTML = `
    ${locked
      ? `<button class="mob-strat-locked" style="display:inline-flex;flex:0 0 auto;padding:8px 14px" onclick="window.__subOpenPaywall()">🔒 ${_T('Subscribe to run', 'Suscríbete para usar')}</button>`
      : `<button class="btn-run-strategy"  id="run-btn-${type}"
      style="display:inline-block"
      onclick="runStrategy('${type}')">▶ Run</button>`}
    <button class="btn-stop-strategy" id="stop-btn-${type}"
      style="display:${running ? 'inline-block' : 'none'}"
      onclick="stopStrategy('${type}')">■ Stop All</button>
    ${PREVIEWABLE.has(type) ? `<button class="btn-show-logs" title="${_T('See what it would do, without doing it', 'Ver qué haría, sin hacerlo')}"
      onclick="window.__botPreview('${type}')">👁 ${_T('Preview', 'Vista previa')}</button>` : ''}
    <button class="btn-show-logs" onclick="showStrategyLogs('${type}')">Logs</button>
    <span id="inst-list-${type}"></span>`
  outputEl.appendChild(div)
}

// ── Build argv from the current input values ─────────────────────────────────
function buildArgv(type) {
  const get = id => document.getElementById(id)?.value?.trim() ?? ''
  const longAssets  = (document.getElementById('longAssets')?.value  ?? '').split(',').map(s => s.trim()).filter(Boolean).join(',')
  const shortAssets = (document.getElementById('shortAssets')?.value ?? '').split(',').map(s => s.trim()).filter(Boolean).join(',')

  const argv = []
  const push = (flag, val) => { if (val) { argv.push(flag, val) } }

  if (type === 'insolvent') {
    push('--max-capital-pct', get('mgr-capital')   || '30')
    push('--short-zone-pct',  get('mgr-shortzone') || '0.5')
    push('--long-zone-pct',   get('mgr-longzone')  || '0.5')
    push('--interval',        get('mgr-interval')  || '5')
    if (longAssets)  argv.push('--long-assets',  longAssets)
    if (shortAssets) argv.push('--short-assets', shortAssets)
  } else if (type === 'dca') {
    const dcaMode = get('dca-mode') || 'time'
    push('--coin',         get('dca-coin')      || 'BTC')
    push('--side',         get('dca-side')      || 'long')
    push('--size',         getSizeUsd('dca-size', 'dca-coin') || '100')
    push('--mode',         dcaMode)
    push('--interval',     get('dca-interval') || (dcaMode === 'drop' ? '5' : '60'))
    if (dcaMode === 'drop') push('--drop-pct', get('dca-droppct') || '2')
    push('--max-orders',   get('dca-maxorders') || '10')
    push('--max-position', get('dca-maxpos')    || '0')
    push('--leverage',     get('dca-leverage')  || '1')
  } else if (type === 'grid') {
    const _gCoin  = _resolveGridCoin(get('grid-coin') || state.selectedCoin || 'BTC')
    const gLower  = _gridRangeToPrice(get('grid-lower'), _gCoin)   // '' = bot auto-ranges
    const gUpper  = _gridRangeToPrice(get('grid-upper'), _gCoin)
    const gLevVal = parseFloat(get('grid-levels') || '10')
    push('--coin',     _gCoin)
    if (_gridSide === 'short') push('--side', 'short')
    push('--lower',    gLower)
    push('--upper',    gUpper)
    if (_gridSpacing !== 'usd') {
      push('--pct-interval', String(gLevVal))
    } else {
      push('--levels', String(gLevVal))
    }
    push('--size',      getSizeUsd('grid-size',  'grid-coin'))   // empty = auto-size from balance
    push('--leverage',  get('grid-leverage') || '10')
    if (_gridMargin === 'isolated') push('--margin', 'isolated')
    push('--total-margin', get('grid-totmargin'))   // per-position margin cap — works in cross or isolated
    const gEntryGap = get('grid-entry-gap')
    if (gEntryGap) push('--entry-gap', gEntryGap)
  } else if (type === 'trend') {
    push('--coin',      get('trend-coin')     || 'BTC')
    push('--fast-ema',       get('trend-fast')      || '9')
    push('--slow-ema',       get('trend-slow')      || '21')
    push('--candle-tf',      get('trend-tf')        || '1h')
    push('--size',           getSizeUsd('trend-size', 'trend-coin') || '500')
    push('--leverage',       get('trend-leverage')  || '3')
    push('--interval',       get('trend-interval')  || '5')
    push('--stop-loss-pct',  get('trend-stoploss')  || '0')
  } else if (type === 'longer') {
    const trigger = get('longer-trigger') || 'always'
    push('--coins',            get('longer-coins')    || 'BTC')
    push('--size',             getSizeUsd('longer-size', 'longer-coins') || '100')
    push('--leverage',         get('longer-leverage') || '2')
    push('--trigger',          trigger)
    if (trigger === 'dump') {
      push('--dump-pct',    get('longer-dumppct')    || '7')
      push('--dump-window', get('longer-dumpwindow') || '1d')
    }
    push('--take-profit-pct',  get('longer-tp')       || '3')
    push('--stop-loss-pct',    get('longer-sl')       || '2')
    push('--interval',         get('longer-interval') || '5')
  } else if (type === 'shorter') {
    const trigger = get('shorter-trigger') || 'always'
    push('--coins',            get('shorter-coins')    || 'BTC')
    push('--size',             getSizeUsd('shorter-size', 'shorter-coins') || '100')
    push('--leverage',         get('shorter-leverage') || '2')
    push('--trigger',          trigger)
    if (trigger === 'pump') {
      push('--pump-pct',    get('shorter-pumppct')    || '7')
      push('--pump-window', get('shorter-pumpwindow') || '1d')
    }
    push('--take-profit-pct',  get('shorter-tp')       || '3')
    push('--stop-loss-pct',    get('shorter-sl')       || '2')
    push('--interval',         get('shorter-interval') || '5')
  } else if (type === 'custom') {
    const coin = get('custom-coin'); const lev = get('custom-leverage')
    const extra = get('custom-args')
    if (coin)  argv.push('--coin', coin)
    if (lev)   argv.push('--leverage', lev)
    // extra args are raw string — split and push
    if (extra) extra.split(/\s+/).filter(Boolean).forEach(a => argv.push(a))
  }
  return argv
}

async function runStrategy(type) {
  // Paper has no agent key and a sentinel address, exactly as on mobile — without this the
  // desktop Run button demanded a key the practice account can never have.
  if (isPaper()) {
    await ensureAllMids()
    if (window.__paperBotStart(type)) { checkServer(); updateAllStrategyButtons() }
    return
  }
  const agentKey = (state.addr ? localStorage.getItem(_agentKeyForAddr(state.addr)) : null)
                || document.getElementById('agentKey')?.value?.trim()
  if (!agentKey) { alert('Enter your Agent Private Key in the Strategies tab before running.'); return }
  if (!state.addr) { alert('Load a wallet address before running a strategy.'); return }
  await ensureAllMids()
  const argv = buildArgv(type)
  const script = type === 'custom'
    ? (document.getElementById('custom-script')?.value?.trim() || null)
    : null
  try {
    const r = await serverFetch('/api/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, agentKey, args: argv, script, address: state.addr, instance: _argvInstance(argv) }),
    })
    if (!r.ok) {
      // The server enforces the paywall; a client reaching here has a stale gate.
      if (r.subscribe) {
        _subRefresh(true)
        // In dev mode the server should have accepted the PIN. Getting here means we do not
        // hold one — dev mode was enabled in a session before it was cached, or it was
        // cleared. Say that, rather than asking the owner to buy their own product.
        _paperToast(isDev()
          ? _T('Dev mode has no saved PIN — turn Dev Mode off and on to re-enter it', 'El modo dev no tiene PIN guardado — apaga y enciende Modo Dev para reintroducirlo')
          : _T('Subscription required to run strategies', 'Se requiere suscripción para usar estrategias'), 'err')
        return
      }
      alert(`Could not start: ${r.error}`); return
    }
    serverStatus[type] = true
    updateAllStrategyButtons()
    renderWinsPanel()
    _verifyStarted(type, _argvInstance(argv))
  } catch (e) {
    alert('Server unreachable. Is server.js running?')
  }
}

// Instance = the coin a bot runs on; '' for multi-coin bots. One address can
// run the same bot type on several coins simultaneously.
function _argvInstance(argv) {
  const i = argv.indexOf('--coin')
  return i >= 0 && argv[i + 1] ? String(argv[i + 1]).toUpperCase() : ''
}

// Normalize a grid coin to its full "dex:SYM" form so typing "SPCX" and "xyz:SPCX"
// resolve to the SAME market — same --coin, same instance key — so the server refuses
// a duplicate instead of spawning a second bot on the same TradFi market.
function _resolveGridCoin(raw) {
  const c = String(raw || '').trim()
  if (!c || c.includes(':')) return c            // already a full dex:SYM (or empty)
  const up = c.toUpperCase()
  if (state.allMids?.[up] != null) return up      // a main-dex coin
  const hit = Object.keys(state.allMids || {}).find(k => k.includes(':') && k.split(':').pop().toUpperCase() === up)
  if (hit) return hit                             // HIP-3 full key
  // The name Hyperliquid SHOWS is not always the ticker it accepts: their UI lists io:GPRO
  // as GOPRO. Someone who read the name there and typed it here got "No price for GOPRO",
  // which is true and useless — the market exists, under a name they were never shown.
  const alias = _MKT_DISPLAY_REV[up]
  if (alias) {
    const aliasHit = Object.keys(state.allMids || {})
      .find(k => k.split(':').pop().toUpperCase() === alias)
    if (aliasHit) return aliasHit
  }
  return up                                       // leave as typed
}

function _typeInstances(type) {
  return Object.keys(serverStatus?._instances ?? {})
    .filter(k => k.startsWith(type + ':'))
    .map(k => k.slice(type.length + 1))
}

async function _postStop(type, instance, addr) {
  // Paper bots live in this browser, not on the server.
  if (isPaper()) { window.__paperBotStop(type); return }
  await serverFetch('/api/stop', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type, address: _isRealAddr(addr) ? addr : state.addr, instance }),
  })
}

// Restart a single running instance — server relaunches with its exact config.
async function restartInstance(type, instance, btn) {
  if (btn) {
    btn.disabled = true
    btn.dataset._t = btn.innerHTML
    btn.innerHTML = '<span style="display:inline-block;animation:spin .8s linear infinite">⟳</span> Restarting'
  }
  try {
    const r = await serverFetch('/api/restart', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, address: state.addr, instance: instance ?? '' }),
    })
    if (!r.ok) alert(`Could not restart: ${r.error}`)
    await checkServer()
    updateAllStrategyButtons()
    if (typeof _mobVActiveTab !== 'undefined' && _mobVActiveTab === 'strategies') _mobVRenderContent()
  } catch {
    alert('Server unreachable.')
    if (btn) { btn.disabled = false; btn.innerHTML = btn.dataset._t || '⟳ Restart' }
  }
}
window.restartInstance    = restartInstance
window.restartStrategyMob = (type, instance, btn) => restartInstance(type, instance, btn)

// Pause / resume a running instance — keeps the process + key alive (no key loss).
async function _pauseResumeInstance(action, type, instance, btn) {
  if (btn) { btn.disabled = true; btn.dataset._t = btn.textContent; btn.textContent = '…' }
  try {
    const r = await serverFetch(`/api/${action}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, address: state.addr, instance: instance ?? '' }),
    })
    if (!r.ok) alert(`Could not ${action}: ${r.error}`)
    await checkServer()
    updateAllStrategyButtons()
    if (typeof _mobVActiveTab !== 'undefined' && _mobVActiveTab === 'strategies') _mobVRenderContent()
  } catch {
    alert('Server unreachable.')
    if (btn) { btn.disabled = false; btn.textContent = btn.dataset._t }
  }
}
window.pauseStrategyMob  = (type, instance) => _pauseResumeInstance('pause',  type, instance)
window.resumeStrategyMob = (type, instance) => _pauseResumeInstance('resume', type, instance)

async function stopStrategy(type, instance) {
  try {
    if (instance !== undefined) {
      await _postStop(type, instance)
      if (serverStatus._instances) delete serverStatus._instances[`${type}:${instance}`]
      if (!_typeInstances(type).length) serverStatus[type] = false
    } else {
      // No instance given — stop every running instance of this type
      const insts = _typeInstances(type)
      for (const i of (insts.length ? insts : [''])) await _postStop(type, i)
      serverStatus[type] = false
    }
    checkServer()
    updateAllStrategyButtons()
  } catch (e) {
    alert('Server unreachable.')
  }
}
window.stopInstance = (type, inst) => stopStrategy(type, inst)

// ── Live log panel ────────────────────────────────────────────────────────────
async function showStrategyLogs(type, inst = '') {
  const panel  = document.getElementById('logPanel')
  const title  = document.getElementById('logPanelTitle')
  const output = document.getElementById('logPanelOutput')
  if (!panel || !title || !output) return

  _pastLogsType = type
  // Reset past logs bar when switching strategies
  const bar = document.getElementById('pastLogsBar')
  if (bar) bar.style.display = 'none'

  // Unsubscribe previous stream
  Object.keys(logStreams).forEach(t => { logStreams[t]?.close(); delete logStreams[t] })
  output.innerHTML = ''

  title.textContent = type.toUpperCase() + (inst ? ' · ' + inst : '') + ' — Live Logs'
  panel.style.display = 'flex'

  const _lAddr = _botApiAddr()
  if (!_lAddr) return   // sentinel account — no bot logs to stream
  const tokenParam = await _botTokenParam(_lAddr)   // owner-gated SSE
  const es = new EventSource(`/api/logs/${type}?address=${encodeURIComponent(_lAddr)}&instance=${encodeURIComponent(inst)}${tokenParam}`)
  logStreams[type] = es

  es.onmessage = e => {
    const data = JSON.parse(e.data)
    if (data.exit !== undefined) {
      appendLog(output, `[process exited — code ${data.exit}]`, 'log-exit')
      return
    }
    const cls = data.line.includes('[WIN') ? 'log-win'
              : data.line.includes('[ERROR') ? 'log-error'
              : data.line.includes('[ORDER') || data.line.includes('[LIMIT') ? 'log-order'
              : ''
    appendLog(output, data.line, cls)
    if (data.line.includes('[WIN')) renderWinsPanel()
  }
  es.onerror = () => appendLog(output, '[connection lost]', 'log-error')
}

function hideStrategyLogs() {
  const panel = document.getElementById('logPanel')
  if (panel) panel.style.display = 'none'
  Object.keys(logStreams).forEach(t => { logStreams[t]?.close(); delete logStreams[t] })
}

let _pastLogsType = null

async function togglePastLogs() {
  const bar    = document.getElementById('pastLogsBar')
  const select = document.getElementById('pastLogFile')
  if (!bar || !select || !_pastLogsType) return
  const showing = bar.style.display !== 'none'
  if (showing) { bar.style.display = 'none'; return }

  // Fetch file list for current log type
  try {
    const files = await serverFetch(`/api/history/${_pastLogsType}?address=${encodeURIComponent(_botApiAddr() || '')}`)
    select.innerHTML = '<option value="">— select a log file —</option>' +
      files.map(f => `<option value="${f}">${f}</option>`).join('')
    bar.style.display = 'block'
  } catch { bar.style.display = 'none' }
}

function colorLogLine(text) {
  if (text.includes('[WIN'))    return 'log-win'
  if (text.includes('[ERROR'))  return 'log-error'
  if (text.includes('[STOP'))   return 'log-error'
  if (text.includes('[ORDER') || text.includes('[LIMIT') || text.includes('[FILL') || text.includes('[PLACE')) return 'log-order'
  if (text.includes('[START') || text.includes('[REINIT') || text.includes('[DONE')) return 'log-info'
  return ''
}

async function loadPastLog(filename) {
  if (!filename || !_pastLogsType) return
  const output = document.getElementById('logPanelOutput')
  if (!output) return
  output.innerHTML = ''
  try {
    const text = await serverFetch(`/api/history/${_pastLogsType}/${filename}?address=${encodeURIComponent(_botApiAddr() || '')}`)
    const lines = (typeof text === 'string' ? text : JSON.stringify(text)).split('\n')
    for (const line of lines) {
      if (line) appendLog(output, line, colorLogLine(line))
    }
  } catch (e) {
    appendLog(output, `[error loading log: ${e.message}]`, 'log-error')
  }
}

// Bot logs are written server-side in UTC ("[2026-06-11 04:09:50]") —
// convert the leading timestamp to the device's local timezone for display.
function _logLineLocal(text) {
  return String(text).replace(/^\[(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})\]/, (_, Y, Mo, D, H, Mi, S) => {
    const d = new Date(Date.UTC(+Y, +Mo - 1, +D, +H, +Mi, +S))
    const p  = n => String(n).padStart(2, '0')
    const h12 = d.getHours() % 12 || 12
    const ap  = d.getHours() < 12 ? 'AM' : 'PM'
    return `[${p(d.getMonth() + 1)}/${p(d.getDate())} ${p(h12)}:${p(d.getMinutes())}:${p(d.getSeconds())} ${ap}]`
  })
}

function appendLog(container, text, cls = '') {
  const line = document.createElement('div')
  line.className = 'log-line' + (cls ? ' ' + cls : '')
  line.textContent = _logLineLocal(text)
  container.appendChild(line)
  container.scrollTop = container.scrollHeight
}

// ── Wins panel ────────────────────────────────────────────────────────────────
async function renderWinsPanel() {
  const el = document.getElementById('winsPanel')
  if (!el || !serverOnline) return

  const _wAddr = _botApiAddr()
  if (!_wAddr) return
  let wins
  try { wins = await serverFetch(`/api/wins?address=${encodeURIComponent(_wAddr)}`) }
  catch { return }

  const types    = ['insolvent','dca','grid','trend','longer','shorter']
  const labels   = { insolvent:'Insolvent', dca:'DCA Bot', grid:'Grid Bot', trend:'Trend Follower', longer:'Longer Bot', shorter:'Shorter Bot' }

  const sections = types.map(t => {
    const list = wins[t] ?? []
    if (!list.length) return ''
    const rows = list.slice(0, 20).map(w =>
      `<div class="win-row"><span class="win-ts">${w.ts}</span><span class="win-msg">${esc(w.msg)}</span></div>`
    ).join('')
    return `
      <div class="wins-strategy-block">
        <div class="wins-strategy-title">${labels[t]} <span class="wins-count">${list.length} win${list.length !== 1 ? 's' : ''}</span></div>
        ${rows}
      </div>`
  }).filter(Boolean).join('')

  el.innerHTML = sections || `<div style="font-size:11px;color:var(--muted)">No wins recorded yet. Wins appear here when strategies close profitable trades.</div>`
}

// Hook generateCommand to also inject run buttons
const _origGenerateCommand = window.generateCommand
window.generateCommand = function(type) {
  _origGenerateCommand(type)
  injectRunButtons(type)
}

// ─── FLIP CARD ────────────────────────────────────────────────────────────────
function flipCard(type) {
  const front = document.getElementById('front-' + type)
  const back  = document.getElementById('back-'  + type)
  if (!front || !back) return
  const showingFront = back.style.display === 'none'
  // Use '' to let the CSS class (display:flex) take over — never set 'block'
  front.style.display = showingFront ? 'none' : ''
  back.style.display  = showingFront ? '' : 'none'
  const visible = showingFront ? back : front
  visible.classList.remove('flip-anim')
  void visible.offsetWidth
  visible.classList.add('flip-anim')
}

// ─── SHORTER TP/SL PRICE SYNC ─────────────────────────────────────────────────
// which: 'tp' | 'sl'   changedField: 'pct' | 'px'
// For shorts: TP price is BELOW entry, SL price is ABOVE entry.
function syncShorterTpSl(which, changedField) {
  const coinRaw = (document.getElementById('shorter-coins')?.value?.split(',')[0]?.trim() || 'BTC').toUpperCase()
  const midPx   = parseFloat(state.allMids?.[coinRaw] ?? 0)

  const pctEl = document.getElementById(`shorter-${which}`)
  const pxEl  = document.getElementById(`shorter-${which}-px`)
  const refEl = document.getElementById(`shorter-${which}-ref`)
  if (!pctEl || !pxEl) return

  if (changedField === 'pct') {
    const pct = parseFloat(pctEl.value)
    if (!isNaN(pct) && midPx > 0) {
      const targetPx = which === 'tp'
        ? midPx * (1 - pct / 100)   // TP: price falls for profit
        : midPx * (1 + pct / 100)   // SL: price rises against us
      pxEl.value = targetPx.toFixed(targetPx >= 1000 ? 1 : targetPx >= 1 ? 2 : 4)
    } else {
      pxEl.value = ''
    }
  } else {
    const px = parseFloat(pxEl.value)
    if (!isNaN(px) && midPx > 0) {
      const calcPct = which === 'tp'
        ? (midPx - px) / midPx * 100   // how much below entry
        : (px - midPx) / midPx * 100   // how much above entry
      pctEl.value = Math.max(0, calcPct).toFixed(2)
    } else {
      pctEl.value = ''
    }
  }

  if (refEl) {
    if (midPx > 0) {
      refEl.textContent = `based on ${coinRaw} @ $${midPx.toLocaleString('en-US', { maximumFractionDigits: 2 })}`
    } else {
      refEl.textContent = `load a wallet to see live prices`
    }
  }
}

